pub fn check_native_window_access(scope: &mut v8::PinScope, window: v8::Local<v8::Object>) -> bool {
    let Some(context) = window.get_creation_context(scope) else {
        return false;
    };
    let Some(state) = context.get_slot::<V8BindingState>() else {
        return false;
    };
    global_events::check_window_access(scope, &state, window)
}

