pub fn set_native_window_location(
    scope: &mut v8::PinScope,
    context: v8::Local<v8::Context>,
    value: v8::Local<v8::Value>,
) {
    let Some(state) = context.get_slot::<V8BindingState>() else {
        throw_type_error(scope, "Window.location requires an active Window");
        return;
    };
    if state.execution_retired() {
        return;
    }
    if let Some(id) = state.location_object.get()
        && let Err(error) = location::set(scope, &state, id, "href", value)
    {
        throw_binding_error(scope, &error);
    }
}

/// Native task/message publication hook for cross-agent Window structure.
pub struct NativeWindowTreePublisher(pub fn(&mut v8::PinScope) -> Result<(), V8BindingError>);
pub fn publish_native_window_tree(scope: &mut v8::PinScope) -> Result<(), V8BindingError> {
    let callback = scope
        .get_slot::<NativeWindowTreePublisher>()
        .map(|publisher| publisher.0);
    if let Some(callback) = callback {
        callback(scope)?;
    }
    Ok(())
}

/// Invoke branded native Location behavior without reading authored members.
pub fn invoke_native_location_navigation<'s>(
    scope: &mut v8::PinScope<'s, '_>,
    args: v8::FunctionCallbackArguments<'s>,
    mut rv: v8::ReturnValue,
    replace: bool,
) {
    if args.length() < 1 {
        throw_type_error(scope, "Location operation requires a URL");
        return;
    }
    let receiver = args.this();
    if receiver.is_proxy() {
        throw_type_error(scope, "Location requires a Location receiver");
        return;
    }
    let Some(state) = binding_state_for_receiver(scope, receiver) else {
        throw_type_error(scope, "Location requires a Location receiver");
        return;
    };
    let Ok(id) = stateful_id(scope, receiver) else {
        throw_type_error(scope, "Location requires a Location receiver");
        return;
    };
    let result = if replace {
        location::operation(scope, &state, id, "replace", &args)
    } else {
        location::set(scope, &state, id, "href", args.get(0)).map(|()| None)
    };
    match result {
        Ok(Some(value)) => rv.set(value),
        Ok(None) => {}
        Err(error) => throw_binding_error(scope, &error),
    }
}

