/// The WebIDL global on which generated interface objects are installed.
/// Keeping exposure as generated data prevents Window-only APIs from leaking
/// into worker realms (and vice versa) as the worker bindings are migrated.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BindingGlobal {
    Window,
    Worker,
    AudioWorklet,
}

/// Parent-authenticated worker subtype; author globals cannot select exposure.
#[derive(Clone, Copy)]
pub struct WorkerExposureKind(pub crate::worker_wire::AgentKind);

fn exposed_on_global(
    exposed: &[&str],
    global: BindingGlobal,
    context: v8::Local<v8::Context>,
) -> bool {
    exposed.contains(&global.webidl_name())
        || (global == BindingGlobal::Worker
            && context
                .get_slot::<WorkerExposureKind>()
                .is_some_and(|kind| {
                    exposed.contains(&match kind.0 {
                        crate::worker_wire::AgentKind::Dedicated => "DedicatedWorker",
                        crate::worker_wire::AgentKind::Shared => "SharedWorker",
                        crate::worker_wire::AgentKind::Service => "ServiceWorker",
                        crate::worker_wire::AgentKind::AudioWorklet => "AudioWorklet",
                    })
                }))
}

impl BindingGlobal {
    const fn webidl_name(self) -> &'static str {
        match self {
            Self::Window => "Window",
            Self::Worker => "Worker",
            Self::AudioWorklet => "AudioWorklet",
        }
    }
}

/// A browser default action accepted by generated event dispatch and waiting
/// for the page orchestrator to perform navigation at the next scheduler
/// checkpoint. Bindings never perform network or page-group work directly.
pub enum PendingDefaultAction {
    Click(Box<submissions::RootedTarget>),
    Submit(Box<submissions::SubmissionTransaction>),
}

#[derive(Debug, thiserror::Error)]
pub enum V8BindingError {
    #[error("JavaScript argument conversion threw")]
    JavaScriptException,
    #[error("generated interface {0} is unavailable")]
    MissingInterface(&'static str),
    #[error("V8 failed to allocate {0}")]
    Allocation(&'static str),
    #[error("event callback failed: {0}")]
    EventCallback(String),
    #[error(transparent)]
    Binding(#[from] BindingError),
    #[error(transparent)]
    Dom(#[from] DomError),
    #[error("generated binding {interface}.{member} is not implemented")]
    Unsupported { interface: String, member: String },
    #[error("script preparation exceeded {resource}")]
    ScriptPreparationCapacity { resource: &'static str },
    #[error("{0}")]
    Message(String),
    #[error("document.write exceeded the configured {resource} limit")]
    DocumentWriteLimit { resource: &'static str },
}

