#[derive(Clone)]
struct BodyOwner {
    state: std::rc::Weak<V8BindingState>,
    wrapper: stream_graph::Owned<v8::Object>,
}
fn body_owner(
    state: &Rc<V8BindingState>,
    foreign: &Option<BodyOwner>,
) -> Result<Rc<V8BindingState>, V8BindingError> {
    match foreign {
        Some(owner) => owner
            .state
            .upgrade()
            .filter(|owner| !owner.execution_retired())
            .ok_or(V8BindingError::Allocation("body stream realm retired")),
        None => Ok(state.clone()),
    }
}
fn retain_body_owner(
    scope: &mut v8::PinScope,
    state: &Rc<V8BindingState>,
    owner: &Rc<V8BindingState>,
    id: u64,
) -> Result<Option<BodyOwner>, V8BindingError> {
    if Rc::ptr_eq(state, owner) {
        return Ok(None);
    }
    let wrapper = new_platform_object(scope, owner, "ReadableStream", id)?;
    Ok(Some(BodyOwner {
        state: Rc::downgrade(owner),
        wrapper: stream_graph::Owned::new(scope, wrapper),
    }))
}
fn input_body_stream(
    scope: &mut v8::PinScope,
    value: v8::Local<v8::Value>,
) -> Option<(Rc<V8BindingState>, u64)> {
    let object = v8::Local::<v8::Object>::try_from(value).ok()?;
    let owner = binding_state_for_receiver(scope, object)?;
    let id = stateful_id(scope, object).ok()?;
    let native = platform_object(&owner, id)
        .is_ok_and(|record| matches!(&*record, PlatformObjectRecord::ReadableStream(_)));
    native.then_some((owner, id))
}

#[derive(Clone)]
struct BodyStreamLease {
    owner: std::rc::Weak<V8BindingState>,
    // Keeps the stream wrapper alive until the asynchronous body lease ends.
    _wrapper: v8::Global<v8::Object>,
    id: u64,
}
impl BodyStreamLease {
    fn capture(
        scope: &mut v8::PinScope,
        owner: &Rc<V8BindingState>,
        id: u64,
    ) -> Result<Self, V8BindingError> {
        let wrapper = new_platform_object(scope, owner, "ReadableStream", id)?;
        Ok(Self {
            owner: Rc::downgrade(owner),
            _wrapper: v8::Global::new(scope, wrapper),
            id,
        })
    }
    fn owner(&self) -> Result<Rc<V8BindingState>, V8BindingError> {
        self.owner
            .upgrade()
            .filter(|owner| !owner.execution_retired())
            .ok_or(V8BindingError::Allocation("body source retired"))
    }
    fn cancel(
        &self,
        scope: &mut v8::PinScope,
        reason: v8::Local<v8::Value>,
    ) -> Result<(), V8BindingError> {
        let Some(owner) = self.owner.upgrade() else {
            return Ok(());
        };
        if owner.execution_retired() {
            return Ok(());
        }
        let context = owner
            .global_object
            .to_local(scope)
            .and_then(|global| global.get_creation_context(scope))
            .ok_or(V8BindingError::Allocation(
                "body cancellation source context",
            ))?;
        let scope = &mut v8::ContextScope::new(scope, context);
        service_worker_events::cancel_body(scope, &owner, self.id, reason)
    }
}

