struct DeferredDomTarget {
    dom: SharedDom,
    node: NodeId,
    document: NodeId,
    _lease: oryn_dom::TrackedNodeLease,
}

impl DeferredDomTarget {
    fn new(dom: &SharedDom, node: NodeId, document: NodeId) -> Result<Self, DomError> {
        let lease = oryn_dom::TrackedNodeLease::new(dom, node)?;
        // Admission identity remains captured for stale-task rejection; only
        // the cleanup lease follows the node when author code adopts it.
        Ok(Self {
            dom: dom.clone(),
            node,
            document,
            _lease: lease,
        })
    }
}

/// Immutable inputs captured at the script preparation boundary. The native
/// lease keeps a detached script alive until the scheduler consumes its work.
pub struct PreparedDynamicScript {
    stream_completion: Option<html_stream::ScriptCompletion>,
    pub render_blocking: bool,
    render_blocker: Option<oryn_dom::RenderBlocker>,
    pub graph_error: Option<u64>,
    pub fallback_encoding: String,
    pub url_encoding: String,
    pub script_policy: Option<String>,
    pub local_script_policy: Option<std::sync::Arc<ScriptPolicySnapshot>>,
    pub node: NodeId,
    pub asynchronous: bool,
    pub module: bool,
    pub src: Option<String>,
    pub source: crate::script_source::ScriptSource,
    pub nonce: Option<String>,
    pub integrity: Option<String>,
    pub cross_origin: Option<String>,
    pub base_url: String,
    pub referrer_policy: Option<String>,
    realm: RealmId,
    document_generation: u64,
    stream_epoch: u64,
    load_cancellation_epoch: u64,
    _target: DeferredDomTarget,
}

impl PreparedDynamicScript {
    pub fn release_render_blocker(&self) {
        if let Some(blocker) = &self.render_blocker {
            blocker.release();
        }
    }
    pub fn resolve_source(&self, input: &str) -> Result<Url, url::ParseError> {
        oryn_dom::document_url::parse_with_label(
            input,
            Url::parse(&self.base_url).ok().as_ref(),
            &self.url_encoding,
        )
    }
    pub fn current_node(&self) -> NodeId {
        self._target._lease.current().1
    }
    pub fn owner_is_current(&self, state: &V8BindingState) -> bool {
        !state.execution_retired()
            && self.realm == state.realm()
            && self.document_generation == state.document_generation()
            && self.stream_epoch == state.document_stream_epoch()
            && self.load_cancellation_epoch == state.load_cancellation_epoch.get()
            && Rc::ptr_eq(&self._target.dom, &state.dom)
            && self._target.document == state.document_root()
    }
    pub fn is_current(&self, state: &V8BindingState) -> bool {
        let (dom, node) = self._target._lease.current();
        self.owner_is_current(state)
            && Rc::ptr_eq(&dom, &state.dom)
            && dom.borrow().node_document(node).ok().flatten() == Some(self._target.document)
    }
}

