pub trait BindingLayoutProvider {
    /// Private embedding bridge: the native renderer and synchronous geometry
    /// queries share one document style session without a layout crate dependency.
    fn native_backend(&self) -> Option<&dyn std::any::Any> {
        None
    }
    fn animations_active(&self) -> bool {
        false
    }

    fn set_animation_time(&self, _time_ms: f64) {}
    fn publish_animation_effects(&self, _effects: &[BindingAnimationEffect]) -> Result<(), String> {
        Ok(())
    }
    fn css_animations(&self) -> Result<Vec<BindingCssAnimation>, String> {
        Ok(Vec::new())
    }
    fn animation_style_values(
        &self,
        _id: u64,
        _css: bool,
    ) -> Result<BTreeMap<String, String>, String> {
        Err("native animation style sampling unavailable".into())
    }
    fn control_css_animation(
        &self,
        _id: u64,
        _action: BindingCssAnimationControl,
        _time_ms: Option<f64>,
    ) -> Result<(), String> {
        Err("native CSS animation control unavailable".into())
    }

    fn install_native_font(
        &self,
        _document: NodeId,
        _owner: NodeId,
        _revision: u64,
        _font: BindingFontResource,
        _custody: std::sync::Arc<dyn std::any::Any + Send + Sync>,
    ) -> Result<(), String> {
        Err("native font consumer unavailable".into())
    }

    /// Private paint-alpha observation. None means this provider has no native
    /// raster authority; it never authorizes a positive visibility result.
    fn permission_paint_coverage(
        &self,
        _request: &crate::drag_image::Capture,
        _paint_keys: &BTreeSet<u64>,
        _custom_states: &BTreeMap<NodeId, BTreeSet<String>>,
        _scroll: (f64, f64),
        _element_scrolls: &BTreeMap<NodeId, (f64, f64)>,
    ) -> Result<Option<bool>, String> {
        Ok(None)
    }

    fn install_paint_capture_inventory(
        &self,
        _document: NodeId,
        _generation: u64,
        _epoch: u64,
        _snapshot: &oryn_common::v4::PaintSnapshot,
    ) -> Result<(), String> {
        Err("native paint inventory unavailable".into())
    }

    fn capture_drag_image(
        &self,
        _request: &crate::drag_image::Capture,
        _custom_states: &BTreeMap<NodeId, BTreeSet<String>>,
        _scroll: (f64, f64),
        _element_scrolls: &BTreeMap<NodeId, (f64, f64)>,
    ) -> Result<crate::drag_image::Snapshot, String> {
        Err("native drag raster capture unavailable".into())
    }

    fn set_page_rule_selector(
        &self,
        _source: &str,
        _path: &[usize],
        _selector: &str,
        _base_url: &str,
        _quirks: bool,
    ) -> Option<Result<Option<Vec<BindingRuleView>>, String>> {
        None
    }

    fn mutate_stylesheet_media(
        &self,
        _text: &str,
        _edit: BindingMediaListEdit<'_>,
        _base_url: &str,
        _quirks: bool,
    ) -> Option<Result<BindingStylesheetMediaMutation, String>> {
        None
    }

    fn mutate_media_list(
        &self,
        _source: &str,
        _path: &[usize],
        _edit: BindingMediaListEdit<'_>,
        _base_url: &str,
        _quirks: bool,
    ) -> Option<Result<BindingMediaListMutation, String>> {
        None
    }

    fn mutate_rule_list(
        &self,
        _source: &str,
        _parent_path: &[usize],
        _edit: BindingRuleListEdit<'_>,
        _base_url: &str,
        _quirks: bool,
        _allow_imports: bool,
    ) -> Option<Result<Vec<BindingRuleView>, BindingRuleMutationError>> {
        None
    }

    fn set_style_rule_selector(
        &self,
        _source: &str,
        _path: &[usize],
        _selector: &str,
        _base_url: &str,
        _quirks: bool,
    ) -> Option<Result<Option<Vec<BindingRuleView>>, String>> {
        None
    }

    fn mutate_rule_declaration(
        &self,
        _request: &BindingDeclarationRequest<'_>,
        _path: &[usize],
        _replace: bool,
    ) -> Option<Result<BindingRuleDeclarationMutation, String>> {
        None
    }

    fn read_font_face_declaration(
        &self,
        _request: &BindingDeclarationRequest<'_>,
    ) -> Option<Result<BindingDeclarationView, String>> {
        None
    }

    fn read_page_declaration(
        &self,
        _request: &BindingDeclarationRequest<'_>,
    ) -> Option<Result<BindingDeclarationView, String>> {
        None
    }

    fn mutate_page_declaration(
        &self,
        _request: &BindingDeclarationRequest<'_>,
        _replace: bool,
    ) -> Option<Result<BindingPageDeclarationMutation, String>> {
        None
    }

    fn set_page_selector(
        &self,
        _source: &str,
        _selector: &str,
        _base_url: &str,
        _quirks: bool,
    ) -> Option<Result<Option<BindingRuleView>, String>> {
        None
    }

    fn read_stylesheet(
        &self,
        _source: &str,
        _base_url: &str,
        _quirks: bool,
        _allow_imports: bool,
    ) -> Option<Result<Vec<BindingRuleView>, String>> {
        None
    }

    fn css_supports(&self, _condition: &str, _value: Option<&str>, _base: &str) -> bool {
        false
    }

    fn validate_custom_property(
        &self,
        _registration: &oryn_dom::RegisteredCustomProperty,
    ) -> Result<(), String> {
        Err("NotSupportedError".into())
    }

    fn supported_css_properties(&self) -> Vec<(String, String)> {
        Vec::new()
    }

    fn read_declaration(
        &self,
        _request: &BindingDeclarationRequest<'_>,
    ) -> Option<Result<BindingDeclarationView, String>> {
        None
    }

    fn mutate_declaration(
        &self,
        _request: &BindingDeclarationRequest<'_>,
    ) -> Option<Result<BindingDeclarationMutation, String>> {
        None
    }

    /// The binding cache is invalidated whenever the environment updates this
    /// viewport, independently of DOM/style revisions.
    fn fork_document(
        &self,
        _dom: SharedDomRuntime,
        _document: NodeId,
        _width: f64,
        _height: f64,
    ) -> Option<Rc<dyn BindingLayoutProvider>> {
        None
    }
    fn set_viewport(&self, _width: f64, _height: f64) {}
    fn set_native_scrollbar_width(&self, _width: f64) {}
    fn set_native_media(&self, _dark: bool, _reduced: bool) {}
    fn set_native_device_pixel_ratio(&self, _ratio: f64) {}
    fn native_device_pixel_ratio(&self) -> f64 {
        1.
    }
    fn native_image_source_size(
        &self,
        _sizes: &str,
        _base: &str,
        _auto_width: Option<f64>,
    ) -> Result<f64, String> {
        Err("native source-size evaluator unavailable".into())
    }
    fn native_media_matches(
        &self,
        _query: &str,
        _base: &str,
        _quirks: bool,
    ) -> Result<bool, String> {
        Err("native media evaluator unavailable".into())
    }

    /// Opt in only when the revision covers every provider-owned layout input.
    /// Providers with independently changing inputs keep the default uncached behavior.
    fn layout_revision(&self) -> Option<u64> {
        None
    }

    fn compute_layout(
        &self,
        custom_states: &BTreeMap<NodeId, BTreeSet<String>>,
    ) -> Result<BindingLayout, String>;

    /// Flush geometry at the native document scroll position. Providers without
    /// geometry can retain the unscrolled implementation.
    fn compute_layout_at_scroll(
        &self,
        custom_states: &BTreeMap<NodeId, BTreeSet<String>>,
        _scroll: (f64, f64),
    ) -> Result<BindingLayout, String> {
        self.compute_layout(custom_states)
    }

    /// Flush with the complete scroll state. Nested offsets are keyed by native
    /// identity and exclude the canonical document viewport offset.
    fn compute_layout_with_scrolls(
        &self,
        custom_states: &BTreeMap<NodeId, BTreeSet<String>>,
        document_scroll: (f64, f64),
        _element_scrolls: &BTreeMap<NodeId, (f64, f64)>,
    ) -> Result<BindingLayout, String> {
        self.compute_layout_at_scroll(custom_states, document_scroll)
    }

    fn query_selector(
        &self,
        _node: NodeId,
        _selector: &str,
        _operation: SelectorOperation,
        _custom_states: &BTreeMap<NodeId, BTreeSet<String>>,
    ) -> Option<Result<Vec<NodeId>, String>> {
        None
    }

    fn canonicalize_selector(&self, _selector: &str) -> Result<String, String> {
        Err("selector parser is unavailable".into())
    }

    fn compute_accessibility_with_layout(
        &self,
        node: NodeId,
        _layout: &BindingLayout,
    ) -> Result<BindingAccessibility, String> {
        self.compute_accessibility(node)
    }
    fn compute_accessibility(&self, _node: NodeId) -> Result<BindingAccessibility, String> {
        Err("accessible semantics provider is unavailable".into())
    }
}

