/// Embedding-owned lifecycle work, run before author reactions to DOM changes.
/// The callback must not execute author JavaScript or retain a borrowed scope.
pub struct DomLifecycleCheckpoint(pub fn(&mut v8::PinScope));

pub fn checkpoint_dom_lifecycle(scope: &mut v8::PinScope) {
    if let Err(error) = oryn_dom::drain_tracked_node_leases() {
        throw_binding_error(scope, &error.into());
        return;
    }
    if let Err(error) = node_migration::resume_publications(scope) {
        throw_binding_error(scope, &error);
        return;
    }
    if let Err(error) = aria::reconcile_agent(scope) {
        throw_binding_error(scope, &error);
        return;
    }
    if scope.is_execution_terminating() {
        return;
    }
    if let Some(state) = scope.get_current_context().get_slot::<V8BindingState>() {
        let completed = state.dom.borrow_mut().drain_committed_tree_tails();
        if let Err(error) = completed {
            throw_binding_error(scope, &error.into());
            return;
        }
        let reclaimed = state.dom.borrow_mut().retry_pending_stylesheet_reclaims();
        if let Err(error) = reclaimed {
            throw_binding_error(scope, &error.into());
            return;
        }
        if let Err(error) = resume_editing_recovery(&state) {
            throw_binding_error(scope, &error);
            return;
        }
        if let Err(error) = state.reconcile_inline_style_policy() {
            throw_binding_error(scope, &error);
            return;
        }
    }
    if let Some(callback) = scope
        .get_slot::<DomLifecycleCheckpoint>()
        .map(|hook| hook.0)
    {
        callback(scope);
    }
}

type PendingSlotNotification = (u64, NodeId, v8::Global<v8::Object>);

/// Keep notifications that have not begun dispatch when an observer or an
/// earlier slot callback aborts the checkpoint. Rooted wrappers stay alive.
struct SlotNotificationBatch {
    remaining: VecDeque<PendingSlotNotification>,
    suspended: VecDeque<PendingSlotNotification>,
    destination: Rc<RefCell<Vec<PendingSlotNotification>>>,
}

impl SlotNotificationBatch {
    fn take(destination: &Rc<RefCell<Vec<PendingSlotNotification>>>) -> Self {
        Self {
            remaining: std::mem::take(&mut *destination.borrow_mut()).into(),
            suspended: VecDeque::new(),
            destination: Rc::clone(destination),
        }
    }
}

impl Drop for SlotNotificationBatch {
    fn drop(&mut self) {
        if self.remaining.is_empty() && self.suspended.is_empty() {
            return;
        }
        let mut pending = self.destination.borrow_mut();
        let mut restored: Vec<_> = self
            .suspended
            .drain(..)
            .chain(self.remaining.drain(..))
            .collect();
        for entry in pending.drain(..) {
            if !restored
                .iter()
                .any(|(instance, node, _)| *instance == entry.0 && *node == entry.1)
            {
                restored.push(entry);
            }
        }
        *pending = restored;
    }
}

/// An aborted checkpoint keeps notifications whose callback has not begun.
/// Restored entries precede reentrant work; one observer occupies one pending
/// position even if both the interrupted batch and a callback queued it.
struct ObserverNotificationBatch {
    remaining: VecDeque<(u64, u64)>,
    suspended: VecDeque<(u64, u64)>,
    destination: Rc<RefCell<Vec<(u64, u64)>>>,
    membership: Rc<RefCell<BTreeSet<(u64, u64)>>>,
}
impl ObserverNotificationBatch {
    fn take(registry: &BindingStateRegistry) -> Self {
        registry.pending_observer_set.borrow_mut().clear();
        Self {
            remaining: std::mem::take(&mut *registry.pending_observers.borrow_mut()).into(),
            suspended: VecDeque::new(),
            destination: Rc::clone(&registry.pending_observers),
            membership: Rc::clone(&registry.pending_observer_set),
        }
    }
}
impl Drop for ObserverNotificationBatch {
    fn drop(&mut self) {
        if self.remaining.is_empty() && self.suspended.is_empty() {
            return;
        }
        let mut pending = self.destination.borrow_mut();
        let mut membership = self.membership.borrow_mut();
        let mut restored: Vec<_> = self
            .suspended
            .drain(..)
            .chain(self.remaining.drain(..))
            .collect();
        let mut seen: BTreeSet<_> = restored.iter().copied().collect();
        for entry in pending.drain(..) {
            if seen.insert(entry) {
                restored.push(entry);
            }
        }
        *pending = restored;
        *membership = seen;
    }
}

