    pub fn notify_user_activation(&self) {
        if !self.execution_retired() {
            self.sticky_user_activation.set(true);
            if let Some(backend) = self.activation_backend.borrow().clone() {
                if let Ok(creator) = workers::native_creator(self) {
                    let _ = backend.notify(creator);
                }
            } else if let Some(backend) = self.local_activation_backend.borrow().clone()
                && let Ok(creator) = self.native_local_creator_identity()
            {
                let _ = backend.notify(creator);
            }
        }
    }
    fn native_transient_user_activation(&self, consume: bool) -> bool {
        if self.execution_retired() {
            return false;
        }
        if let Some(backend) = self.activation_backend.borrow().clone() {
            let Ok(creator) = workers::native_creator(self) else {
                return false;
            };
            return backend.transient(creator, consume).unwrap_or(false);
        }
        let Some(backend) = self.local_activation_backend.borrow().clone() else {
            return false;
        };
        let Ok(creator) = self.native_local_creator_identity() else {
            return false;
        };
        backend.transient(creator, consume).unwrap_or(false)
    }
    pub fn has_transient_user_activation(&self) -> bool {
        self.native_transient_user_activation(false)
    }
    pub fn consume_transient_user_activation(&self) -> bool {
        self.native_transient_user_activation(true)
    }
    pub fn has_sticky_user_activation(&self) -> bool {
        if self.execution_retired() {
            return false;
        }
        if self.sticky_user_activation.get() {
            return true;
        }
        if let Some(backend) = self.activation_backend.borrow().clone() {
            let Ok(creator) = workers::native_creator(self) else {
                return false;
            };
            return backend.sticky(creator).unwrap_or(false);
        }
        let Some(backend) = self.local_activation_backend.borrow().clone() else {
            return false;
        };
        let Ok(creator) = self.native_local_creator_identity() else {
            return false;
        };
        backend.sticky(creator).unwrap_or(false)
    }
