    /// Parent-facing request identity comes from the active native document.
    pub fn request_initiator_url(&self) -> Result<String, V8BindingError> {
        Ok(self
            .dom
            .borrow()
            .arena()
            .get(self.document_root())?
            .document_metadata
            .as_ref()
            .and_then(|metadata| metadata.url.clone())
            .unwrap_or_else(|| self.location_url.borrow().to_string()))
    }

    /// Resolve the active document base without invoking author JavaScript.
    pub fn native_document_base_url(
        &self,
        use_base_element: bool,
    ) -> Result<String, V8BindingError> {
        let href = self.request_initiator_url()?;
        let fallback = if document_url_uses_inherited_base(&href) {
            self.inherited_base_url.borrow().clone().unwrap_or(href)
        } else {
            href
        };
        resolve_document_base(
            &self.dom.borrow(),
            self.document_root(),
            fallback,
            use_base_element,
        )
    }

    /// HTML resource attributes use the selected Document output encoding for
    /// query bytes. Fetch/URL/module specifier APIs use their own UTF-8 parser.
    pub fn native_document_resource_url(&self, input: &str) -> Result<Url, V8BindingError> {
        let base = self.native_document_base_url(true)?;
        let encoding = hyperlinks::document_encoding(self, self.document_root())?;
        oryn_dom::document_url::parse(input, Url::parse(&base).ok().as_ref(), encoding)
            .map_err(|_| V8BindingError::Message("invalid HTML resource URL".into()))
    }

    /// Read the native Location value without invoking author code.
    pub fn current_location_url(&self) -> String {
        self.location_url.borrow().to_string()
    }

    /// Commit a URL without requesting navigation (initialization/history).
    pub fn commit_location(&self, href: &str) -> Result<(), V8BindingError> {
        let url = Url::parse(href).map_err(|_| V8BindingError::Unsupported {
            interface: "Location".into(),
            member: "SyntaxError".into(),
        })?;
        {
            let mut dom = self.dom.borrow_mut();
            let document = dom.arena_mut().get_mut(self.document_root())?;
            let metadata = document
                .document_metadata
                .get_or_insert_with(|| Box::new(oryn_dom::DocumentMetadata::html()));
            metadata.url = Some(url.to_string());
        }
        let previous = self.location_url.replace(url);
        let installed = self
            .dom
            .borrow()
            .arena()
            .get(self.document_root())?
            .document_metadata
            .as_ref()
            .is_some_and(|metadata| metadata.provenance.is_some());
        if installed && let Err(error) = self.refresh_document_provenance() {
            self.dom
                .borrow_mut()
                .arena_mut()
                .get_mut(self.document_root())?
                .document_metadata
                .as_mut()
                .unwrap()
                .url = Some(previous.to_string());
            *self.location_url.borrow_mut() = previous;
            return Err(error);
        }
        Ok(())
    }

