    pub fn scoped_message_request(
        &self,
        request: crate::message_wire::MessageRequest,
    ) -> Result<crate::message_wire::MessageRequest, V8BindingError> {
        Ok(match self.native_worker_creator()? {
            crate::worker_wire::Creator::Window {
                target,
                document_generation,
                stream_epoch,
            } => crate::message_wire::MessageRequest::InDocument {
                target,
                document_generation,
                stream_epoch,
                request: Box::new(request),
            },
            crate::worker_wire::Creator::Agent(_) => request,
        })
    }
    pub fn native_shared_wait_delay(&self) -> Option<std::time::Duration> {
        #[cfg(unix)]
        if self
            .shared_waits
            .borrow()
            .as_ref()
            .is_some_and(|waits| waits.pending())
        {
            return Some(std::time::Duration::from_millis(10));
        }
        None
    }
    #[cfg(unix)]
    pub(crate) fn map_native_shared_memory<'s>(
        &self,
        scope: &mut v8::PinScope<'s, '_>,
        response: crate::shared_memory::SharedMemoryResponse,
    ) -> Result<v8::Local<'s, v8::SharedArrayBuffer>, V8BindingError> {
        let transport = self
            .worker_transport
            .borrow()
            .clone()
            .ok_or(V8BindingError::Allocation("shared memory broker"))?;
        let creator = self.native_worker_creator()?;
        if self.execution_retired() {
            return Err(V8BindingError::Allocation(
                "shared memory environment retired",
            ));
        }
        let mut waits = self.shared_waits.borrow_mut();
        if waits.is_none() {
            *waits = crate::v8_shared_wait::WaitEnvironment::new();
        }
        let waits = waits
            .as_ref()
            .ok_or(V8BindingError::Allocation("shared wait environment"))?;
        let mapped = if response
            .descriptor
            .is_some_and(|descriptor| descriptor.wasm)
        {
            crate::v8_shared_memory::map_wasm_backing(scope, transport, creator, response, waits)
        } else {
            crate::v8_shared_memory::map(scope, transport, creator, response, waits)
        };
        let (buffer, _lease) =
            mapped.map_err(|_| V8BindingError::Allocation("native shared memory mapping"))?;
        Ok(buffer)
    }
    #[cfg(unix)]
    pub(crate) fn native_shared_wait_authority(
        &self,
    ) -> Option<(
        std::sync::Arc<dyn crate::worker_wire::WorkerTransport>,
        crate::worker_wire::Creator,
    )> {
        if self.execution_retired() {
            return None;
        }
        // Reading native identity must never synchronously register a document
        // while V8 is waiting for interruptible admission. Existing mappings
        // already required committed parent authority; Open revalidates it.
        let creator = self.worker_creator.borrow().clone().unwrap_or_else(|| {
            crate::worker_wire::Creator::Window {
                target: self.message_target.borrow().clone(),
                document_generation: self.document_generation(),
                stream_epoch: self.document_authority_epoch(),
            }
        });
        Some((self.worker_transport.borrow().clone()?, creator))
    }
    #[cfg(unix)]
    pub(crate) fn native_wait_environment_pointer(&self) -> *mut std::ffi::c_void {
        let mut waits = self.shared_waits.borrow_mut();
        if waits.is_none() {
            *waits = crate::v8_shared_wait::WaitEnvironment::new();
        }
        waits
            .as_ref()
            .map_or(std::ptr::null_mut(), |waits| waits.native_pointer())
    }
    #[cfg(unix)]
    pub(crate) fn native_shared_mapping(
        &self,
        buffer: &v8::SharedArrayBuffer,
    ) -> Option<std::sync::Arc<crate::v8_shared_memory::MappingLease>> {
        crate::v8_shared_memory::lookup(buffer)
    }
