    pub fn poll_external_ports(
        self: &Rc<Self>,
        scope: &mut v8::PinScope,
    ) -> Result<usize, V8BindingError> {
        if self.execution_tasks_stopped() {
            return Ok(0);
        }
        #[cfg(unix)]
        let wait_completions = self
            .shared_waits
            .borrow()
            .as_ref()
            .map(|waits| waits.poll(scope))
            .unwrap_or(0);
        #[cfg(not(unix))]
        let wait_completions = 0;
        platform_listener_graph::reconcile_activity(scope, self);
        let result = (|| {
            let mut count = 0;
            macro_rules! poll_tasks {
                ($poll:path) => {
                    if !self.execution_tasks_stopped() {
                        count += $poll(scope, self)?;
                    }
                };
            }
            poll_tasks!(message_ports::poll_external);
            poll_tasks!(broadcast_channels::poll);
            poll_tasks!(audio_worklet::poll);
            poll_tasks!(workers::poll);
            poll_tasks!(csp_events::poll_agent);
            poll_tasks!(service_workers::poll);
            poll_tasks!(cache_storage::poll);
            Ok(count)
        })();
        platform_listener_graph::reconcile_activity(scope, self);
        result.map(|count| count + wait_completions)
    }
