fn blob_url_source_callback(
    scope: &mut v8::PinScope,
    args: v8::FunctionCallbackArguments,
    mut return_value: v8::ReturnValue,
) {
    let Some(state) = scope.get_current_context().get_slot::<V8BindingState>() else {
        return_value.set(v8::null(scope).into());
        return;
    };
    let url = args.get(0).to_rust_string_lossy(scope);
    let Some(blob) = blob_url_record(&state, &url) else {
        return_value.set(v8::null(scope).into());
        return;
    };
    if let Some(value) = v8::String::new(scope, &String::from_utf8_lossy(&blob.bytes)) {
        return_value.set(value.into());
    }
}

fn install_image_factory(
    scope: &mut v8::PinScope,
    context: v8::Local<v8::Context>,
) -> Result<(), V8BindingError> {
    let template = v8::FunctionTemplate::builder(image_factory_callback)
        .length(2)
        .build(scope);
    template.set_class_name(
        v8::String::new(scope, "Image").ok_or(V8BindingError::Allocation("Image name"))?,
    );
    let factory = template
        .get_function(scope)
        .ok_or(V8BindingError::Allocation("Image factory"))?;
    let prototype_name =
        v8::String::new(scope, "prototype").ok_or(V8BindingError::Allocation("prototype"))?;
    let image_element_name = v8::String::new(scope, "HTMLImageElement")
        .ok_or(V8BindingError::Allocation("HTMLImageElement name"))?;
    let image_element_prototype = context
        .global(scope)
        .get(scope, image_element_name.into())
        .and_then(|value| value.to_object(scope))
        .and_then(|constructor| constructor.get(scope, prototype_name.into()))
        .ok_or(V8BindingError::MissingInterface("HTMLImageElement"))?;
    factory.define_own_property(
        scope,
        prototype_name.into(),
        image_element_prototype,
        v8::PropertyAttribute::DONT_ENUM | v8::PropertyAttribute::DONT_DELETE,
    );
    let name = v8::String::new(scope, "Image").ok_or(V8BindingError::Allocation("Image name"))?;
    context.global(scope).define_own_property(
        scope,
        name.into(),
        factory.into(),
        v8::PropertyAttribute::DONT_ENUM,
    );
    Ok(())
}

fn install_option_factory(
    scope: &mut v8::PinScope,
    context: v8::Local<v8::Context>,
) -> Result<(), V8BindingError> {
    // Share the existing snapshotted native factory dispatch entry point.
    let marker = v8::Integer::new(scope, 1);
    let template = v8::FunctionTemplate::builder(image_factory_callback)
        .data(marker.into())
        .length(0)
        .build(scope);
    let name = v8::String::new(scope, "Option").ok_or(V8BindingError::Allocation("Option name"))?;
    template.set_class_name(name);
    let factory = template
        .get_function(scope)
        .ok_or(V8BindingError::Allocation("Option factory"))?;
    let prototype_name = v8::String::new(scope, "prototype").unwrap();
    let interface = v8::String::new(scope, "HTMLOptionElement").unwrap();
    let prototype = context
        .global(scope)
        .get(scope, interface.into())
        .and_then(|value| value.to_object(scope))
        .and_then(|constructor| constructor.get(scope, prototype_name.into()))
        .ok_or(V8BindingError::MissingInterface("HTMLOptionElement"))?;
    factory.define_own_property(
        scope,
        prototype_name.into(),
        prototype,
        v8::PropertyAttribute::READ_ONLY
            | v8::PropertyAttribute::DONT_ENUM
            | v8::PropertyAttribute::DONT_DELETE,
    );
    // FunctionTemplate construction allocates `this` and reads newTarget.prototype
    // before entering Rust. A native construct trap defers that read until after
    // WebIDL argument conversion, as required for a legacy factory.
    let handler = v8::Object::new(scope);
    let construct = v8::String::new(scope, "construct").unwrap();
    let marker = v8::Integer::new(scope, 2);
    let trap = v8::Function::builder(image_factory_callback)
        .data(marker.into())
        .build(scope)
        .ok_or(V8BindingError::Allocation("Option construct trap"))?;
    handler.create_data_property(scope, construct.into(), trap.into());
    let proxy = v8::Proxy::new(scope, factory.into(), handler)
        .ok_or(V8BindingError::Allocation("Option factory proxy"))?;
    context.global(scope).define_own_property(
        scope,
        name.into(),
        proxy.into(),
        v8::PropertyAttribute::DONT_ENUM,
    );
    Ok(())
}

fn option_factory<'s>(
    scope: &mut v8::PinScope<'s, '_>,
    args: &v8::FunctionCallbackArguments,
) -> Result<v8::Local<'s, v8::Value>, V8BindingError> {
    let values = v8::Local::<v8::Array>::try_from(args.get(1))
        .map_err(|_| V8BindingError::Allocation("Option arguments"))?;
    let mut arguments = Vec::new();
    for index in 0..4 {
        arguments.push(if index < values.length() {
            values
                .get_index(scope, index)
                .ok_or(V8BindingError::JavaScriptException)?
        } else {
            v8::undefined(scope).into()
        });
    }
    let state = scope
        .get_current_context()
        .get_slot::<V8BindingState>()
        .ok_or(V8BindingError::MissingInterface("Option realm"))?;
    let text = if arguments[0].is_undefined() {
        String::new()
    } else {
        let value = arguments[0]
            .to_string(scope)
            .ok_or(V8BindingError::JavaScriptException)?;
        rust_string_preserving_utf16(scope, value)?
    };
    let value = if arguments[1].is_undefined() {
        None
    } else {
        let value = arguments[1]
            .to_string(scope)
            .ok_or(V8BindingError::JavaScriptException)?;
        Some(rust_string_preserving_utf16(scope, value)?)
    };
    let default_selected = arguments[2].boolean_value(scope);
    let selected = arguments[3].boolean_value(scope);
    let new_target = args
        .get(2)
        .to_object(scope)
        .ok_or(V8BindingError::JavaScriptException)?;
    let prototype_name = v8::String::new(scope, "prototype").unwrap();
    let prototype = new_target
        .get(scope, prototype_name.into())
        .ok_or(V8BindingError::JavaScriptException)?;
    let node = {
        let mut dom = state.dom.borrow_mut();
        let node = dom.create_element("option");
        if !text.is_empty() {
            dom.set_text_content(node, text)?;
        }
        if let Some(value) = value {
            dom.set_attribute_ns(node, None, "value", value)?;
        }
        if default_selected {
            dom.set_attribute_ns(node, None, "selected", "")?;
        }
        dom.set_option_selectedness(node, selected)?;
        node
    };
    let wrapper = wrap_node(scope, &state, node)?;
    if prototype.is_object() {
        wrapper.set_prototype(scope, prototype);
    }
    Ok(wrapper.into())
}

fn image_factory_callback(
    scope: &mut v8::PinScope,
    args: v8::FunctionCallbackArguments,
    mut return_value: v8::ReturnValue,
) {
    if args.data().int32_value(scope) == Some(1) {
        throw_type_error(scope, "Option constructor requires new");
        return;
    }
    if args.data().int32_value(scope) == Some(2) {
        match option_factory(scope, &args) {
            Ok(value) => return_value.set(value),
            Err(error) => throw_binding_error(scope, &error),
        }
        return;
    }
    let Some(state) = scope.get_current_context().get_slot::<V8BindingState>() else {
        throw_type_error(scope, "generated binding state is unavailable");
        return;
    };
    let node = state.dom.borrow_mut().create_element("img");
    for (index, name) in [(0, "width"), (1, "height")] {
        let value = args.get(index);
        if value.is_undefined() {
            continue;
        }
        let Some(value) = value.integer_value(scope) else {
            throw_type_error(scope, "Image dimensions must be finite integers");
            return;
        };
        if let Err(error) =
            state
                .dom
                .borrow_mut()
                .set_attribute(node, name, value.max(0).to_string())
        {
            throw_binding_error(scope, &error.into());
            return;
        }
    }
    let Ok(wrapper) = wrap_node(scope, &state, node) else {
        throw_type_error(scope, "Image wrapper allocation failed");
        return;
    };
    if let Some(new_target) = args.new_target().to_object(scope)
        && let Some(prototype_name) = v8::String::new(scope, "prototype")
        && let Some(prototype) = new_target.get(scope, prototype_name.into())
        && prototype.is_object()
    {
        wrapper.set_prototype(scope, prototype);
    }
    return_value.set(wrapper.into());
}

fn install_dom_exception_intrinsics(
    scope: &mut v8::PinScope,
    context: v8::Local<v8::Context>,
) -> Result<(), V8BindingError> {
    let prototype_name =
        v8::String::new(scope, "prototype").ok_or(V8BindingError::Allocation("prototype"))?;
    let dom_name = v8::String::new(scope, "DOMException")
        .ok_or(V8BindingError::Allocation("DOMException name"))?;
    let dom_prototype = context
        .global(scope)
        .get(scope, dom_name.into())
        .and_then(|value| value.to_object(scope))
        .and_then(|constructor| constructor.get(scope, prototype_name.into()))
        .and_then(|value| value.to_object(scope))
        .ok_or(V8BindingError::MissingInterface("DOMException"))?;
    let error_name =
        v8::String::new(scope, "Error").ok_or(V8BindingError::Allocation("Error name"))?;
    let error_prototype = context
        .global(scope)
        .get(scope, error_name.into())
        .and_then(|value| value.to_object(scope))
        .and_then(|constructor| constructor.get(scope, prototype_name.into()))
        .ok_or(V8BindingError::Allocation("Error prototype"))?;
    dom_prototype.set_prototype(scope, error_prototype);
    let error_prototype = v8::Local::<v8::Object>::try_from(error_prototype)
        .map_err(|_| V8BindingError::Allocation("Error prototype"))?;
    native_errors::install(scope, context, error_prototype)?;
    Ok(())
}

fn install_abort_signal_statics(
    scope: &mut v8::PinScope,
    context: v8::Local<v8::Context>,
) -> Result<(), V8BindingError> {
    let name = v8::String::new(scope, "AbortSignal")
        .ok_or(V8BindingError::Allocation("AbortSignal name"))?;
    let constructor = context
        .global(scope)
        .get(scope, name.into())
        .and_then(|value| v8::Local::<v8::Function>::try_from(value).ok())
        .ok_or(V8BindingError::MissingInterface("AbortSignal"))?;
    let callback = v8::Function::builder(abort_signal_abort_static)
        .length(0)
        .constructor_behavior(v8::ConstructorBehavior::Throw)
        .build(scope)
        .ok_or(V8BindingError::Allocation("AbortSignal.abort static"))?;
    let name = v8::String::new(scope, "abort")
        .ok_or(V8BindingError::Allocation("AbortSignal.abort name"))?;
    callback.set_name(name);
    constructor.create_data_property(scope, name.into(), callback.into());
    let callback = v8::Function::builder(abort_signal_any_static)
        .length(1)
        .constructor_behavior(v8::ConstructorBehavior::Throw)
        .build(scope)
        .ok_or(V8BindingError::Allocation("AbortSignal.any static"))?;
    let name =
        v8::String::new(scope, "any").ok_or(V8BindingError::Allocation("AbortSignal.any name"))?;
    callback.set_name(name);
    constructor.create_data_property(scope, name.into(), callback.into());
    let callback = v8::Function::builder(abort_signal_timeout_static)
        .length(1)
        .constructor_behavior(v8::ConstructorBehavior::Throw)
        .build(scope)
        .ok_or(V8BindingError::Allocation("AbortSignal.timeout static"))?;
    let name = v8::String::new(scope, "timeout")
        .ok_or(V8BindingError::Allocation("AbortSignal.timeout name"))?;
    callback.set_name(name);
    constructor.create_data_property(scope, name.into(), callback.into());
    Ok(())
}

fn abort_signal_abort_static<'s>(
    scope: &mut v8::PinScope<'s, '_>,
    args: v8::FunctionCallbackArguments<'s>,
    mut return_value: v8::ReturnValue,
) {
    let result = (|| -> Result<v8::Local<v8::Object>, V8BindingError> {
        let state = scope
            .get_current_context()
            .get_slot::<V8BindingState>()
            .ok_or(V8BindingError::Allocation("AbortSignal state"))?;
        let reason = if args.length() == 0 || args.get(0).is_undefined() {
            dom_exception_value(scope, "AbortError")?
        } else {
            args.get(0)
        };
        let id = register_platform_object(
            &state,
            PlatformObjectRecord::AbortSignal(AbortSignalRecord {
                aborted: true,
                reason: Some(platform_listener_graph::Value::new(scope, reason)),
                followers: Vec::new(),
                foreign_followers: Vec::new(),
                foreign_sources: Vec::new(),
            }),
        );
        new_platform_object(scope, &state, "AbortSignal", id)
    })();
    match result {
        Ok(signal) => return_value.set(signal.into()),
        Err(error) => throw_binding_error(scope, &error),
    }
}

fn abort_signal_any_static<'s>(
    scope: &mut v8::PinScope<'s, '_>,
    args: v8::FunctionCallbackArguments<'s>,
    mut rv: v8::ReturnValue,
) {
    let result = (|| {
        let state = scope
            .get_current_context()
            .get_slot::<V8BindingState>()
            .ok_or(V8BindingError::Allocation("AbortSignal state"))?;
        abort_any::create(scope, &state, args.get(0))
    })();
    match result {
        Ok(value) => rv.set(value.into()),
        Err(error) => throw_binding_error(scope, &error),
    }
}

fn abort_signal_timeout_static<'s>(
    scope: &mut v8::PinScope<'s, '_>,
    args: v8::FunctionCallbackArguments<'s>,
    mut return_value: v8::ReturnValue,
) {
    let result =
        (|| -> Result<v8::Local<'s, v8::Object>, V8BindingError> {
            let state = scope
                .get_current_context()
                .get_slot::<V8BindingState>()
                .ok_or(V8BindingError::Allocation("AbortSignal state"))?;
            let number = args
                .get(0)
                .number_value(scope)
                .ok_or(V8BindingError::JavaScriptException)?;
            let number = number.trunc();
            if !number.is_finite() || number < 0. || number >= 18446744073709551616.0 {
                return Err(V8BindingError::Unsupported {
                    interface: "AbortSignal".into(),
                    member: "TypeError: timeout outside unsigned long long range".into(),
                });
            }
            let scheduler = state.native_timeout_scheduler.get().ok_or_else(|| {
                V8BindingError::Unsupported {
                    interface: "AbortSignal".into(),
                    member: "NotSupportedError: native timer scheduler unavailable".into(),
                }
            })?;
            let id = register_platform_object(
                &state,
                PlatformObjectRecord::AbortSignal(AbortSignalRecord {
                    aborted: false,
                    reason: None,
                    followers: Vec::new(),
                    foreign_followers: Vec::new(),
                    foreign_sources: Vec::new(),
                }),
            );
            let signal = new_platform_object(scope, &state, "AbortSignal", id)?;
            // The host's pending callback traces the actual signal wrapper. A
            // dependent listener remains reachable until timeout delivery/retirement.
            let callback = v8::Function::builder(abort_signal_timeout_callback)
                .data(signal.into())
                .build(scope)
                .ok_or(V8BindingError::Allocation("AbortSignal timeout callback"))?;
            scheduler(scope, &state, callback, number as u64)?;
            Ok(signal)
        })();
    match result {
        Ok(signal) => return_value.set(signal.into()),
        Err(error) => throw_binding_error(scope, &error),
    }
}

fn abort_signal_timeout_callback(
    scope: &mut v8::PinScope,
    args: v8::FunctionCallbackArguments,
    _return_value: v8::ReturnValue,
) {
    let result = (|| -> Result<(), V8BindingError> {
        let state = scope
            .get_current_context()
            .get_slot::<V8BindingState>()
            .ok_or(V8BindingError::Allocation("AbortSignal state"))?;
        if state.execution_retired() {
            return Ok(());
        }
        let signal = v8::Local::<v8::Object>::try_from(args.data())
            .map_err(|_| V8BindingError::Allocation("AbortSignal timeout identity"))?;
        let owner = binding_state_for_receiver(scope, signal)
            .ok_or(V8BindingError::Allocation("AbortSignal timeout owner"))?;
        if owner.instance_id != state.instance_id {
            return Err(V8BindingError::Allocation("AbortSignal timeout realm"));
        }
        let id = stateful_id(scope, signal)?;
        let reason = dom_exception_value(scope, "TimeoutError")?;
        abort_signal_with_reason(scope, &state, id, reason)
    })();
    if let Err(error) = result {
        throw_binding_error(scope, &error);
    }
}

struct ConvertedResponseInit {
    headers: Vec<Vec<String>>,
    status: u16,
    status_text: String,
}

fn convert_response_init(
    scope: &mut v8::PinScope,
    init: v8::Local<v8::Value>,
) -> Result<ConvertedResponseInit, V8BindingError> {
    if !init.is_null_or_undefined() && !init.is_object() {
        return Err(V8BindingError::Unsupported {
            interface: "Response".into(),
            member: "init is not a dictionary".into(),
        });
    }
    // Web IDL dictionary members are read in lexicographic order.
    let object = if init.is_null_or_undefined() {
        None
    } else {
        Some(
            v8::Local::<v8::Object>::try_from(init)
                .map_err(|_| V8BindingError::JavaScriptException)?,
        )
    };
    let headers_value = if let Some(object) = object {
        let key = v8::String::new(scope, "headers")
            .ok_or(V8BindingError::Allocation("Response headers"))?;
        Some(
            object
                .get(scope, key.into())
                .ok_or(V8BindingError::JavaScriptException)?,
        )
    } else {
        None
    };
    let headers = if let Some(value) = headers_value.filter(|value| !value.is_undefined()) {
        convert_headers_init(scope, value)?
    } else {
        Vec::new()
    };
    let status = if let Some(object) = object {
        let key = v8::String::new(scope, "status")
            .ok_or(V8BindingError::Allocation("Response status"))?;
        let value = object
            .get(scope, key.into())
            .ok_or(V8BindingError::JavaScriptException)?;
        if value.is_undefined() {
            200
        } else {
            value
                .uint32_value(scope)
                .ok_or(V8BindingError::JavaScriptException)? as u16
        }
    } else {
        200
    };
    let status_text = if let Some(object) = object {
        let key = v8::String::new(scope, "statusText")
            .ok_or(V8BindingError::Allocation("Response statusText"))?;
        let value = object
            .get(scope, key.into())
            .ok_or(V8BindingError::JavaScriptException)?;
        if value.is_undefined() {
            String::new()
        } else {
            let value = value
                .to_string(scope)
                .ok_or(V8BindingError::JavaScriptException)?;
            let text = value.to_rust_string_lossy(scope);
            if text.chars().any(|ch| ch as u32 > 255) {
                return Err(V8BindingError::Unsupported {
                    interface: "Response".into(),
                    member: "statusText is not a ByteString".into(),
                });
            }
            text
        }
    } else {
        String::new()
    };
    Ok(ConvertedResponseInit {
        headers,
        status,
        status_text,
    })
}

fn initialize_response(
    scope: &mut v8::PinScope,
    state: &V8BindingState,
    init: ConvertedResponseInit,
    has_body: bool,
) -> Result<(u64, u16, String), V8BindingError> {
    let ConvertedResponseInit {
        headers,
        status,
        status_text,
    } = init;
    if !(200..=599).contains(&status) {
        let exception = dom_exception_value(scope, "RangeError")?;
        scope.throw_exception(exception);
        return Err(V8BindingError::JavaScriptException);
    }
    if status_text
        .chars()
        .any(|ch| ch != '\t' && !((' '..='~').contains(&ch) || ('\u{80}'..='\u{ff}').contains(&ch)))
    {
        return Err(V8BindingError::Unsupported {
            interface: "Response".into(),
            member: "statusText is not an HTTP reason phrase".into(),
        });
    }
    let headers_id = headers_from_entries(state, headers)?;
    if let PlatformObjectRecord::Headers(headers) = &mut *platform_object_mut(state, headers_id)? {
        headers.response_guard = true;
        headers
            .entries
            .retain(|(name, _)| !forbidden_response_header(name));
    }

    if matches!(status, 204 | 205 | 304) && has_body {
        return Err(V8BindingError::Unsupported {
            interface: "Response".into(),
            member: "status does not permit a body".into(),
        });
    }
    Ok((headers_id, status, status_text))
}

fn response_factory_static<'s>(
    scope: &mut v8::PinScope<'s, '_>,
    args: v8::FunctionCallbackArguments<'s>,
    mut return_value: v8::ReturnValue,
) {
    let result = (|| -> Result<v8::Local<v8::Object>, V8BindingError> {
        let state = scope
            .get_current_context()
            .get_slot::<V8BindingState>()
            .ok_or(V8BindingError::Allocation("Response state"))?;
        let redirect = args.data().integer_value(scope) == Some(1);
        let (status, entries) = if redirect {
            if args.length() < 1 {
                return Err(V8BindingError::Unsupported {
                    interface: "Response".into(),
                    member: "redirect requires URL".into(),
                });
            }
            let input = args
                .get(0)
                .to_string(scope)
                .ok_or(V8BindingError::JavaScriptException)?
                .to_rust_string_lossy(scope);
            let status = if args.get(1).is_undefined() {
                302
            } else {
                args.get(1)
                    .uint32_value(scope)
                    .ok_or(V8BindingError::JavaScriptException)? as u16
            };
            let url = resolve_platform_url(scope, &input)?;
            if !matches!(status, 301 | 302 | 303 | 307 | 308) {
                let exception = dom_exception_value(scope, "RangeError")?;
                scope.throw_exception(exception);
                return Err(V8BindingError::JavaScriptException);
            }
            (status, vec![("location".into(), url)])
        } else {
            (0, Vec::new())
        };
        let headers_id = register_platform_object(
            &state,
            PlatformObjectRecord::Headers(HeadersRecord {
                immutable: true,
                response_guard: true,
                request_guard: false,
                request_no_cors: false,
                entries,
            }),
        );
        let id = register_platform_object(
            &state,
            PlatformObjectRecord::Response(ResponseRecord {
                timing: None,
                internal_response: None,
                body_owner: None,
                response_type: if redirect { "default" } else { "error" },
                status_text: String::new(),
                redirected: false,
                status,
                url: String::new(),
                headers_id,
                body_stream_id: None,
                bytes: Vec::new(),
                body_used: false,
                signal_id: None,
            }),
        );
        new_platform_object(scope, &state, "Response", id)
    })();
    match result {
        Ok(value) => return_value.set(value.into()),
        Err(error) => throw_binding_error(scope, &error),
    }
}

fn response_json_static<'s>(
    scope: &mut v8::PinScope<'s, '_>,
    args: v8::FunctionCallbackArguments<'s>,
    mut return_value: v8::ReturnValue,
) {
    let result = (|| -> Result<v8::Local<v8::Object>, V8BindingError> {
        let state = scope
            .get_current_context()
            .get_slot::<V8BindingState>()
            .ok_or(V8BindingError::Allocation("Response state"))?;
        if args.length() < 1 {
            return Err(V8BindingError::Unsupported {
                interface: "Response".into(),
                member: "json requires data".into(),
            });
        }
        let init = convert_response_init(scope, args.get(1))?;
        let body = {
            v8::tc_scope!(let tc, scope);
            let serialized = v8::json::stringify(tc, args.get(0));
            if !tc.has_caught() {
                let _ = crate::v8_termination::checkpoint(tc);
            }
            let serialized =
                serialized.filter(|_| !tc.has_terminated() && !tc.is_execution_terminating());
            match serialized {
                Some(value) => {
                    let bytes = value.to_rust_string_lossy(tc).into_bytes();
                    // V8's C++ JSON API converts the undefined result to the
                    // string "undefined". It is not a serialized JSON value;
                    // this also covers toJSON() returning undefined.
                    if bytes == b"undefined" {
                        return Err(V8BindingError::Unsupported {
                            interface: "Response".into(),
                            member: "data is not JSON serializable".into(),
                        });
                    }
                    bytes
                }
                None if tc.has_terminated() || tc.is_execution_terminating() => {
                    tc.rethrow();
                    return Err(V8BindingError::JavaScriptException);
                }
                None if tc.has_caught() => {
                    tc.rethrow();
                    return Err(V8BindingError::JavaScriptException);
                }
                None => {
                    return Err(V8BindingError::Unsupported {
                        interface: "Response".into(),
                        member: "data is not JSON serializable".into(),
                    });
                }
            }
        };
        let (headers_id, status, status_text) = initialize_response(scope, &state, init, true)?;
        add_body_content_type(&state, headers_id, Some("application/json".into()))?;
        let body_stream_id = Some(new_byte_stream_record(scope, &state, body.clone())?);
        let id = register_platform_object(
            &state,
            PlatformObjectRecord::Response(ResponseRecord {
                timing: None,
                internal_response: None,
                body_owner: None,
                response_type: "default",
                status_text,
                redirected: false,
                status,
                url: String::new(),
                headers_id,
                body_stream_id,
                bytes: body,
                body_used: false,
                signal_id: None,
            }),
        );
        new_platform_object(scope, &state, "Response", id)
    })();
    match result {
        Ok(value) => return_value.set(value.into()),
        Err(error) => throw_binding_error(scope, &error),
    }
}

fn parse_dom_parser_document<'s>(
    scope: &mut v8::PinScope<'s, '_>,
    state: &Rc<V8BindingState>,
    markup: &str,
    media_type: &str,
) -> Result<v8::Local<'s, v8::Object>, V8BindingError> {
    let mut parsed = if media_type == "text/html" {
        oryn_dom::html::parse_inert_dom_string(markup)
    } else {
        oryn_dom::xml::parse(markup, media_type)
    };
    if let Some(metadata) = parsed
        .dom
        .get_mut(parsed.document)?
        .document_metadata
        .as_mut()
    {
        metadata.url = Some(state.request_initiator_url()?);
    }
    let document = state
        .dom
        .borrow_mut()
        .import_subtree(&parsed.dom, parsed.document)?;
    state.derive_document_provenance(state.document_root(), document)?;
    wrap_node(scope, state, document)
}

