    #[test]
    fn automation_click_readiness_distinguishes_covering_elements_from_missing_geometry() {
        initialize_v8();
        let dom = Rc::new(RefCell::new(
            html::parse("<main><button id='target'>go</button><div id='cover'></div></main>")
                .into_runtime()
                .unwrap(),
        ));
        let target = dom.borrow().find_by_id("target").unwrap();
        let cover = dom.borrow().find_by_id("cover").unwrap();
        let mut isolate = v8::Isolate::new(Default::default());
        v8::scope!(let scope,&mut isolate);
        let context = v8::Context::new(scope, Default::default());
        let scope = &mut v8::ContextScope::new(scope, context);
        let state = install_generated_bindings(scope, context, dom, RealmId(0), 1).unwrap();
        let rect = BindingRect {
            x: 0.,
            y: 0.,
            width: 20.,
            height: 20.,
        };
        state.set_layout(BindingLayout {
            viewport: Some((100., 100.)),
            geometry: [target, cover]
                .into_iter()
                .map(|node| (node_key(node), BindingGeometry::Available(rect)))
                .collect(),
            styles: BTreeMap::from([(
                node_key(cover),
                std::sync::Arc::new(BTreeMap::from([
                    ("position".into(), "absolute".into()),
                    ("z-index".into(), "10".into()),
                ])),
            )]),
            ..Default::default()
        });
        assert_eq!(
            native_automation_click_ready(&state, target).unwrap(),
            Some(false)
        );
        state.set_layout(BindingLayout {
            viewport: Some((100., 100.)),
            geometry: BTreeMap::from([(node_key(target), BindingGeometry::Available(rect))]),
            ..Default::default()
        });
        assert_eq!(
            native_automation_click_ready(&state, target).unwrap(),
            Some(true)
        );
        state.set_layout(BindingLayout {
            viewport: Some((100., 100.)),
            geometry: BTreeMap::from([(node_key(target), BindingGeometry::Hidden)]),
            ..Default::default()
        });
        assert_eq!(native_automation_click_ready(&state, target).unwrap(), None);
        state.set_layout(BindingLayout {
            viewport: Some((100., 100.)),
            ..Default::default()
        });
        assert!(matches!(
            native_automation_click_ready(&state, target),
            Err(V8BindingError::Unsupported { .. })
        ));
    }

