    #[test]
    fn bitmap_and_offscreen_transfers_preserve_pixels_identity_and_atomicity() {
        check_global_event_prototype_script(
            r#"(()=>{
            const surface=new OffscreenCanvas(2,1),ctx=surface.getContext('2d');
            if(!(ctx instanceof OffscreenCanvasRenderingContext2D)||ctx.canvas!==surface||ctx!==surface.getContext('2d'))throw Error('native offscreen owner');
            ctx.fillStyle='red';ctx.fillRect(0,0,1,1);ctx.fillStyle='blue';ctx.fillRect(1,0,1,1);
            const bitmap=surface.transferToImageBitmap(),copy=structuredClone({bitmap,again:bitmap});
            if(copy.bitmap!==copy.again||copy.bitmap===bitmap||!(copy.bitmap instanceof ImageBitmap)||copy.bitmap.width!==2)throw Error('bitmap graph');
            if(ctx.getImageData(0,0,1,1).data[3]!==0)throw Error('transfer resets surface pixels');
            ctx.drawImage(copy.bitmap,0,0);const pixels=ctx.getImageData(0,0,2,1).data;
            if(pixels[0]!==255||pixels[3]!==255||pixels[6]!==255)throw Error('bitmap pixel snapshot');
            let error;try{structuredClone({bitmap,bad:()=>{}},{transfer:[bitmap]})}catch(e){error=e}
            if(error?.name!=='DataCloneError'||bitmap.width!==2)throw Error('failed clone must not detach');
            const moved=structuredClone(bitmap,{transfer:[bitmap]});if(bitmap.width!==0||bitmap.height!==0||moved.width!==2)throw Error('bitmap transfer');
            moved.close();moved.close();if(moved.width!==0)throw Error('bitmap close');
            error=undefined;try{structuredClone(moved)}catch(e){error=e}if(error?.name!=='DataCloneError')throw Error('detached bitmap clone');
            const transferable=new OffscreenCanvas(7,3);error=undefined;try{structuredClone(transferable)}catch(e){error=e}if(error?.name!=='DataCloneError')throw Error('offscreen requires transfer');
            const received=structuredClone(transferable,{transfer:[transferable]});if(received.width!==7||received.height!==3||transferable.width!==0||!(received instanceof OffscreenCanvas))throw Error('offscreen transfer');
            received.getContext('2d');error=undefined;try{structuredClone(received,{transfer:[received]})}catch(e){error=e}if(error?.name!=='InvalidStateError'||received.width!==7)throw Error('context transfer lock');
            const pending=new OffscreenCanvas(4,4),buffer=new ArrayBuffer(4);error=undefined;try{structuredClone({get x(){pending.getContext('2d');return 1}},{transfer:[pending,buffer]})}catch(e){error=e}if(error?.name!=='InvalidStateError'||buffer.byteLength!==4||pending.width!==4)throw Error('getter revalidation');
            return true;
        })()"#,
        );
    }

