        v8::scope!(let scope,&mut isolate);
        let context = v8::Context::new(scope, Default::default());
        let scope = &mut v8::ContextScope::new(scope, context);
        install_generated_bindings(scope, context, dom, RealmId(0), 1).unwrap();
        let source=v8::String::new(scope,r#"globalThis.bitmapResult=false;(async()=>{const data=new ImageData(new Uint8ClampedArray([255,0,0,255,0,0,255,255]),2,1);const promise=createImageBitmap(data,1,0,1,1);data.data.fill(0);const bitmap=await promise;const surface=new OffscreenCanvas(1,1),ctx=surface.getContext('2d');ctx.drawImage(bitmap,0,0);if(ctx.getImageData(0,0,1,1).data[2]!==255)throw Error('snapshot/crop');let error;try{await createImageBitmap(data,0,0,0,1)}catch(e){error=e}if(!(error instanceof RangeError))throw Error('zero crop');bitmap.close();error=undefined;try{await createImageBitmap(bitmap)}catch(e){error=e}if(error?.name!=='InvalidStateError')throw Error('closed source');globalThis.bitmapResult=true;})().catch(error=>globalThis.bitmapError=String(error))"#).unwrap();
        v8::Script::compile(scope, source, None)
            .unwrap()
            .run(scope)
            .unwrap();
