    #[test]
    fn matrix_prototypes_share_readonly_operations_and_native_attributes() {
        check_global_event_prototype_script(
            r#"(() => {
            const mutable=new DOMMatrix(),readonly=new DOMMatrixReadOnly();
            if(!(mutable instanceof DOMMatrixReadOnly)||Object.getPrototypeOf(DOMMatrix.prototype)!==DOMMatrixReadOnly.prototype)throw Error('matrix inheritance');
            if(Object.keys(mutable).length||Object.keys(readonly).length)throw Error('own matrix properties');
            for(const name of ['inverse','multiply','translate','toJSON','transformPoint']) {
                if(!Object.hasOwn(DOMMatrixReadOnly.prototype,name)||Object.hasOwn(DOMMatrix.prototype,name)||mutable[name]!==readonly[name])throw Error('readonly method ownership');
            }
            for(const name of ['invertSelf','multiplySelf','translateSelf']) {
                if(!Object.hasOwn(DOMMatrix.prototype,name)||name in readonly)throw Error('mutable method ownership');
            }
            for(const name of ['a','m11','f','m44']) {
                const read=Object.getOwnPropertyDescriptor(DOMMatrixReadOnly.prototype,name);
                const write=Object.getOwnPropertyDescriptor(DOMMatrix.prototype,name);
                if(!read.get||read.set||!write.get||!write.set||!write.enumerable||!write.configurable)throw Error('matrix descriptors');
            }
            mutable.a=2;if(mutable.m11!==2||Object.hasOwn(mutable,'a'))throw Error('native matrix assignment');
            const snapshot=document.createElement('canvas').getContext('2d').getTransform();
            return Object.keys(snapshot).length===0&&snapshot.inverse===readonly.inverse;
        })()"#,
        );
    }

    #[test]
    fn point_prototypes_own_accessors_and_operations_without_instance_copies() {
        check_global_event_prototype_script(
            r#"(() => {
            const point=new DOMPoint(1,2),readonly=new DOMPointReadOnly(3,4);
            if(Object.getPrototypeOf(DOMPoint.prototype)!==DOMPointReadOnly.prototype||!(point instanceof DOMPointReadOnly))throw Error('point inheritance');
            if(Object.keys(point).length||Object.keys(readonly).length)throw Error('instance geometry members');
            if(Object.hasOwn(DOMPoint.prototype,'toJSON')||!Object.hasOwn(DOMPointReadOnly.prototype,'toJSON'))throw Error('operation ownership');
            for(const name of ['x','y','z','w']) {
                const mutable=Object.getOwnPropertyDescriptor(DOMPoint.prototype,name);
                const read=Object.getOwnPropertyDescriptor(DOMPointReadOnly.prototype,name);
                if(!mutable.get||!mutable.set||!read.get||read.set||!mutable.enumerable||!mutable.configurable)throw Error('coordinate descriptors');
                let error;try{read.get.call({})}catch(e){error=e}
                if(!(error instanceof TypeError))throw Error('forged point getter');
            }
            if(point.toJSON!==readonly.toJSON)throw Error('method identity');
            point.x=5;if(point.x!==5||Object.hasOwn(point,'x'))throw Error('native assignment');
            return true;
        })()"#,
        );
    }

