    #[test]
    fn geometry_factories_convert_dictionaries_and_preserve_declared_types() {
        check_global_event_prototype_script(
            r#"(() => {
            const point=DOMPoint.fromPoint({x:3,w:2});
            const readonly=DOMPointReadOnly.fromPoint(point);
            if(!(point instanceof DOMPoint)||!(readonly instanceof DOMPointReadOnly)||readonly.x!==3||readonly.w!==2)throw Error('point factories');
            point.x=4;if(readonly.x!==3)throw Error('factory aliases source');
            const factory=DOMPoint.fromPoint;
            if(!(factory.call(DOMPointReadOnly,{x:1}) instanceof DOMPoint))throw Error('factory used caller constructor');
            const matrix=DOMMatrix.fromMatrix({a:2,e:4,is2D:false});
            const readMatrix=DOMMatrixReadOnly.fromMatrix(matrix);
            if(matrix.is2D||readMatrix.is2D||readMatrix.a!==2||readMatrix.e!==4)throw Error('matrix factory classification');
            const order=[];DOMPoint.fromPoint(new Proxy({}, {get(_,key){order.push(key)}}));
            if(order.join()!=='w,x,y,z')throw Error('point factory dictionary order');
            let error;try{DOMMatrix.fromMatrix({a:1,m11:2})}catch(e){error=e}
            if(!(error instanceof TypeError))throw Error('matrix factory alias validation');
            return DOMPoint.fromPoint().w===1&&DOMMatrix.fromMatrix().isIdentity;
        })()"#,
        );
    }

    #[test]
    fn point_matrix_transform_uses_native_receiver_and_shared_2d_rules() {
        check_global_event_prototype_script(
            r#"(() => {
            const point=new DOMPoint(1,2,0,1), matrix=new DOMMatrix([2,0,0,3,4,5]);
            const result=point.matrixTransform(matrix),other=matrix.transformPoint(point);
            if(result.x!==6||result.y!==11||JSON.stringify(result)!==JSON.stringify(other)||result===point)throw Error('point matrix transform');
            Object.defineProperty(point,'x',{get(){throw Error('author receiver getter')}});
            if(point.matrixTransform(matrix).x!==6)throw Error('native point read');
            const readonly=new DOMPointReadOnly(2,3);
            if(!(readonly.matrixTransform() instanceof DOMPoint)||readonly.matrixTransform().x!==2)throw Error('readonly transform');
            const nonfinite=new DOMPoint(Infinity,NaN);
            const transformed=nonfinite.matrixTransform();
            if(transformed.z!==0||transformed.w!==1)throw Error('2D nonfinite z/w');
            const viaMatrix=new DOMMatrix().transformPoint(nonfinite);
            if(viaMatrix.z!==0||viaMatrix.w!==1)throw Error('matrix 2D nonfinite z/w');
            const mutable=new DOMPoint(1,2);
            const changed=mutable.matrixTransform({get a(){mutable.x=4;return 2}});
            if(changed.x!==8)throw Error('argument conversion ordering');
            return true;
        })()"#,
        );
    }

