    #[test]
    fn matrix_rotation_uses_degrees_axes_and_vector_direction() {
        check_global_event_prototype_script(
            r#"(() => {
            const close=(a,b)=>Math.abs(a-b)<1e-12;
            const identity=new DOMMatrix(),quarter=identity.rotate(90);
            if(!close(quarter.a,0)||!close(quarter.b,1)||!close(quarter.c,-1)||!quarter.is2D||!identity.isIdentity)throw Error('2D rotation');
            const axis=identity.rotateAxisAngle(0,0,5,90);
            if(!close(axis.b,1)||!axis.is2D)throw Error('axis normalization');
            const x=identity.rotate(90,0,0);
            if(x.is2D||!close(x.m23,1)||!close(x.m32,-1))throw Error('X rotation');
            const composition=identity.rotate(30,40,50);
            const sequential=identity.rotateAxisAngle(0,0,1,50).rotateAxisAngle(0,1,0,40).rotateAxisAngle(1,0,0,30);
            if(!Array.from(composition.toFloat64Array()).every((v,i)=>close(v,sequential.toFloat64Array()[i])))throw Error('Euler order');
            const vector=identity.rotateFromVector(0,-2);
            if(!close(vector.b,-1)||!vector.is2D)throw Error('vector direction');
            if(!identity.rotateFromVector(0,0).isIdentity||!identity.rotateAxisAngle(0,0,0,90).isIdentity)throw Error('zero vector');
            const mutable=new DOMMatrix();if(mutable.rotateSelf(90)!==mutable||!close(mutable.b,1))throw Error('inplace rotation');
            return true;
        })()"#,
        );
    }

