    #[test]
    fn matrix_multiplication_orders_and_dictionary_validation() {
        check_global_event_prototype_script(
            r#"(() => {
            const scale=new DOMMatrix([2,0,0,3,0,0]);
            const translation=new DOMMatrix([1,0,0,1,4,5]);
            const product=scale.multiply(translation);
            if(product.e!==8||product.f!==15||scale.e!==0)throw Error('post multiplication');
            if(scale.preMultiplySelf(translation)!==scale||scale.e!==4||scale.f!==5)throw Error('pre multiplication');
            if(scale.multiplySelf({e:1,f:1})!==scale||scale.e!==6||scale.f!==8)throw Error('inplace multiplication');
            const before=scale.toFloat64Array().join();
            for(const invalid of [{a:1,m11:2},{is2D:true,m13:1},1]) {
                let error;try{scale.multiplySelf(invalid)}catch(e){error=e}
                if(!(error instanceof TypeError)||scale.toFloat64Array().join()!==before)throw Error('dictionary validation');
            }
            const three=scale.multiply({is2D:false});if(three.is2D)throw Error('explicit 3D lost');
            const ordered=new DOMMatrix();const gets=[];
            ordered.multiplySelf(new Proxy({a:2,get m11(){ordered.e=7;return 2}},
                {get(target,key){gets.push(key);return Reflect.get(target,key)}}));
            if(ordered.a!==2||ordered.e!==7||gets.join()!=='a,b,c,d,e,f,is2D,m11,m12,m13,m14,m21,m22,m23,m24,m31,m32,m33,m34,m41,m42,m43,m44')throw Error('conversion order');
            const readonly=new DOMMatrixReadOnly();
            if(!(readonly.multiply({e:2}) instanceof DOMMatrix))throw Error('readonly result');
            return true;
        })()"#,
        );
    }

