    fn matrix_inverse_and_exports_preserve_native_values_and_identity() {
        check_global_event_prototype_script(
            r#"(() => {
            const matrix=new DOMMatrix([2,0,0,4,6,8]);
            const inverse=matrix.inverse();
            if(inverse===matrix||inverse.a!==.5||inverse.d!==.25||inverse.e!==-3||inverse.f!==-2||!inverse.is2D)throw Error('affine inverse');
            if(matrix.a!==2||matrix.invertSelf()!==matrix||matrix.a!==.5)throw Error('inplace inverse');
            const array=matrix.toFloat64Array(), single=matrix.toFloat32Array();
            if(!(array instanceof Float64Array)||!(single instanceof Float32Array)||array.length!==16||array[12]!==-3)throw Error('matrix arrays');
            array[0]=99;if(matrix.a!==.5)throw Error('array aliases storage');
            const json=matrix.toJSON();json.a=99;
            if(matrix.a!==.5||json.m11!==.5||!json.is2D)throw Error('JSON snapshot');
            const readonly=new DOMMatrixReadOnly([1,0,0,1,4,5]);
            if(!(readonly.inverse() instanceof DOMMatrix)||readonly.inverse().e!==-4)throw Error('readonly inverse');
            let error;try{matrix.invertSelf.call(readonly)}catch(e){error=e}
            if(!(error instanceof TypeError)||readonly.e!==4)throw Error('readonly mutation');
            const singular=new DOMMatrix([0,0,0,0,0,0]);singular.invertSelf();
            if(singular.is2D||singular.isIdentity||!Array.from(singular.toFloat64Array()).every(Number.isNaN))throw Error('singular inverse');
            const three=new DOMMatrix([2,0,0,0,0,4,0,0,0,0,8,0,6,8,16,1]);
            const inv=three.inverse();
            if(inv.is2D||inv.m33!==.125||inv.m43!==-2||inv.e!==-3||inv.f!==-2)throw Error('3D inverse');
            return true;
        })()"#,
        );
    }

    #[test]
    fn matrix_sequence_conversion_closes_iterator_and_preserves_original_exception() {
        check_global_event_prototype_script(
            r#"(() => {
            const original={original:true};
            for(const close of [()=>({}),()=>{throw Error('close failure')},()=>1]) {
                let closed=0;
                const iterable={[Symbol.iterator](){return {
                    next(){return {done:false,value:{valueOf(){throw original}}}},
                    return(){closed++;return close()}
                }}};
                let error;try{new DOMMatrix(iterable)}catch(e){error=e}
                if(error!==original||closed!==1)throw Error('IteratorClose completion');
            }
            let returned=0;
            const brokenNext={[Symbol.iterator](){return {next(){throw original},return(){returned++;return {}}}}};
            let error;try{new DOMMatrix(brokenNext)}catch(e){error=e}
            if(error!==original||returned!==0)throw Error('closed an abrupt iterator step');
            return true;
        })()"#,
        );
    }

