    #[test]
    fn canvas_transform_snapshots_are_native_independent_and_alias_linked() {
        check_global_event_prototype_script(
            r#"(() => {
            const c=document.createElement('canvas'),ctx=c.getContext('2d');
            const Matrix=DOMMatrix;globalThis.DOMMatrix=function(){throw Error('author constructor invoked')};
            const identity=ctx.getTransform();
            if(!(identity instanceof Matrix)||!identity.isIdentity||!identity.is2D)throw Error('matrix identity');
            ctx.setTransform(2,3,4,5,6,7);
            const snapshot=ctx.getTransform();
            if([snapshot.a,snapshot.b,snapshot.c,snapshot.d,snapshot.e,snapshot.f].join()!=='2,3,4,5,6,7')throw Error('matrix components');
            if(identity.a!==1||identity.e!==0)throw Error('live matrix snapshot');
            snapshot.a=8;if(snapshot.m11!==8)throw Error('alias did not update');
            snapshot.m42=9;if(snapshot.f!==9)throw Error('canonical did not update');
            if(ctx.getTransform().a!==2)throw Error('snapshot changed canvas');
            ctx.setTransform(snapshot);
            if(ctx.getTransform().a!==8||ctx.getTransform().f!==9)throw Error('matrix round trip');
            const getter=Object.getOwnPropertyDescriptor(Matrix.prototype,'a').get;
            if(DOMMatrix===Matrix)throw Error('author constructor replacement was lost');
            let rejected=false;try{getter.call({a:1})}catch(e){rejected=e instanceof TypeError}
            return rejected;
        })()"#,
        );
    }

    #[test]
    fn canvas_quad_coverage_handles_winding_centroids_and_outside_pixels() {
        let quad = [(0.0, 0.5), (0.5, 0.0), (1.0, 0.5), (0.5, 1.0)];
        let (coverage, x, y) = canvas_pixel_coverage(&quad, 0, 0);
        assert!((coverage - 0.5).abs() < 1e-12);
        assert!((x - 0.5).abs() < 1e-12 && (y - 0.5).abs() < 1e-12);
        let mut reversed = quad;
        reversed.reverse();
        let reverse = canvas_pixel_coverage(&reversed, 0, 0);
        assert!((reverse.0 - coverage).abs() < 1e-12);
        assert!((reverse.1 - x).abs() < 1e-12 && (reverse.2 - y).abs() < 1e-12);
        assert_eq!(canvas_pixel_coverage(&quad, 1, 0).0, 0.0);
        let shifted = quad.map(|(x, y)| (x + 100000.0, y + 100000.0));
        assert!((canvas_pixel_coverage(&shifted, 100000, 100000).0 - 0.5).abs() < 1e-12);
    }

