    #[test]
    fn canvas_context_identity_owner_and_receiver_checks() {
        initialize_v8();
        let dom = Rc::new(RefCell::new(
            html::parse(
                "<canvas id=a width=1 height=1></canvas><canvas id=b width=1 height=1></canvas>",
            )
            .into_runtime()
            .unwrap(),
        ));
        let mut isolate = v8::Isolate::new(Default::default());
        v8::scope!(let scope, &mut isolate);
        let context = v8::Context::new(scope, Default::default());
        let scope = &mut v8::ContextScope::new(scope, context);
        let _state = install_generated_bindings(scope, context, dom, RealmId(0), 1).unwrap();
        let source = v8::String::new(scope, r#"
            const a=document.getElementById('a'),b=document.getElementById('b');
            const first=a.getContext('2d'),second=b.getContext('2d');
            if(first!==a.getContext('2d')||first===second||first.canvas!==a)throw Error('context identity');
            first.customProperty=42;a.width=1;
            if(a.getContext('2d')!==first||first.customProperty!==42)throw Error('resize replaced context');
            const ownerGetter=Object.getOwnPropertyDescriptor(CanvasRenderingContext2D.prototype,'canvas').get;
            for(const operation of [()=>first.fillRect.call({},0,0,1,1),
                ()=>first.clearRect.call({},0,0,1,1),()=>first.save.call({}),
                ()=>first.getImageData.call({},0,0,1,1),()=>ownerGetter.call({})]) {
                let error;try{operation()}catch(e){error=e}
                if(!(error instanceof TypeError))throw Error('forged receiver accepted');
            }
            second.fillStyle='red';first.fillRect.call(second,0,0,1,1);
            if(first.getImageData(0,0,1,1).data[3]!==0)throw Error('borrowed method used original canvas');
            if(second.getImageData(0,0,1,1).data[0]!==255)throw Error('borrowed method missed receiver');
            a.remove();if(first.canvas!==a||a.getContext('2d')!==first)throw Error('detached identity');
        "#).unwrap();
        v8::Script::compile(scope, source, None)
            .unwrap()
            .run(scope)
            .unwrap();
    }

    #[test]
    fn canvas_drawing_state_saves_restores_and_resets_without_restoring_pixels() {
        initialize_v8();
        let dom = Rc::new(RefCell::new(
            html::parse("<canvas id=c width=2 height=1></canvas>")
                .into_runtime()
                .unwrap(),
        ));
        let mut isolate = v8::Isolate::new(Default::default());
        v8::scope!(let scope, &mut isolate);
        let context = v8::Context::new(scope, Default::default());
        let scope = &mut v8::ContextScope::new(scope, context);
        let _state = install_generated_bindings(scope, context, dom, RealmId(0), 1).unwrap();
        let source = v8::String::new(scope, r#"
            const c=document.getElementById('c'),ctx=c.getContext('2d');
            if(ctx.globalAlpha!==1||ctx.imageSmoothingEnabled!==true)throw Error('defaults');
            ctx.fillStyle='red';ctx.globalAlpha=.5;ctx.imageSmoothingEnabled=false;ctx.save();
            for(const invalid of [-1,2,NaN,Infinity,-Infinity]){
                ctx.globalAlpha=invalid;if(ctx.globalAlpha!==.5)throw Error('invalid alpha accepted');
            }
            ctx.fillRect(0,0,1,1);
            ctx.globalAlpha=1;ctx.fillStyle='blue';ctx.imageSmoothingEnabled=true;ctx.save();
            ctx.fillStyle='green';ctx.restore();
            if(ctx.fillStyle!=='#0000ff'||ctx.globalAlpha!==1||!ctx.imageSmoothingEnabled)throw Error('nested restore');
            ctx.restore();
            if(ctx.fillStyle!=='#ff0000'||ctx.globalAlpha!==.5||ctx.imageSmoothingEnabled)throw Error('outer restore');
            if(Array.from(ctx.getImageData(0,0,1,1).data).join()!=='255,0,0,128')throw Error('saved bitmap or wrong alpha');
            ctx.restore();if(ctx.globalAlpha!==.5)throw Error('empty restore');
            ctx.save();c.width=2;ctx.restore();
            if(ctx.fillStyle!=='#000000'||ctx.globalAlpha!==1||!ctx.imageSmoothingEnabled)throw Error('resize kept saved state');
            ctx.globalAlpha=0;ctx.fillRect(0,0,2,1);
            if(ctx.getImageData(0,0,1,1).data[3]!==0)throw Error('zero alpha');
        "#).unwrap();
        v8::Script::compile(scope, source, None)
            .unwrap()
            .run(scope)
            .unwrap();
    }

