    #[test]
    fn image_requests_use_native_base_and_deliver_trusted_completion_events() {
        #[derive(Default)]
        struct ImageHost(RefCell<Vec<(String, Option<String>)>>);
        impl PlatformHost for ImageHost {
            fn retire(&self) {}
            fn submit(
                &self,
                _: HostOperationId,
                request: PlatformHostRequest,
            ) -> Result<(), String> {
                if let PlatformHostRequest::ImageStart { request, .. } = request {
                    self.0
                        .borrow_mut()
                        .push((request.url, request.initiator_url));
                }
                Ok(())
            }
            fn cancel(&self, _: HostOperationId) {}
            fn drain_completions(&self, _: usize) -> Vec<PlatformHostCompletion> {
                Vec::new()
            }
        }
        {
            let element = "img";
            initialize_v8();
            let dom = Rc::new(RefCell::new(
                html::parse("<base href='/assets/'><body></body>")
                    .into_runtime()
                    .unwrap(),
            ));
            let mut isolate = v8::Isolate::new(Default::default());
            v8::scope!(let scope, &mut isolate);
            let context = v8::Context::new(scope, Default::default());
            let scope = &mut v8::ContextScope::new(scope, context);
            let state =
                install_generated_bindings(scope, context, dom.clone(), RealmId(0), 1).unwrap();
            state.commit_location("https://example.test/page").unwrap();
            let host = Rc::new(ImageHost::default());
            state.set_platform_host(host.clone());
            let source_text = r#"
            globalThis.events=[];Object.defineProperty(document,'baseURI',{value:'https://wrong.test/'});
            for(const id of ['good','bad']) {
                const img=document.createElement('ELEMENT');img.id=id;img.setAttribute('SOURCE',id+'.svg');
                img.dispatchEvent=()=>{throw Error('author dispatcher used')};
                for(const type of ['load','error'])img.addEventListener(type,event=>events.push(
                    [id,type,event.isTrusted,event.bubbles,event.cancelable,event.target===img].join(':')));
                document.body.appendChild(img);
            }
            globalThis.Event=function(){throw Error('author constructor used')};
        "#.replace("ELEMENT",element).replace("SOURCE",if element=="object"{"data"}else{"src"});
            let source = v8::String::new(scope, &source_text).unwrap();
            v8::Script::compile(scope, source, None)
                .unwrap()
                .run(scope)
                .unwrap();
            assert_eq!(
                *host.0.borrow(),
                vec![
                    (
                        "https://example.test/assets/good.svg".into(),
                        Some("https://example.test/page".into())
                    ),
                    (
                        "https://example.test/assets/bad.svg".into(),
                        Some("https://example.test/page".into())
                    ),
                ]
            );
            let good = dom.borrow().find_by_id("good").unwrap();
            let bad = dom.borrow().find_by_id("bad").unwrap();
            let generation = *state.image_generations.borrow().get(&good).unwrap();
            state
                .pending_platform_operations
                .borrow_mut()
                .remove(&generation);
            state.pending_platform_operations.borrow_mut().insert(
                generation,
                PendingPlatformOperation::ImageRead {
                    node: good,
                    generation,
                    stream_id: 77,
                    origin_clean: true,
                    _root: submissions::RootedTarget::new(&state, good).unwrap(),
                    bytes: Vec::new(),
                },
            );
            state.handle_platform_completion(scope, PlatformHostCompletion {
            operation_id: generation, result: Ok(PlatformHostResult::HttpChunk {encoded_body_size:None, stream_id: 77,
                bytes: br#"<svg xmlns="http://www.w3.org/2000/svg" width="20" height="10"/>"#.to_vec(), done: true }),
        }).unwrap();
            let failed = *state.image_generations.borrow().get(&bad).unwrap();
            state
                .handle_platform_completion(
                    scope,
                    PlatformHostCompletion {
                        operation_id: failed,
                        result: Err("image load failed".into()),
                    },
                )
                .unwrap();
            assert_eq!(
                dom.borrow().arena().get(good).unwrap().image_dimensions,
                Some((20, 10))
            );
            assert_eq!(
                dom.borrow().arena().get(bad).unwrap().image_dimensions,
                None
            );
            assert!(state.decoded_svg_images.borrow().contains_key(&good));
            let source = v8::String::new(scope, "events.join(',')").unwrap();
            assert_eq!(
                v8::Script::compile(scope, source, None)
                    .unwrap()
                    .run(scope)
                    .unwrap()
                    .to_rust_string_lossy(scope),
                "good:load:true:false:false:true,bad:error:true:false:false:true"
            );
        }
    }

    #[test]
    fn new_document_stream_cancels_image_read_and_ignores_late_pixels() {
        #[derive(Default)]
        struct ImageHost(RefCell<Vec<u64>>);
        impl PlatformHost for ImageHost {
            fn retire(&self) {}
            fn submit(
                &self,
                _: HostOperationId,
                request: PlatformHostRequest,
            ) -> Result<(), String> {
                if let PlatformHostRequest::HttpAbort { stream_id } = request {
                    self.0.borrow_mut().push(stream_id);
                }
                Ok(())
            }
            fn cancel(&self, _: HostOperationId) {}
            fn drain_completions(&self, _: usize) -> Vec<PlatformHostCompletion> {
                Vec::new()
            }
        }
        initialize_v8();
        let dom = Rc::new(RefCell::new(
            html::parse("<img id=image>").into_runtime().unwrap(),
        ));
        let node = dom.borrow().find_by_id("image").unwrap();
        let mut isolate = v8::Isolate::new(Default::default());
        v8::scope!(let scope, &mut isolate);
        let context = v8::Context::new(scope, Default::default());
        let scope = &mut v8::ContextScope::new(scope, context);
        let state = install_generated_bindings(scope, context, dom.clone(), RealmId(0), 1).unwrap();
        let host = Rc::new(ImageHost::default());
        state.set_platform_host(host.clone());
        let operation = HostOperationId(10);
        state.image_generations.borrow_mut().insert(node, operation);
        state.image_sources.borrow_mut().insert(
            node,
            ImageRequestKey {
                source: "old.svg".into(),
                ..Default::default()
            },
        );
        state.pending_platform_operations.borrow_mut().insert(
            operation,
            PendingPlatformOperation::ImageRead {
                node,
                generation: operation,
                stream_id: 55,
                origin_clean: true,
                _root: submissions::RootedTarget::new(&state, node).unwrap(),
                bytes: Vec::new(),
            },
        );
        state.images_deferred.set(true);
        state.advance_document_stream_epoch().unwrap();
        assert!(!state.has_pending_images());
        assert!(!state.image_sources.borrow().contains_key(&node));
        assert_eq!(*host.0.borrow(), vec![55]);
        state
            .handle_platform_completion(
                scope,
                PlatformHostCompletion {
                    operation_id: operation,
                    result: Ok(PlatformHostResult::HttpChunk {
                        encoded_body_size: None,
                        stream_id: 55,
                        bytes:
                            br#"<svg xmlns="http://www.w3.org/2000/svg" width="20" height="10"/>"#
                                .to_vec(),
                        done: true,
                    }),
                },
            )
            .unwrap();
        assert_eq!(
            dom.borrow().arena().get(node).unwrap().image_dimensions,
            None
        );
        assert!(!state.decoded_images.borrow().contains_key(&node));
    }

    #[test]
    fn borrowed_insertion_prepares_images_in_owner_document_environment() {
        #[derive(Default)]
        struct ImageHost(RefCell<Vec<String>>);
        impl PlatformHost for ImageHost {
            fn retire(&self) {}
            fn submit(
                &self,
                _: HostOperationId,
                request: PlatformHostRequest,
            ) -> Result<(), String> {
                if let PlatformHostRequest::ImageStart { request, .. } = request {
                    self.0.borrow_mut().push(request.url);
                }
                Ok(())
            }
            fn cancel(&self, _: HostOperationId) {}
            fn drain_completions(&self, _: usize) -> Vec<PlatformHostCompletion> {
                Vec::new()
            }
        }
        initialize_v8();
        let dom = Rc::new(RefCell::new(
            html::parse("<body><iframe id=frame></iframe></body>")
                .into_runtime()
                .unwrap(),
        ));
        let child = html::parse("<body></body>");
        let child_document = dom
            .borrow_mut()
            .import_subtree(&child.dom, child.document)
            .unwrap();
        let frame = dom.borrow().find_by_id("frame").unwrap();
        dom.borrow_mut()
            .set_hosted_document(frame, Some(child_document))
            .unwrap();
        let mut isolate = v8::Isolate::new(Default::default());
        v8::scope!(let scope, &mut isolate);
        let parent = v8::Context::new(scope, Default::default());
        let child = v8::Context::new(scope, Default::default());
        child.set_security_token(parent.get_security_token(scope));
        let parent_host = Rc::new(ImageHost::default());
        let child_host = Rc::new(ImageHost::default());
        {
            let scope = &mut v8::ContextScope::new(scope, child);
            let state = install_generated_bindings_with_root(
                scope,
                child,
                dom.clone(),
                RealmId(1),
                1,
                child_document,
            )
            .unwrap();
            state.set_platform_host(child_host.clone());
            state
                .commit_location("https://example.test/child/page")
                .unwrap();
        }
        {
            let scope = &mut v8::ContextScope::new(scope, parent);
            let state = install_generated_bindings(scope, parent, dom, RealmId(0), 1).unwrap();
            state
                .commit_location("https://example.test/parent/page")
                .unwrap();
            state.set_platform_host(parent_host.clone());
            let key = v8::String::new(scope, "child").unwrap();
            parent
                .global(scope)
                .set(scope, key.into(), child.global(scope).into());
            let source = v8::String::new(
                scope,
                r#"
                const image=document.createElement('img');image.src='picture.png';
                Node.prototype.appendChild.call(child.document.body,image);
                Object.getOwnPropertyDescriptor(HTMLImageElement.prototype,'src').set.call(image,'second.png');
            "#,
            )
            .unwrap();
            v8::Script::compile(scope, source, None)
                .unwrap()
                .run(scope)
                .unwrap();
        }
        assert!(parent_host.0.borrow().is_empty());
        assert_eq!(
            *child_host.0.borrow(),
            vec![
                "https://example.test/child/picture.png",
                "https://example.test/child/second.png"
            ]
        );
    }

    #[test]
    fn fetch_xhr_and_images_ignore_author_policy_global() {
        #[derive(Default)]
        struct RecordingHost {
            inner: TestPlatformHost,
            requests: RefCell<Vec<(String, Option<String>)>>,
        }
        impl PlatformHost for RecordingHost {
            fn retire(&self) {
                self.inner.retire();
            }
            fn submit(
                &self,
                id: HostOperationId,
                operation: PlatformHostRequest,
            ) -> Result<(), String> {
                if let PlatformHostRequest::HttpStart { request }
                | PlatformHostRequest::ImageStart { request, .. } = &operation
                {
                    self.requests
                        .borrow_mut()
                        .push((request.url.clone(), request.referrer_policy.clone()));
                }
                self.inner.submit(id, operation)
            }
            fn cancel(&self, id: HostOperationId) {
                self.inner.cancel(id);
            }
            fn drain_completions(&self, limit: usize) -> Vec<PlatformHostCompletion> {
                self.inner.drain_completions(limit)
            }
        }
        initialize_v8();
        let dom = Rc::new(RefCell::new(
            html::parse("<!doctype html><body></body>")
                .into_runtime()
                .unwrap(),
        ));
        let mut isolate = v8::Isolate::new(Default::default());
        v8::scope!(let scope, &mut isolate);
        let context = v8::Context::new(scope, Default::default());
        let scope = &mut v8::ContextScope::new(scope, context);
        let state = install_generated_bindings(scope, context, dom, RealmId(0), 1).unwrap();
        let host = Rc::new(RecordingHost::default());
        state.set_platform_host(host.clone());
        state.commit_location("https://example.test/page").unwrap();
        state.set_document_referrer_policy("same-origin").unwrap();
        let source = v8::String::new(scope, r#"
            Object.defineProperty(globalThis, '__oryn_referrer_policy', {
                get() { throw Error('policy getter must not run'); }
            });
            fetch('/default');
            fetch('/explicit', {referrerPolicy:'origin'});
            fetch('/none', {referrer:''});
            const xhr = new XMLHttpRequest(); xhr.open('GET', '/xhr'); xhr.send();
            const image = document.createElement('img'); image.src='/image'; document.body.appendChild(image);
        "#).unwrap();
        test_eval::run(scope, source);
        let expected: Vec<_> = [
            ("default", "same-origin"),
            ("explicit", "origin"),
            ("none", "no-referrer"),
            ("xhr", "same-origin"),
            ("image", "same-origin"),
        ]
        .into_iter()
        .map(|(path, policy)| {
            (
                format!("https://example.test/{path}"),
                Some(policy.to_string()),
            )
        })
        .collect();
        assert_eq!(*host.requests.borrow(), expected);
    }

    #[test]
    fn batch_meta_processing_preserves_fetch_policy_order() {
        #[derive(Default)]
        struct RecordingHost {
            inner: TestPlatformHost,
            requests: RefCell<Vec<(String, Option<String>)>>,
        }
        impl PlatformHost for RecordingHost {
            fn retire(&self) {
                self.inner.retire();
            }
            fn submit(
                &self,
                id: HostOperationId,
                request: PlatformHostRequest,
            ) -> Result<(), String> {
                if let PlatformHostRequest::HttpStart { request } = &request {
                    self.requests
                        .borrow_mut()
                        .push((request.url.clone(), request.referrer_policy.clone()));
                }
                self.inner.submit(id, request)
            }
            fn cancel(&self, id: HostOperationId) {
                self.inner.cancel(id);
            }
            fn drain_completions(&self, limit: usize) -> Vec<PlatformHostCompletion> {
                self.inner.drain_completions(limit)
            }
        }
        initialize_v8();
        for method in ["appendChild", "append", "prepend", "replaceChildren", "div"] {
            let dom = Rc::new(RefCell::new(
                html::parse("<!doctype html><body></body>")
                    .into_runtime()
                    .unwrap(),
            ));
            let mut isolate = v8::Isolate::new(Default::default());
            v8::scope!(let scope, &mut isolate);
            let context = v8::Context::new(scope, Default::default());
            let scope = &mut v8::ContextScope::new(scope, context);
            let state = install_generated_bindings(scope, context, dom, RealmId(0), 1).unwrap();
            let host = Rc::new(RecordingHost::default());
            state.set_platform_host(host.clone());
            let script = format!(
                "const insertionMethod = {method:?};\n{}",
                r#"
                globalThis.location.href='https://example.test/page';
                const initial = document.createElement('meta');
                initial.name = 'referrer'; initial.content = 'unsafe-url'; document.head.appendChild(initial);
                const before = document.createElement('script'), after = document.createElement('script');
                before.textContent = "fetch('https://example.test/before')";
                after.textContent = "fetch('https://example.test/after')";
                const meta = document.createElement('meta'); meta.name = 'referrer'; meta.content = 'no-referrer';
                const fragment = document.createDocumentFragment(); fragment.append(before, meta, after);
                if (insertionMethod === 'appendChild') document.head.appendChild(fragment);
                else if (insertionMethod === 'div') {
                    const div = document.createElement('div'); div.appendChild(fragment); document.head.appendChild(div);
                } else document.head[insertionMethod](before, meta, after);
            "#
            );
            let source = v8::String::new(scope, &script).unwrap();
            v8::Script::compile(scope, source, None)
                .unwrap()
                .run(scope)
                .unwrap();
            assert_eq!(
                *host.requests.borrow(),
                vec![
                    (
                        "https://example.test/before".into(),
                        Some("unsafe-url".into())
                    ),
                    (
                        "https://example.test/after".into(),
                        Some("no-referrer".into())
                    ),
                ],
                "{method}"
            );
        }
    }

    #[test]
    fn retired_observer_microtask_owner_cannot_capture_sibling_notifications() {
        initialize_v8();
        let mut isolate = v8::Isolate::new(Default::default());
        isolate.set_microtasks_policy(v8::MicrotasksPolicy::Explicit);
        v8::scope!(let scope,&mut isolate);
        let first = v8::Context::new(scope, Default::default());
        let second = v8::Context::new(scope, Default::default());
        let a = {
            let scope = &mut v8::ContextScope::new(scope, first);
            install_generated_bindings(
                scope,
                first,
                Rc::new(RefCell::new(
                    html::parse("<body></body>").into_runtime().unwrap(),
                )),
                RealmId(172),
                1,
            )
            .unwrap()
        };
        let b = {
            let scope = &mut v8::ContextScope::new(scope, second);
            let state = install_generated_bindings(
                scope,
                second,
                Rc::new(RefCell::new(
                    html::parse("<body></body>").into_runtime().unwrap(),
                )),
                RealmId(173),
                1,
            )
            .unwrap();
            let source=v8::String::new(scope,"var hits=0;var observer=new MutationObserver(()=>hits++);observer.observe(document.body,{attributes:true})").unwrap();
            v8::Script::compile(scope, source, None)
                .unwrap()
                .run(scope)
                .unwrap();
            state
        };
        let body = b
            .dom
            .borrow()
            .query_selector(b.document_root(), "body")
            .unwrap()
            .unwrap();
        b.dom
            .borrow_mut()
            .set_attribute(body, "data-value", "changed")
            .unwrap();
        let serial = {
            let scope = &mut v8::ContextScope::new(scope, first);
            queue_mutation_observer_microtask(scope);
            let registry = scope.get_slot::<BindingStateRegistry>().unwrap();
            assert!(registry.observer_microtask_queued.get());
            assert!(Rc::ptr_eq(
                &registry
                    .observer_microtask_owner
                    .borrow()
                    .as_ref()
                    .unwrap()
                    .upgrade()
                    .unwrap(),
                &a
            ));
            registry.observer_microtask_serial.get()
        };
        a.retire_execution();
        let scope = &mut v8::ContextScope::new(scope, second);
        queue_mutation_observer_microtask(scope);
        assert!(
            scope
                .get_slot::<BindingStateRegistry>()
                .unwrap()
                .observer_microtask_serial
                .get()
                > serial
        );
        // Leave the stale callback queued as well: it must not drain the new
        // batch or clear the newer notification's scheduling ownership.
        scope.perform_microtask_checkpoint();
        let source = v8::String::new(scope, "hits===1").unwrap();
        assert!(
            v8::Script::compile(scope, source, None)
                .unwrap()
                .run(scope)
                .unwrap()
                .is_true()
        );
        assert!(!has_pending_mutation_observer_microtask(scope));
    }

    #[test]
    fn parked_observer_and_slot_notifications_wait_without_blocking_active_siblings() {
        initialize_v8();
        for discard in [false, true] {
            let mut isolate = v8::Isolate::new(Default::default());
            isolate.set_microtasks_policy(v8::MicrotasksPolicy::Explicit);
            v8::scope!(let scope,&mut isolate);
            let first = v8::Context::new(scope, Default::default());
            let second = v8::Context::new(scope, Default::default());
            let log = {
                let scope = &mut v8::ContextScope::new(scope, first);
                let log = v8::Array::new(scope, 0);
                v8::Global::new(scope, log)
            };
            let log = v8::Local::new(scope, &log);
            let mut states = Vec::new();
            for (index, context, label) in [(0, first, "A"), (1, second, "B")] {
                let scope = &mut v8::ContextScope::new(scope, context);
                let state = install_generated_bindings(
                    scope,
                    context,
                    Rc::new(RefCell::new(
                        html::parse("<body></body>").into_runtime().unwrap(),
                    )),
                    RealmId(170 + index),
                    1,
                )
                .unwrap();
                let key = v8::String::new(scope, "log").unwrap();
                context
                    .global(scope)
                    .set(scope, key.into(), log.into())
                    .unwrap();
                let source=v8::String::new(scope,&format!("var observer=new MutationObserver(()=>log.push('{label}'));observer.observe(document.body,{{attributes:true}});document.body.addEventListener('slotchange',()=>log.push('{label}S'));")).unwrap();
                v8::Script::compile(scope, source, None)
                    .unwrap()
                    .run(scope)
                    .unwrap();
                states.push(state);
            }
            let scope = &mut v8::ContextScope::new(scope, second);
            queue_mutation_observer_microtask(scope);
            scope.perform_microtask_checkpoint();
            states[0].set_execution_suspended(true);
            for state in &states {
                let body = state
                    .dom
                    .borrow()
                    .query_selector(state.document_root(), "body")
                    .unwrap()
                    .unwrap();
                state
                    .dom
                    .borrow_mut()
                    .set_attribute(body, "data-value", "changed")
                    .unwrap();
                let wrapper = wrap_node(scope, state, body).unwrap();
                let wrapper = v8::Global::new(scope, wrapper);
                scope
                    .get_slot::<BindingStateRegistry>()
                    .unwrap()
                    .pending_slots
                    .borrow_mut()
                    .push((state.instance_id, body, wrapper));
            }
            queue_mutation_observer_microtask(scope);
            scope.perform_microtask_checkpoint();
            let source = v8::String::new(scope, "log.join() === 'B,BS'").unwrap();
            assert!(
                v8::Script::compile(scope, source, None)
                    .unwrap()
                    .run(scope)
                    .unwrap()
                    .is_true()
            );
            for _ in 0..3 {
                queue_mutation_observer_microtask(scope);
                assert!(
                    !has_pending_mutation_observer_microtask(scope),
                    "parked-only work must not keep the agent spinning"
                );
                scope.perform_microtask_checkpoint();
            }
            {
                let registry = scope.get_slot::<BindingStateRegistry>().unwrap();
                assert_eq!(registry.pending_observers.borrow().len(), 1);
                assert_eq!(registry.pending_slots.borrow().len(), 1);
            }
            if discard {
                states[0].retire_execution();
            } else {
                states[0].set_execution_suspended(false);
            }
            queue_mutation_observer_microtask(scope);
            scope.perform_microtask_checkpoint();
            let expected = if discard { "B,BS" } else { "B,BS,A,AS" };
            let source = v8::String::new(scope, &format!("log.join() === '{expected}'")).unwrap();
            assert!(
                v8::Script::compile(scope, source, None)
                    .unwrap()
                    .run(scope)
                    .unwrap()
                    .is_true()
            );
            let registry = scope.get_slot::<BindingStateRegistry>().unwrap();
            assert!(registry.pending_observers.borrow().is_empty());
            assert!(registry.pending_slots.borrow().is_empty());
        }
    }

    #[test]
    fn interrupted_observer_batches_restore_order_and_reentrant_membership() {
        let registry = BindingStateRegistry::default();
        registry
            .pending_observers
            .borrow_mut()
            .extend([(1, 1), (2, 2), (3, 3)]);
        registry
            .pending_observer_set
            .borrow_mut()
            .extend([(1, 1), (2, 2), (3, 3)]);
        {
            let mut batch = ObserverNotificationBatch::take(&registry);
            assert!(registry.pending_observer_set.borrow().is_empty());
            assert_eq!(batch.remaining.pop_front(), Some((1, 1)));
            registry
                .pending_observers
                .borrow_mut()
                .extend([(4, 4), (2, 2), (1, 1)]);
            registry
                .pending_observer_set
                .borrow_mut()
                .extend([(4, 4), (2, 2), (1, 1)]);
        }
        assert_eq!(
            *registry.pending_observers.borrow(),
            vec![(2, 2), (3, 3), (4, 4), (1, 1)]
        );
        assert_eq!(
            *registry.pending_observer_set.borrow(),
            BTreeSet::from([(1, 1), (2, 2), (3, 3), (4, 4)])
        );
        {
            let mut batch = ObserverNotificationBatch::take(&registry);
            batch.remaining.clear();
        }
        assert!(registry.pending_observers.borrow().is_empty());
        assert!(registry.pending_observer_set.borrow().is_empty());
    }

    #[test]
    fn observer_checkpoint_failure_and_termination_keep_later_observers_and_slots() {
        initialize_v8();
        fn terminate(
            scope: &mut v8::PinScope,
            _args: v8::FunctionCallbackArguments,
            _rv: v8::ReturnValue,
        ) {
            scope.terminate_execution();
        }
        for failure in ["prepare", "terminate"] {
            let mut isolate = v8::Isolate::new(Default::default());
            isolate.set_microtasks_policy(v8::MicrotasksPolicy::Explicit);
            v8::scope!(let scope,&mut isolate);
            let local = v8::Context::new(scope, Default::default());
            let foreign = v8::Context::new(scope, Default::default());
            let a = {
                let scope = &mut v8::ContextScope::new(scope, local);
                install_generated_bindings(
                    scope,
                    local,
                    Rc::new(RefCell::new(
                        html::parse("<body></body>").into_runtime().unwrap(),
                    )),
                    RealmId(137),
                    1,
                )
                .unwrap()
            };
            let b = {
                let scope = &mut v8::ContextScope::new(scope, foreign);
                install_generated_bindings(
                    scope,
                    foreign,
                    Rc::new(RefCell::new(
                        html::parse("<body></body>").into_runtime().unwrap(),
                    )),
                    RealmId(138),
                    1,
                )
                .unwrap()
            };
            let log = {
                let scope = &mut v8::ContextScope::new(scope, local);
                let log = v8::Array::new(scope, 0);
                v8::Global::new(scope, log)
            };
            let log = v8::Local::new(scope, &log);
            for (context, script) in [
                (
                    local,
                    "var first=new MutationObserver(()=>{log.push('A');if(stopFirst)stopNow()});var last=new MutationObserver(()=>log.push('C'));first.observe(document.body,{attributes:true});last.observe(document.body,{attributes:true});document.body.addEventListener('slotchange',()=>log.push('S'));document.body.id='changed'",
                ),
                (
                    foreign,
                    "var middle=new MutationObserver(()=>log.push('B'));middle.observe(document.body,{attributes:true});document.body.id='changed'",
                ),
            ] {
                let scope = &mut v8::ContextScope::new(scope, context);
                let global = context.global(scope);
                let key = v8::String::new(scope, "log").unwrap();
                global.set(scope, key.into(), log.into()).unwrap();
                let key = v8::String::new(scope, "stopFirst").unwrap();
                let stop = v8::Boolean::new(scope, failure == "terminate");
                global.set(scope, key.into(), stop.into()).unwrap();
                let key = v8::String::new(scope, "stopNow").unwrap();
                let callback = v8::Function::new(scope, terminate).unwrap();
                global.set(scope, key.into(), callback.into()).unwrap();
                let source = v8::String::new(scope, script).unwrap();
                v8::Script::compile(scope, source, None)
                    .unwrap()
                    .run(scope)
                    .unwrap();
            }
            let scope = &mut v8::ContextScope::new(scope, local);
            let ids = a
                .mutation_observers
                .borrow()
                .keys()
                .copied()
                .collect::<Vec<_>>();
            let middle = *b.mutation_observers.borrow().keys().next().unwrap();
            let body = a
                .dom
                .borrow()
                .query_selector(a.document_root(), "body")
                .unwrap()
                .unwrap();
            let wrapper = wrap_node(scope, &a, body).unwrap();
            let wrapper = v8::Global::new(scope, wrapper);
            {
                let registry = scope.get_slot::<BindingStateRegistry>().unwrap();
                *registry.pending_observers.borrow_mut() = vec![
                    (a.instance_id, ids[0]),
                    (b.instance_id, middle),
                    (a.instance_id, ids[1]),
                ];
                *registry.pending_observer_set.borrow_mut() = registry
                    .pending_observers
                    .borrow()
                    .iter()
                    .copied()
                    .collect();
                registry
                    .pending_slots
                    .borrow_mut()
                    .push((a.instance_id, body, wrapper));
            }
            let template = if failure == "prepare" {
                b.instance_templates.borrow_mut().remove("MutationRecord")
            } else {
                None
            };
            let result = deliver_pending_mutation_notifications(scope);
            if failure == "prepare" {
                assert!(result.is_err());
            } else {
                assert!(result.is_ok());
                assert!(scope.is_execution_terminating());
                scope.cancel_terminate_execution();
                reset_mutation_observer_microtask_after_termination(scope);
            }
            if let Some(template) = template {
                b.instance_templates
                    .borrow_mut()
                    .insert("MutationRecord", template);
            }
            {
                let registry = scope.get_slot::<BindingStateRegistry>().unwrap();
                assert_eq!(
                    *registry.pending_observers.borrow(),
                    vec![(b.instance_id, middle), (a.instance_id, ids[1])]
                );
                assert_eq!(registry.pending_slots.borrow().len(), 1);
            }
            deliver_pending_mutation_notifications(scope).unwrap();
            let source = v8::String::new(scope, "log.join(',')==='A,B,C,S'").unwrap();
            assert!(
                v8::Script::compile(scope, source, None)
                    .unwrap()
                    .run(scope)
                    .unwrap()
                    .is_true(),
                "{failure}"
            );
            let registry = scope.get_slot::<BindingStateRegistry>().unwrap();
            assert!(registry.pending_observers.borrow().is_empty());
            assert!(registry.pending_slots.borrow().is_empty());
        }
    }

    #[test]
    fn pending_slot_wrapper_follows_adoption_before_and_during_checkpoint() {
        initialize_v8();
        let mut isolate = v8::Isolate::new(Default::default());
        isolate.set_microtasks_policy(v8::MicrotasksPolicy::Explicit);
        v8::scope!(let scope,&mut isolate);
        let local = v8::Context::new(scope, Default::default());
        let foreign = v8::Context::new(scope, Default::default());
        let a = {
            let scope = &mut v8::ContextScope::new(scope, local);
            install_generated_bindings(
                scope,
                local,
                Rc::new(RefCell::new(
                    html::parse("<slot id=s></slot>").into_runtime().unwrap(),
                )),
                RealmId(140),
                1,
            )
            .unwrap()
        };
        let b = {
            let scope = &mut v8::ContextScope::new(scope, foreign);
            install_generated_bindings(
                scope,
                foreign,
                Rc::new(RefCell::new(
                    html::parse("<body></body>").into_runtime().unwrap(),
                )),
                RealmId(141),
                1,
            )
            .unwrap()
        };
        let scope = &mut v8::ContextScope::new(scope, local);
        let node = a.dom.borrow().find_by_id("s").unwrap();
        let wrapper = wrap_node(scope, &a, node).unwrap();
        let wrapper = v8::Global::new(scope, wrapper);
        let foreign_document = wrap_node(scope, &b, b.document_root()).unwrap();
        let key = v8::String::new(scope, "foreignDocument").unwrap();
        local
            .global(scope)
            .set(scope, key.into(), foreign_document.into())
            .unwrap();
        let source=v8::String::new(scope,"var slot=document.getElementById('s'),hits=0;slot.addEventListener('slotchange',()=>hits++);foreignDocument.adoptNode(slot)").unwrap();
        scope
            .get_slot::<BindingStateRegistry>()
            .unwrap()
            .pending_slots
            .borrow_mut()
            .push((a.instance_id, node, wrapper.clone()));
        v8::Script::compile(scope, source, None)
            .unwrap()
            .run(scope)
            .unwrap();
        collect_slot_notifications(scope).unwrap();
        assert_eq!(
            scope
                .get_slot::<BindingStateRegistry>()
                .unwrap()
                .pending_slots
                .borrow()[0]
                .0,
            b.instance_id
        );
        deliver_pending_mutation_notifications(scope).unwrap();
        let source=v8::String::new(scope,"var observer=new MutationObserver(()=>document.adoptNode(slot));observer.observe(document.body,{attributes:true});document.body.id='changed'").unwrap();
        v8::Script::compile(scope, source, None)
            .unwrap()
            .run(scope)
            .unwrap();
        let object = v8::Local::new(scope, &wrapper);
        let (_, foreign_node) = node_identity::argument(scope, object.into())
            .unwrap()
            .unwrap();
        {
            let registry = scope.get_slot::<BindingStateRegistry>().unwrap();
            let id = *a.mutation_observers.borrow().keys().next().unwrap();
            *registry.pending_observers.borrow_mut() = vec![(a.instance_id, id)];
            *registry.pending_observer_set.borrow_mut() = BTreeSet::from([(a.instance_id, id)]);
            registry
                .pending_slots
                .borrow_mut()
                .push((b.instance_id, foreign_node, wrapper));
        }
        deliver_pending_mutation_notifications(scope).unwrap();
        let source = v8::String::new(scope, "hits===2&&slot.ownerDocument===document").unwrap();
        assert!(
            v8::Script::compile(scope, source, None)
                .unwrap()
                .run(scope)
                .unwrap()
                .is_true()
        );
    }

    #[test]
    fn slot_checkpoint_retries_preparation_but_never_replays_started_dispatch() {
        initialize_v8();
        let mut isolate = v8::Isolate::new(Default::default());
        isolate.set_microtasks_policy(v8::MicrotasksPolicy::Explicit);
        v8::scope!(let scope,&mut isolate);
        let context = v8::Context::new(scope, Default::default());
        let scope = &mut v8::ContextScope::new(scope, context);
        let dom = Rc::new(RefCell::new(
            html::parse("<div id=a></div><div id=b></div>")
                .into_runtime()
                .unwrap(),
        ));
        let a = dom.borrow().find_by_id("a").unwrap();
        let b = dom.borrow().find_by_id("b").unwrap();
        let state = install_generated_bindings(scope, context, dom, RealmId(139), 1).unwrap();
        fn terminate(
            scope: &mut v8::PinScope,
            _args: v8::FunctionCallbackArguments,
            _rv: v8::ReturnValue,
        ) {
            scope.terminate_execution();
        }
        let callback = v8::Function::new(scope, terminate).unwrap();
        let key = v8::String::new(scope, "stopNow").unwrap();
        context
            .global(scope)
            .set(scope, key.into(), callback.into())
            .unwrap();
        let source=v8::String::new(scope,"var log=[];document.getElementById('a').addEventListener('slotchange',()=>{log.push('A');stopNow()});document.getElementById('b').addEventListener('slotchange',()=>log.push('B'))").unwrap();
        test_eval::run(scope, source);
        let queue = Rc::clone(
            &scope
                .get_slot::<BindingStateRegistry>()
                .unwrap()
                .pending_slots,
        );
        for node in [a, b] {
            let wrapper = wrap_node(scope, &state, node).unwrap();
            queue
                .borrow_mut()
                .push((state.instance_id, node, v8::Global::new(scope, wrapper)));
        }
        let template = state
            .instance_templates
            .borrow_mut()
            .remove("Event")
            .unwrap();
        assert!(deliver_pending_mutation_notifications(scope).is_err());
        assert_eq!(
            queue.borrow().iter().map(|v| v.1).collect::<Vec<_>>(),
            vec![a, b]
        );
        state
            .instance_templates
            .borrow_mut()
            .insert("Event", template);
        let resumed = deliver_pending_mutation_notifications(scope);
        assert!(
            scope.is_execution_terminating(),
            "resumed={resumed:?}; queued={:?}",
            queue.borrow().iter().map(|v| v.1).collect::<Vec<_>>()
        );
        scope.cancel_terminate_execution();
        reset_mutation_observer_microtask_after_termination(scope);
        assert_eq!(
            queue.borrow().iter().map(|v| v.1).collect::<Vec<_>>(),
            vec![b]
        );
        deliver_pending_mutation_notifications(scope).unwrap();
        assert!(queue.borrow().is_empty());
        let source = v8::String::new(scope, "log.join(',')==='A,B'").unwrap();
        assert!(test_eval::run(scope, source).is_true());
    }

    #[test]
    fn interrupted_slot_batches_restore_only_undispatched_targets_in_order() {
        initialize_v8();
        let dom = Rc::new(RefCell::new(
            html::parse("<div id=a></div><div id=b></div><div id=c></div>")
                .into_runtime()
                .unwrap(),
        ));
        let a = dom.borrow().find_by_id("a").unwrap();
        let b = dom.borrow().find_by_id("b").unwrap();
        let c = dom.borrow().find_by_id("c").unwrap();
        let mut isolate = v8::Isolate::new(Default::default());
        v8::scope!(let scope, &mut isolate);
        let context = v8::Context::new(scope, Default::default());
        let scope = &mut v8::ContextScope::new(scope, context);
        let state = install_generated_bindings(scope, context, dom, RealmId(0), 1).unwrap();
        let queue = Rc::clone(
            &scope
                .get_slot::<BindingStateRegistry>()
                .unwrap()
                .pending_slots,
        );
        for node in [a, b] {
            let wrapper = wrap_node(scope, &state, node).unwrap();
            queue
                .borrow_mut()
                .push((state.instance_id, node, v8::Global::new(scope, wrapper)));
        }
        {
            let mut batch = SlotNotificationBatch::take(&queue);
            assert_eq!(batch.remaining.pop_front().unwrap().1, a);
            for node in [c, b] {
                let wrapper = wrap_node(scope, &state, node).unwrap();
                queue
                    .borrow_mut()
                    .push((state.instance_id, node, v8::Global::new(scope, wrapper)));
            }
            // Leaving scope models a terminated observer/checkpoint callback.
        }
        assert_eq!(
            queue
                .borrow()
                .iter()
                .map(|entry| entry.1)
                .collect::<Vec<_>>(),
            vec![b, c]
        );
        {
            let mut batch = SlotNotificationBatch::take(&queue);
            while batch.remaining.pop_front().is_some() {}
        }
        assert!(queue.borrow().is_empty());
        let wrapper = wrap_node(scope, &state, b).unwrap();
        queue
            .borrow_mut()
            .push((state.instance_id, b, v8::Global::new(scope, wrapper)));
        state.retire_execution();
        collect_slot_notifications(scope).unwrap();
        assert!(
            queue.borrow().is_empty(),
            "retired document notification retained"
        );
    }

