    #[test]
    fn tee_cancellation_preserves_source_rejection_and_terminal_state() {
        initialize_v8();
        let dom = Rc::new(RefCell::new(
            html::parse("<main></main>").into_runtime().unwrap(),
        ));
        let mut isolate = v8::Isolate::new(Default::default());
        v8::scope!(let scope, &mut isolate);
        let context = v8::Context::new(scope, Default::default());
        let scope = &mut v8::ContextScope::new(scope, context);
        let _state = install_generated_bindings(scope, context, dom, RealmId(0), 1).unwrap();
        let source = v8::String::new(scope, r#"
            let result='pending';
            (async()=>{
                const check=(value,message)=>{if(!value)throw Error(message)};
                const rejection={cancel:'rejected'};
                let calls=0;
                const [left,right]=new ReadableStream({cancel(){calls++;return Promise.reject(rejection)}}).tee();
                const first=left.cancel(1).then(()=>null,error=>error);
                const second=right.cancel(2).then(()=>null,error=>error);
                check(await first===rejection && await second===rejection,'cancellation rejection identity');
                check(calls===1,'single source cancellation');
                let closedCancels=0;
                const [a,b]=new ReadableStream({start(c){c.enqueue('queued');c.close()},cancel(){closedCancels++}}).tee();
                await Promise.all([a.cancel(),b.cancel()]);
                check(closedCancels===0,'closed source does not invoke cancel');
                const error={source:'failed'};
                let controller;
                const [c,d]=new ReadableStream({start(value){controller=value}}).tee();
                const cancelled=c.cancel();controller.error(error);
                await cancelled;
                let caught;try{await d.getReader().read()}catch(reason){caught=reason}
                check(caught===error,'remaining branch source error');
                result='ok';
            })().catch(error=>result=String(error));
        "#).unwrap();
        v8::Script::compile(scope, source, None)
            .unwrap()
            .run(scope)
            .unwrap();
        for _ in 0..32 {
            scope.perform_microtask_checkpoint();
        }
        let source = v8::String::new(scope, "result").unwrap();
        assert_eq!(
            v8::Script::compile(scope, source, None)
                .unwrap()
                .run(scope)
                .unwrap()
                .to_rust_string_lossy(scope),
            "ok"
        );
    }

    #[test]
    fn native_tee_clones_streaming_bodies_and_combines_cancellation() {
        initialize_v8();
        let dom = Rc::new(RefCell::new(
            html::parse("<main></main>").into_runtime().unwrap(),
        ));
        let mut isolate = v8::Isolate::new(Default::default());
        v8::scope!(let scope, &mut isolate);
        let context = v8::Context::new(scope, Default::default());
        let scope = &mut v8::ContextScope::new(scope, context);
        let state = install_generated_bindings(scope, context, dom, RealmId(0), 1).unwrap();
        state.commit_location("https://example.test/app").unwrap();
        state.set_platform_host(Rc::new(TestPlatformHost::default()));
        let source = v8::String::new(scope, r#"
            let result='pending';
            (async()=>{
                const check=(value,message)=>{if(!value)throw Error(message)};
                let controller;
                const response=new Response(new ReadableStream({start(c){controller=c}}));
                const clone=response.clone(), nested=clone.clone();
                check(!response.bodyUsed && !clone.bodyUsed,'cloning does not consume branches');
                const first=response.text();
                controller.enqueue(new Uint8Array([65]));
                controller.enqueue(new Uint8Array([66]));controller.close();
                check(await first==='AB','first stream');
                check(await clone.text()==='AB' && await nested.text()==='AB','delayed nested clones');
                const copied=new Response(new Uint8Array([7]));
                const twin=copied.clone();
                const left=await copied.body.getReader().read();left.value[0]=99;
                check((await twin.body.getReader().read()).value[0]===7,'byte isolation');
                let cancelReasons, finish;
                const [a,b]=new ReadableStream({cancel(reasons){cancelReasons=reasons;return new Promise(resolve=>finish=resolve)}}).tee();
                let settled=false;
                const cancellation=a.cancel('left').then(()=>settled=true);
                await Promise.resolve();check(!settled && !cancelReasons,'single branch cancellation');
                const other=b.cancel('right');
                check(cancelReasons[0]==='left' && cancelReasons[1]==='right','combined reasons');
                await Promise.resolve();check(!settled,'wait for source cancellation');
                finish();await cancellation;await other;
                
                const fetched=await fetch('/bytes');const fetchedClone=fetched.clone();
                check(await fetched.text()==='native' && await fetchedClone.text()==='native','host body clone');
                result='ok';
            })().catch(error=>result=String(error));
        "#).unwrap();
        v8::Script::compile(scope, source, None)
            .unwrap()
            .run(scope)
            .unwrap();
        for _ in 0..32 {
            state.drain_platform_completions(scope, 8).unwrap();
            scope.perform_microtask_checkpoint();
        }
        let source = v8::String::new(scope, "result").unwrap();
        assert_eq!(
            v8::Script::compile(scope, source, None)
                .unwrap()
                .run(scope)
                .unwrap()
                .to_rust_string_lossy(scope),
            "ok"
        );
    }

