    #[test]
    fn native_document_base_tracks_inheritance_and_ignores_author_shadows() {
        initialize_v8();
        let dom = Rc::new(RefCell::new(
            html::parse("<head><base href='../assets/'></head><body></body>")
                .into_runtime()
                .unwrap(),
        ));
        let mut isolate = v8::Isolate::new(Default::default());
        v8::scope!(let scope, &mut isolate);
        let context = v8::Context::new(scope, Default::default());
        let scope = &mut v8::ContextScope::new(scope, context);
        let state = install_generated_bindings(scope, context, dom, RealmId(0), 1).unwrap();
        state.commit_location("about:srcdoc").unwrap();
        state.set_inherited_base_url(Some("https://example.test/parent/page".into()));
        assert_eq!(
            state.native_document_base_url(true).unwrap(),
            "https://example.test/assets/"
        );
        assert_eq!(
            state.native_document_base_url(false).unwrap(),
            "https://example.test/parent/page"
        );
        for href in ["about:blank#next", "about:srcdoc#next"] {
            state.commit_location(href).unwrap();
            assert_eq!(state.request_initiator_url().unwrap(), href);
            assert_eq!(
                state.native_document_base_url(false).unwrap(),
                "https://example.test/parent/page"
            );
            assert_eq!(
                state.native_document_base_url(true).unwrap(),
                "https://example.test/assets/"
            );
            assert_eq!(
                retained_document_base_url(&state, state.document_root()).unwrap(),
                "https://example.test/assets/"
            );
            assert_eq!(
                state
                    .native_document_resource_url("image.png")
                    .unwrap()
                    .as_str(),
                "https://example.test/assets/image.png"
            );
        }
        let source = v8::String::new(
            scope,
            r#"
            Object.defineProperty(document,'baseURI',{get(){throw Error('author base getter')}});
            document.querySelector('base').setAttribute('href','data:text/html,wrong');
        "#,
        )
        .unwrap();
        v8::Script::compile(scope, source, None)
            .unwrap()
            .run(scope)
            .unwrap();
        assert_eq!(
            state.native_document_base_url(true).unwrap(),
            "https://example.test/parent/page"
        );
        state.commit_location("https://next.test/final").unwrap();
        assert_eq!(
            state.native_document_base_url(true).unwrap(),
            "https://next.test/final"
        );
        assert_eq!(
            state.request_initiator_url().unwrap(),
            "https://next.test/final"
        );
    }

