    #[test]
    fn request_and_response_extract_byte_bodies_with_content_types() {
        initialize_v8();
        let dom = Rc::new(RefCell::new(
            html::parse("<main></main>").into_runtime().unwrap(),
        ));
        let mut isolate = v8::Isolate::new(Default::default());
        v8::scope!(let scope, &mut isolate);
        let context = v8::Context::new(scope, Default::default());
        let scope = &mut v8::ContextScope::new(scope, context);
        let state = install_generated_bindings(scope, context, dom, RealmId(0), 1).unwrap();
        state.commit_location("https://example.test/app").unwrap();
        let source = v8::String::new(scope, r#"
            let result='pending';
            (async()=>{
                const check=(value,message)=>{if(!value)throw Error(message)};
                
                const params=new URLSearchParams([['a','hello world'],['a','é']]);
                params.toString=()=>{throw Error('public stringifier')};
                for(const make of [body=>new Response(body),body=>new Request('/data',{method:'POST',body})]){
                    const text=make('text');check(text.headers.get('content-type')==='text/plain;charset=UTF-8','text type');
                    check(await text.text()==='text','text bytes');
                    const encoded=make(params);check(encoded.headers.get('content-type')==='application/x-www-form-urlencoded;charset=UTF-8','params type');
                    check(await encoded.text()==='a=hello+world&a=%C3%A9','native params encoding');
                    const blob=make(new Blob(['blob'],{type:'application/example'}));
                    check(blob.headers.get('content-type')==='application/example' && await blob.text()==='blob','blob type and bytes');
                    const backing=new Uint8Array([1,2,3,4]);const view=make(backing.subarray(1,3));backing.fill(9);
                    check(view.headers.get('content-type')===null,'buffer has no inferred type');
                    check(Array.from(new Uint8Array(await view.arrayBuffer())).join(',')==='2,3','view range snapshot');
                }
                const explicit=new Response('text',{headers:{'content-type':'custom/type'}});
                check(explicit.headers.get('content-type')==='custom/type','explicit type wins');
                const reason={conversion:true};let caught;
                try{new Response({toString(){throw reason}})}catch(error){caught=error}
                check(caught===reason,'body conversion exception');
                result='ok';
            })().catch(error=>result=String(error));
        "#).unwrap();
        v8::Script::compile(scope, source, None)
            .unwrap()
            .run(scope)
            .unwrap();
        for _ in 0..32 {
            scope.perform_microtask_checkpoint();
        }
        let source = v8::String::new(scope, "result").unwrap();
        assert_eq!(
            v8::Script::compile(scope, source, None)
                .unwrap()
                .run(scope)
                .unwrap()
                .to_rust_string_lossy(scope),
            "ok"
        );
    }

    #[test]
    fn request_byte_bodies_distinguish_absent_empty_transfer_and_clone() {
        initialize_v8();
        let dom = Rc::new(RefCell::new(
            html::parse("<main></main>").into_runtime().unwrap(),
        ));
        let mut isolate = v8::Isolate::new(Default::default());
        v8::scope!(let scope, &mut isolate);
        let context = v8::Context::new(scope, Default::default());
        let scope = &mut v8::ContextScope::new(scope, context);
        let state = install_generated_bindings(scope, context, dom, RealmId(0), 1).unwrap();
        state.commit_location("https://example.test/app").unwrap();
        let source = v8::String::new(scope, r#"
            let result='pending';
            (async()=>{
                const check=(value,message)=>{if(!value)throw Error(message)};
                const fail=fn=>{let caught;try{fn()}catch(error){caught=error}check(caught instanceof TypeError,'expected TypeError')};
                
                for(const method of ['GET','HEAD'])for(const body of ['',new Uint8Array(0),new Blob([])])fail(()=>new Request('/data',{method,body}));
                const absent=new Request('/data');check(absent.body===null,'absent body');
                check(await absent.text()==='' && await absent.text()==='' && !absent.bodyUsed,'absent reusable');
                const empty=new Request('/data',{method:'POST',body:''});
                check(empty.body instanceof ReadableStream && !empty.bodyUsed,'empty body stream');
                check(await empty.text()==='' && empty.bodyUsed,'empty consumed');
                fail(()=>new Request(empty));fail(()=>empty.clone());
                const original=new Request('/data',{method:'POST',body:'payload'});
                const cloned=original.clone();
                check(!original.bodyUsed && !cloned.bodyUsed,'clone not consumed');
                check(await original.text()==='payload' && await cloned.text()==='payload','clone payloads');
                const source=new Request('/data',{method:'POST',body:'transfer'});
                const derived=new Request(source);
                check(source.bodyUsed && !derived.bodyUsed,'transfer body state');
                check(await derived.text()==='transfer','transferred bytes');
                const locked=new Request('/data',{method:'POST',body:'locked'});const reader=locked.body.getReader();
                fail(()=>new Request(locked));fail(()=>locked.clone());reader.releaseLock();
                check(await locked.text()==='locked','release restores usable body');
                result='ok';
            })().catch(error=>result=String(error));
        "#).unwrap();
        v8::Script::compile(scope, source, None)
            .unwrap()
            .run(scope)
            .unwrap();
        for _ in 0..32 {
            scope.perform_microtask_checkpoint();
        }
        let source = v8::String::new(scope, "result").unwrap();
        assert_eq!(
            v8::Script::compile(scope, source, None)
                .unwrap()
                .run(scope)
                .unwrap()
                .to_rust_string_lossy(scope),
            "ok"
        );
    }

