    #[test]
    fn headers_init_consumes_iterables_and_closes_on_conversion_errors() {
        initialize_v8();
        let dom = Rc::new(RefCell::new(
            html::parse("<main></main>").into_runtime().unwrap(),
        ));
        let mut isolate = v8::Isolate::new(Default::default());
        v8::scope!(let scope, &mut isolate);
        let context = v8::Context::new(scope, Default::default());
        let scope = &mut v8::ContextScope::new(scope, context);
        let _state = install_generated_bindings(scope, context, dom, RealmId(0), 1).unwrap();
        let source = v8::String::new(scope, r#"
            const check=(value,message)=>{if(!value)throw Error(message)};
            function* pair(){yield 'X-Test';yield 'value'}
            function* entries(){yield pair();yield new Set(['other','yes'])}
            const headers=new Headers(entries());
            check(headers.get('x-test')==='value' && headers.get('other')==='yes','nested iterables');
            headers[Symbol.iterator]=function*(){yield ['replacement','honored']};
            const copied=new Headers(headers);
            check(copied.get('replacement')==='honored' && !copied.has('x-test'),'custom native iterator');
            const reason={conversion:true}, closeReason={close:true};let order=[];
            function* badPair(){try{yield {toString(){throw reason}}}finally{order.push('inner');throw closeReason}}
            function* badEntries(){try{yield badPair()}finally{order.push('outer')}}
            let caught;try{new Headers(badEntries())}catch(error){caught=error}
            check(caught===reason && order.join(',')==='inner,outer','close preserves original exception');
            order=[];
            function* invalidNames(){yield ['bad name','value'];order.push('continued');yield ['fine','yes']}
            try{new Headers(invalidNames())}catch(error){caught=error}
            check(caught instanceof TypeError && order.join(',')==='continued','convert entire sequence before validation');
            const record=Object.create({inherited:'no'});record.visible='yes';
            Object.defineProperty(record,'hidden',{get(){throw Error('hidden getter')}});
            check(new Headers(record).get('visible')==='yes','enumerable own record');
            for(const value of [null,1,'text',{[Symbol.iterator]:4}]){
                caught=null;try{new Headers(value)}catch(error){caught=error}
                check(caught instanceof TypeError,'invalid union input');
            }
            'ok';
        "#).unwrap();
        assert_eq!(
            v8::Script::compile(scope, source, None)
                .unwrap()
                .run(scope)
                .unwrap()
                .to_rust_string_lossy(scope),
            "ok"
        );
    }

    #[test]
    fn headers_validate_bytes_without_borrowing_across_author_conversion() {
        initialize_v8();
        let dom = Rc::new(RefCell::new(
            html::parse("<main></main>").into_runtime().unwrap(),
        ));
        let mut isolate = v8::Isolate::new(Default::default());
        v8::scope!(let scope, &mut isolate);
        let context = v8::Context::new(scope, Default::default());
        let scope = &mut v8::ContextScope::new(scope, context);
        let _state = install_generated_bindings(scope, context, dom, RealmId(0), 1).unwrap();
        let source = v8::String::new(scope, r#"
            const check=(value,message)=>{if(!value)throw Error(message)};
            const fail=fn=>{let caught;try{fn()}catch(error){caught=error}check(caught instanceof TypeError,'expected TypeError')};
            const headers=new Headers();
            for(const name of [' x','x ','x:y',''])fail(()=>headers.set(name,'value'));
            for(const value of ['\0','a\rb','a\nb','\u0100','\ud800'])fail(()=>headers.set('x',value));
            headers.set('x','\r\n\t value \t\r\n');check(headers.get('x')==='value','HTTP edge whitespace');
            headers.set('x','\u00a0value\u00a0');check(headers.get('x')==='\u00a0value\u00a0','preserve non-HTTP whitespace');
            const order=[];
            headers.set({toString(){order.push('name');headers.set('inner','one');return 'x'}},
                {toString(){order.push('value');headers.append('inner','two');return 'outer'}});
            check(order.join(',')==='name,value' && headers.get('inner')==='one, two' && headers.get('x')==='outer','reentrant conversions');
            let converted=false;fail(()=>headers.set('bad name',{toString(){converted=true;return 'v'}}));
            check(converted,'convert arguments before name validation');
            fail(()=>headers.append('x'));fail(()=>new Headers([['a']]));fail(()=>new Headers([['a','b','c']]));
            const reason={conversion:true};let caught;
            try{headers.set('x',{toString(){throw reason}})}catch(error){caught=error}
            check(caught===reason && headers.get('x')==='outer','exception preserves list');
            try{new Headers({get x(){throw reason}})}catch(error){caught=error}
            check(caught===reason,'record getter propagates');
            'ok';
        "#).unwrap();
        assert_eq!(
            v8::Script::compile(scope, source, None)
                .unwrap()
                .run(scope)
                .unwrap()
                .to_rust_string_lossy(scope),
            "ok"
        );
    }

    #[test]
    fn xhr_upload_completion_requires_measured_consumption_and_preserves_reentrancy() {
        initialize_v8();
        for (upload, reopen, expected) in [
            (None, false, ""),
            (
                Some(crate::platform::PlatformUploadProgress {
                    bytes_consumed: 2,
                    total_bytes: 4,
                    body_complete: false,
                }),
                false,
                "progress:2:4",
            ),
            (
                Some(crate::platform::PlatformUploadProgress {
                    bytes_consumed: 4,
                    total_bytes: 4,
                    body_complete: true,
                }),
                false,
                "progress:4:4,load:4:4,loadend:4:4",
            ),
            (
                Some(crate::platform::PlatformUploadProgress {
                    bytes_consumed: 4,
                    total_bytes: 4,
                    body_complete: true,
                }),
                true,
                "progress:4:4",
            ),
        ] {
            let dom = Rc::new(RefCell::new(
                html::parse("<main></main>").into_runtime().unwrap(),
            ));
            let mut isolate = v8::Isolate::new(Default::default());
            v8::scope!(let scope, &mut isolate);
            let context = v8::Context::new(scope, Default::default());
            let scope = &mut v8::ContextScope::new(scope, context);
            let state = install_generated_bindings(scope, context, dom, RealmId(0), 1).unwrap();
            state.commit_location("https://example.test/page").unwrap();
            let host = Rc::new(TestPlatformHost {
                upload,
                ..Default::default()
            });
            state.set_platform_host(host.clone());
            let source = format!(
                r#"
                const xhr=new XMLHttpRequest();const uploads=[];const states=[];
                xhr.open('POST','/upload');
                for(const kind of ['progress','load','loadend']) xhr.upload.addEventListener(kind,event=>{{
                    if(!(event instanceof ProgressEvent) || !event.isTrusted || !event.lengthComputable) throw Error('event metadata');
                    uploads.push(kind+':'+event.loaded+':'+event.total);
                    if({reopen} && kind==='progress') xhr.open('GET','/replacement');
                }});
                xhr.onreadystatechange=()=>states.push(xhr.readyState);
                xhr.send('body');
            "#
            );
            let source = v8::String::new(scope, &source).unwrap();
            test_eval::run(scope, source);
            state.drain_platform_completions(scope, 1).unwrap();
            let source = v8::String::new(scope, "uploads.join(',')").unwrap();
            assert_eq!(
                test_eval::run(scope, source).to_rust_string_lossy(scope),
                expected
            );
            if reopen {
                let source =
                    v8::String::new(scope, "xhr.readyState===1 && !states.includes(2)").unwrap();
                assert!(test_eval::run(scope, source).boolean_value(scope));
                assert!(host.aborted_streams.lock().unwrap().contains(&7));
            }
        }
    }

    #[test]
    fn xhr_upload_start_abort_events_are_owned_by_the_active_request() {
        initialize_v8();
        let dom = Rc::new(RefCell::new(
            html::parse("<main></main>").into_runtime().unwrap(),
        ));
        let mut isolate = v8::Isolate::new(Default::default());
        v8::scope!(let scope, &mut isolate);
        let context = v8::Context::new(scope, Default::default());
        let scope = &mut v8::ContextScope::new(scope, context);
        let state = install_generated_bindings(scope, context, dom, RealmId(0), 1).unwrap();
        state.commit_location("https://example.test/page").unwrap();
        let host = Rc::new(TestPlatformHost::default());
        state.set_platform_host(host.clone());
        let source = v8::String::new(scope, r#"
            const check=(value,message)=>{if(!value)throw Error(message)};
            const xhr=new XMLHttpRequest();xhr.open('POST','/upload');const events=[];
            xhr.onloadstart=()=>events.push('request start');
            xhr.upload.onloadstart=event=>{
                check(event instanceof ProgressEvent && event.isTrusted && event.lengthComputable && event.loaded===0 && event.total===4,'upload start');
                events.push('upload start');xhr.abort();
            };
            xhr.upload.onabort=event=>{check(event.loaded===0 && event.total===0,'abort counts');events.push('upload abort')};
            xhr.upload.onloadend=()=>events.push('upload end');
            xhr.onabort=()=>events.push('request abort');xhr.onloadend=()=>events.push('request end');
            xhr.send('body');
            check(events.join(',')==='request start,upload start,upload abort,upload end,request abort,request end','abort event order');
            check(xhr.readyState===0,'aborted request');
            const reopened=new XMLHttpRequest();reopened.open('POST','/old');let stale=0;
            reopened.upload.onloadstart=()=>reopened.abort();
            reopened.upload.onabort=()=>reopened.open('GET','/new');
            reopened.upload.onloadend=()=>stale++;reopened.onabort=()=>stale++;
            reopened.send('body');check(reopened.readyState===1 && stale===0,'upload callback replacement');
            'ok';
        "#).unwrap();
        assert_eq!(
            test_eval::run(scope, source).to_rust_string_lossy(scope),
            "ok"
        );
        assert!(host.requests.lock().unwrap().is_empty());
    }

