    #[test]
    fn xhr_upload_target_has_stable_identity_and_independent_listeners() {
        initialize_v8();
        let dom = Rc::new(RefCell::new(
            html::parse("<main></main>").into_runtime().unwrap(),
        ));
        let mut isolate = v8::Isolate::new(Default::default());
        v8::scope!(let scope, &mut isolate);
        let context = v8::Context::new(scope, Default::default());
        let scope = &mut v8::ContextScope::new(scope, context);
        let state = install_generated_bindings(scope, context, dom, RealmId(0), 1).unwrap();
        state.commit_location("https://example.test/page").unwrap();
        let source = v8::String::new(scope, r#"
            const check=(value,message)=>{if(!value)throw Error(message)};
            const xhr=new XMLHttpRequest(),other=new XMLHttpRequest(),upload=xhr.upload;
            check(upload===xhr.upload && upload!==other.upload,'upload identity');
            check(xhr instanceof XMLHttpRequestEventTarget && upload instanceof XMLHttpRequestUpload && upload instanceof XMLHttpRequestEventTarget && upload instanceof EventTarget,'inheritance');
            let received=0,download=0;
            upload.onprogress=function(event){check(this===upload && event.target===upload,'upload receiver');received+=event.loaded};
            xhr.onprogress=()=>download++;
            upload.dispatchEvent(new ProgressEvent('progress',{loaded:3}));
            check(received===3 && download===0,'independent registry');
            xhr.open('GET','/one');xhr.abort();xhr.open('POST','/two');
            check(xhr.upload===upload,'identity survives lifecycle');
            upload.dispatchEvent(new ProgressEvent('progress',{loaded:2}));
            check(received===5,'handlers survive lifecycle');
            'ok';
        "#).unwrap();
        assert_eq!(
            test_eval::run(scope, source).to_rust_string_lossy(scope),
            "ok"
        );
    }

