    #[test]
    fn trusted_script_preparation_rejects_callback_replaced_document_authority() {
        fn invalidate(
            scope: &mut v8::PinScope,
            args: v8::FunctionCallbackArguments,
            _rv: v8::ReturnValue,
        ) {
            let state = scope
                .get_current_context()
                .get_slot::<V8BindingState>()
                .unwrap();
            match args.data().int32_value(scope).unwrap() {
                0 => state
                    .document_stream_epoch
                    .set(state.document_stream_epoch().wrapping_add(1)),
                1 => state
                    .document_authority_epoch
                    .set(state.document_authority_epoch().wrapping_add(1)),
                _ => state.retire_execution(),
            }
        }
        initialize_v8();
        for mode in 0..3 {
            let dom = Rc::new(RefCell::new(
                html::parse("<body></body>").into_runtime().unwrap(),
            ));
            let mut isolate = v8::Isolate::new(Default::default());
            v8::scope!(let scope,&mut isolate);
            let context = v8::Context::new(scope, Default::default());
            let scope = &mut v8::ContextScope::new(scope, context);
            let state =
                install_generated_bindings(scope, context, dom.clone(), RealmId(0), 1).unwrap();
            state.configure_trusted_types(TrustedTypesConfig {
                require_script: true,
                allow_any_policy: true,
                ..Default::default()
            });
            let data = v8::Integer::new(scope, mode);
            let callback = v8::Function::builder(invalidate)
                .data(data.into())
                .build(scope)
                .unwrap();
            let key = v8::String::new(scope, "invalidateNativeOwner").unwrap();
            context
                .global(scope)
                .create_data_property(scope, key.into(), callback.into());
            let source=v8::String::new(scope,"trustedTypes.createPolicy('default',{createScript(s){invalidateNativeOwner();return s}})").unwrap();
            assert!(
                v8::Script::compile(scope, source, None)
                    .unwrap()
                    .run(scope)
                    .is_some()
            );
            let script = {
                let mut dom = dom.borrow_mut();
                let script = dom.create_element("script");
                dom.set_text_content(script, "globalThis.unexpected=true")
                    .unwrap();
                let body = dom.query_selector(dom.document(), "body").unwrap().unwrap();
                dom.append_child(body, script).unwrap();
                script
            };
            assert!(
                prepare_inline_script_or_queue(scope, &state, script)
                    .unwrap()
                    .is_none()
            );
            assert!(
                dom.borrow()
                    .arena()
                    .get(script)
                    .unwrap()
                    .script_trusted_text
                    .is_empty(),
                "obsolete callback result must not change remembered trust, mode {mode}"
            );
            assert!(!dom.borrow().script_already_started(script).unwrap());
            assert!(state.pending_dynamic_scripts.borrow().is_empty());
        }
    }

    #[test]
    fn script_preparation_uses_remembered_trusted_text_after_dom_mutations() {
        initialize_v8();
        let mut isolate = v8::Isolate::new(Default::default());
        v8::scope!(let scope,&mut isolate);
        let context = v8::Context::new(scope, Default::default());
        let scope = &mut v8::ContextScope::new(scope, context);
        let dom = Rc::new(RefCell::new(
            html::parse("<body></body>").into_runtime().unwrap(),
        ));
        let state = install_generated_bindings(scope, context, dom, RealmId(0), 1).unwrap();
        state.configure_trusted_types(TrustedTypesConfig {
            require_script: true,
            allow_any_policy: true,
            ..Default::default()
        });
        let source=v8::String::new(scope,r#"(() => {
            const check=(value,message)=>{if(!value)throw Error(message)};
            globalThis.runs=0;
            const policy=trustedTypes.createPolicy('script-text',{createScript:x=>x});
            const make=()=>{const script=document.createElement('script');script.text=policy.createScript('runs++');return script};
            const split=make();split.firstChild.splitText(3);split.normalize();document.body.appendChild(split);
            check(runs===1,'unchanged split/normalized source retains trust');
            const original=make();document.body.appendChild(original.cloneNode(true));
            check(runs===1,'clone drops trusted script text');
            const borrowed=document.createElement('script');
            Object.getOwnPropertyDescriptor(Node.prototype,'textContent').set.call(borrowed,'runs+=100');
            document.body.appendChild(borrowed);check(runs===1,'borrowed Node setter leaves source untrusted without throwing');
            const borrowedInner=document.createElement('script');
            Object.getOwnPropertyDescriptor(HTMLElement.prototype,'innerText').set.call(borrowedInner,'runs+=100');
            document.body.appendChild(borrowedInner);check(runs===1,'borrowed HTMLElement setter leaves source untrusted');
            let rejected=false;try{document.createElement('script').textContent='runs+=100'}catch(error){rejected=error instanceof TypeError}
            check(rejected,'script-specific textContent requires trusted input');
            const direct=document.createElement('script');direct.innerText=policy.createScript('runs++');document.body.appendChild(direct);check(runs===2,'script-specific innerText stores accepted source');
            let calls=0;
            trustedTypes.createPolicy('default',{createScript(input,kind,sink){calls++;check(kind==='TrustedScript','script preparation brand');check(sink==='HTMLScriptElement text','script preparation sink');return 'runs+=10'}});
            const changed=make();changed.firstChild.data='runs+=1000';document.body.appendChild(changed);
            check(calls===1&&runs===12&&changed.text==='runs+=1000','preparation executes accepted source without rewriting child text');
            const empty=make();Object.getOwnPropertyDescriptor(Node.prototype,'textContent').set.call(empty,'');document.body.appendChild(empty);
            check(calls===2&&runs===22,'default policy runs before empty-source rejection');
            const assigned=document.createElement('script');assigned.text='anything';document.body.appendChild(assigned);
            check(calls===3&&runs===32,'accepted setter source is not converted again during preparation');
            return true;
        })()"#).unwrap();
        assert!(
            v8::Script::compile(scope, source, None)
                .unwrap()
                .run(scope)
                .unwrap()
                .is_true()
        );
    }

    #[test]
    fn native_text_setters_preserve_nullable_and_utf16_values() {
        initialize_v8();
        let mut isolate = v8::Isolate::new(Default::default());
        v8::scope!(let scope,&mut isolate);
        let context = v8::Context::new(scope, Default::default());
        let scope = &mut v8::ContextScope::new(scope, context);
        let dom = Rc::new(RefCell::new(
            html::parse("<body></body>").into_runtime().unwrap(),
        ));
        let _state = install_generated_bindings(scope, context, dom, RealmId(0), 1).unwrap();
        let source=v8::String::new(scope,r#"(() => {
            const check=(value,message)=>{if(!value)throw Error(message)};
            const samples=['\uD800','\uDC00','\uD83D\uDE00','\0'];
            for(const create of [()=>document.createTextNode(''),()=>document.createComment(''),()=>document.createElement('div')]){
                const node=create();
                for(const value of samples){node.textContent=value;check(node.textContent===value,'lossless textContent')}
                for(const value of [null,undefined]){node.textContent='before';node.textContent=value;check(node.textContent==='','nullable textContent')}
            }
            const text=document.createTextNode('');
            for(const value of samples){text.data=value;check(text.data===value,'lossless CharacterData');text.nodeValue=value;check(text.nodeValue===value,'lossless nodeValue')}
            text.nodeValue=undefined;check(text.nodeValue==='','nullable nodeValue');
            const ordinary=document.createElementNS('urn:custom','script');ordinary.textContent='raw';check(ordinary.textContent==='raw','foreign script name is ordinary text');
            return true;
        })()"#).unwrap();
        assert!(
            v8::Script::compile(scope, source, None)
                .unwrap()
                .run(scope)
                .unwrap()
                .is_true()
        );
    }

    #[test]
    fn trusted_attribute_mutations_share_native_sink_names() {
        initialize_v8();
        let mut isolate = v8::Isolate::new(Default::default());
        v8::scope!(let scope,&mut isolate);
        let context = v8::Context::new(scope, Default::default());
        let scope = &mut v8::ContextScope::new(scope, context);
        let dom = Rc::new(RefCell::new(
            html::parse("<body></body>").into_runtime().unwrap(),
        ));
        let state = install_generated_bindings(scope, context, dom, RealmId(0), 1).unwrap();
        state.configure_trusted_types(TrustedTypesConfig {
            require_script: true,
            allow_any_policy: true,
            ..Default::default()
        });
        let source=v8::String::new(scope,r#"(() => {
            const seen=[];const policy=(input,kind,sink)=>{seen.push([input,kind,sink]);return input};
            trustedTypes.createPolicy('default',{createHTML:policy,createScript:policy,createScriptURL:policy});
            for(const [namespace,tag,attribute,kind,sink] of [
                ['http://www.w3.org/1999/xhtml','iframe','srcdoc','TrustedHTML','HTMLIFrameElement srcdoc'],
                ['http://www.w3.org/1999/xhtml','script','src','TrustedScriptURL','HTMLScriptElement src'],
                ['http://www.w3.org/1999/xhtml','div','onclick','TrustedScript','Element onclick'],
                ['http://www.w3.org/2000/svg','script','href','TrustedScriptURL','SVGScriptElement href']]){
                const element=document.createElementNS(namespace,tag);
                for(const write of [()=>element.setAttribute(attribute,'value'),()=>element.setAttributeNS(null,attribute,'value'),
                    ()=>{const attr=document.createAttribute(attribute);attr.value='value';element.setAttributeNode(attr)},
                    ()=>{element.getAttributeNode(attribute).value='value'}]){
                    const count=seen.length;write();
                    if(seen.length!==count+1||JSON.stringify(seen.at(-1))!==JSON.stringify(['value',kind,sink]))throw Error('native attribute sink '+sink);
                }
            }
            return true;
        })()"#).unwrap();
        assert!(
            v8::Script::compile(scope, source, None)
                .unwrap()
                .run(scope)
                .unwrap()
                .is_true()
        );
    }

    #[test]
    fn trusted_policy_checks_capture_native_script_location() {
        initialize_v8();
        let mut isolate = v8::Isolate::new(Default::default());
        v8::scope!(let scope,&mut isolate);
        let context = v8::Context::new(scope, Default::default());
        let scope = &mut v8::ContextScope::new(scope, context);
        let dom = Rc::new(RefCell::new(
            html::parse("<body></body>").into_runtime().unwrap(),
        ));
        let state = install_generated_bindings(scope, context, dom, RealmId(0), 1).unwrap();
        let checks = Rc::new(RefCell::new(Vec::new()));
        let saved = checks.clone();
        state.set_trusted_types_policy(Rc::new(move |_, check| {
            saved.borrow_mut().push(check.clone());
            Ok(true)
        }));
        let source = v8::String::new(
            scope,
            "trustedTypes.createPolicy('location',{});
const target=document.createElement('iframe');
target.srcdoc='raw';
//# sourceURL=https://example.test/trusted-location.js",
        )
        .unwrap();
        assert!(
            v8::Script::compile(scope, source, None)
                .unwrap()
                .run(scope)
                .is_some()
        );
        let checks = checks.borrow();
        let locations = checks
            .iter()
            .filter_map(|check| match check {
                crate::trusted_types::PolicyCheck::Policy { location, .. }
                | crate::trusted_types::PolicyCheck::Sink { location, .. } => Some(location),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert_eq!(locations.len(), 2);
        assert_eq!(locations[0].line, 1);
        assert_eq!(locations[1].line, 3);
        for location in locations {
            assert_eq!(
                location.source_file,
                "https://example.test/trusted-location.js"
            );
            assert!(location.column > 0);
        }
    }

    #[test]
    fn trusted_native_policy_hook_handles_report_only_and_default_fallback() {
        initialize_v8();
        let mut isolate = v8::Isolate::new(Default::default());
        v8::scope!(let scope,&mut isolate);
        let context = v8::Context::new(scope, Default::default());
        let scope = &mut v8::ContextScope::new(scope, context);
        let dom = Rc::new(RefCell::new(
            html::parse("<body></body>").into_runtime().unwrap(),
        ));
        let state = install_generated_bindings(scope, context, dom, RealmId(0), 1).unwrap();
        let checks = Rc::new(RefCell::new(Vec::new()));
        let saved = checks.clone();
        let enforcing = Rc::new(Cell::new(false));
        let enforcing_hook = enforcing.clone();
        state.set_trusted_types_policy(Rc::new(move |_, check| {
            saved.borrow_mut().push(check.clone());
            Ok(match check {
                crate::trusted_types::PolicyCheck::SinkRequired => true,
                crate::trusted_types::PolicyCheck::Policy { .. } => true,
                crate::trusted_types::PolicyCheck::Sink { .. } => !enforcing_hook.get(),
            })
        }));
        let eval = |scope: &mut v8::PinScope, source: &str| {
            let source = v8::String::new(scope, source).unwrap();
            v8::Script::compile(scope, source, None)
                .unwrap()
                .run(scope)
                .unwrap()
                .is_true()
        };
        assert!(eval(
            scope,
            "globalThis.target=document.createElement('iframe');target.srcdoc='raw';target.srcdoc==='raw'"
        ));
        assert!(
            matches!(checks.borrow().last(),Some(crate::trusted_types::PolicyCheck::Sink{sink,input,..}) if sink=="HTMLIFrameElement srcdoc"&&input=="raw")
        );
        assert!(eval(
            scope,
            "globalThis.callbackInputs=[];trustedTypes.createPolicy('default',{createHTML(input){callbackInputs.push(input);if(input==='throw')throw 42;return input==='null'?null:'safe:'+input}});target.srcdoc='accepted';target.srcdoc==='safe:accepted'"
        ));
        assert!(matches!(
            checks.borrow().last(),
            Some(crate::trusted_types::PolicyCheck::SinkRequired)
        ));
        assert!(eval(
            scope,
            "target.srcdoc='null';target.srcdoc==='null'&&callbackInputs.at(-1)==='null'"
        ));
        enforcing.set(true);
        assert!(eval(
            scope,
            "(()=>{try{target.srcdoc='null'}catch(error){return error instanceof TypeError&&target.srcdoc==='null'}return false})()"
        ));
        let reports = checks
            .borrow()
            .iter()
            .filter(|check| matches!(check, crate::trusted_types::PolicyCheck::Sink { .. }))
            .count();
        assert!(eval(
            scope,
            "(()=>{try{target.srcdoc='throw'}catch(error){return error===42}return false})()"
        ));
        assert_eq!(
            checks
                .borrow()
                .iter()
                .filter(|check| matches!(check, crate::trusted_types::PolicyCheck::Sink { .. }))
                .count(),
            reports
        );
        assert!(eval(
            scope,
            "globalThis.branded=trustedTypes.createPolicy('brand',{createHTML:x=>x}).createHTML('brand');true"
        ));
        checks.borrow_mut().clear();
        assert!(eval(scope, "target.srcdoc=branded;target.srcdoc==='brand'"));
        assert!(checks.borrow().is_empty());
    }

    #[test]
    fn trusted_property_sinks_enforce_policy_and_supply_standard_sink_names() {
        initialize_v8();
        let mut isolate = v8::Isolate::new(Default::default());
        v8::scope!(let scope,&mut isolate);
        let context = v8::Context::new(scope, Default::default());
        let scope = &mut v8::ContextScope::new(scope, context);
        let dom = Rc::new(RefCell::new(
            html::parse("<body></body>").into_runtime().unwrap(),
        ));
        let state = install_generated_bindings(scope, context, dom, RealmId(0), 1).unwrap();
        state.configure_trusted_types(TrustedTypesConfig {
            require_script: true,
            allow_any_policy: true,
            ..Default::default()
        });
        let source=v8::String::new(scope,r#"(() => {
            const check=(value,message)=>{if(!value)throw Error(message)};
            const rows=[['script','src','TrustedScriptURL','HTMLScriptElement src'],
                ['iframe','srcdoc','TrustedHTML','HTMLIFrameElement srcdoc'],
                ['script','text','TrustedScript','HTMLScriptElement text'],
                ['div','innerHTML','TrustedHTML','Element innerHTML']];
            const targets=rows.map(([tag,property])=>{
                const element=document.createElement(tag);let caught;
                try{element[property]='blocked'}catch(error){caught=error}
                check(caught instanceof TypeError,'raw property assignment requires a policy');
                check(element[property]==='','failed property assignment leaves value intact');return element;
            });
            const seen=[];const reason={identity:true};
            const callback=(input,kind,sink)=>{
                seen.push([input,kind,sink]);
                if(input==='throw')throw reason;
                if(input==='null')return null;
                return 'accepted:'+input;
            };
            trustedTypes.createPolicy('default',{createHTML:callback,createScript:callback,createScriptURL:callback});
            rows.forEach(([tag,property,kind,sink],index)=>{
                const element=targets[index];element[property]='value';
                check(JSON.stringify(seen.at(-1))===JSON.stringify(['value',kind,sink]),'default callback sink arguments');
                const previous=element[property];
                for(const input of ['null','throw']){
                    let caught;try{element[property]=input}catch(error){caught=error}
                    check(input==='throw'?caught===reason:caught instanceof TypeError,'default callback failure identity');
                    check(element[property]===previous,'rejected policy preserves property');
                }
            });
            const scalarInput='\uD800';targets[0].src=scalarInput;
            check(seen.at(-1)[0]===scalarInput.toWellFormed(),'script src converts USVString before default callback');
            check(targets[0].getAttribute('src')==='accepted:'+scalarInput.toWellFormed(),'script src stores scalar result');
            targets[1].srcdoc=scalarInput;
            check(seen.at(-1)[0]===scalarInput&&targets[1].getAttribute('srcdoc')==='accepted:'+scalarInput,'srcdoc preserves DOMString');
            return true;
        })()"#).unwrap();
        assert!(
            v8::Script::compile(scope, source, None)
                .unwrap()
                .run(scope)
                .unwrap()
                .is_true()
        );
    }

