        let state = install_generated_bindings(scope, context, dom, RealmId(0), 1).unwrap();
        let host = Rc::new(TestPlatformHost::default());
        host.block_idb_admission_once
            .store(true, std::sync::atomic::Ordering::SeqCst);
        state.set_platform_host(host.clone());
        let source=v8::String::new(scope,"globalThis.location.href='https://example.test/';globalThis.completed=0;const opening=indexedDB.open('admission',2);opening.onupgradeneeded=()=>opening.result.createObjectStore('store');opening.onsuccess=()=>{const tx=opening.result.transaction('store','readonly');tx.oncomplete=()=>completed++;};").unwrap();
        v8::Script::compile(scope, source, None)
