        let source=v8::String::new(scope,r#"globalThis.reads=0;globalThis.original=(()=>{const shared={label:'key'};const buffer=new ArrayBuffer(8);const view=new Uint8Array(buffer,2,3);view[0]=7;const root={shared,again:shared,buffer,view,map:new Map([[shared,shared]]),set:new Set([shared]),big:12345678901234567890n,boxed:Object(12n),negativeZero:-0,error:new TypeError('stored'),spoof:{__oryn_projection_ref:0}};root.self=root;Object.defineProperty(root,'once',{enumerable:true,get(){reads++;return shared}});return root})();original"#).unwrap();
        let value = v8::Script::compile(scope, source, None)
            .unwrap()
            .run(scope)
            .unwrap();
        let mut stored = idb_value_to_json(scope, &state, value).unwrap();
