    #[test]
    fn indexeddb_close_pending_blocks_upgrade_until_preexisting_transactions_settle() {
        initialize_v8();
        let dom = Rc::new(RefCell::new(
            html::parse("<body></body>").into_runtime().unwrap(),
        ));
        let mut isolate = v8::Isolate::new(Default::default());
        isolate.set_microtasks_policy(v8::MicrotasksPolicy::Explicit);
        v8::scope!(let scope,&mut isolate);
        let context = v8::Context::new(scope, Default::default());
        let scope = &mut v8::ContextScope::new(scope, context);
        let state = install_generated_bindings(scope, context, dom, RealmId(0), 1).unwrap();
        state.commit_location("https://example.test/").unwrap();
        state.set_platform_host(Rc::new(TestPlatformHost {
            // The command-result mock must report the database created above
            // version 0 when this fixture opens it again at version 2.
            idb_old_versions: BTreeMap::from([(("close-upgrade".into(), 2), 1)]),
            ..Default::default()
        }));
        let source=v8::String::new(scope,r#"
            globalThis.events=[];
            const first=indexedDB.open('close-upgrade',1);
            first.onupgradeneeded=()=>first.result.createObjectStore('items');
            first.onsuccess=()=>{
                const db=first.result;
                const commit=db.transaction('items','readwrite');
                const abort=db.transaction('items','readwrite');
                commit.oncomplete=()=>events.push('complete');
                abort.onabort=()=>events.push('abort');
                abort.abort();db.close();
                db.onversionchange=()=>events.push('unexpected-versionchange');
                const upgrade=indexedDB.open('close-upgrade',2);
                upgrade.onblocked=e=>events.push('blocked:'+e.oldVersion+':'+e.newVersion);
                upgrade.onupgradeneeded=()=>events.push('upgrade:'+events.filter(x=>x==='complete'||x==='abort').length);
                upgrade.onsuccess=()=>{events.push('success');upgrade.result.close()};
            };
        "#).unwrap();
        test_eval::run(scope, source);
        for _ in 0..128 {
            state.drain_platform_completions(scope, 32).unwrap();
            scope.perform_microtask_checkpoint();
        }
        // IndexedDB opening/closing algorithms: close-pending connections
        // still block upgrades until their existing transactions finish.
        let source=v8::String::new(scope,"events.length===5&&events[0]==='blocked:1:2'&&events.includes('complete')&&events.includes('abort')&&events[3]==='upgrade:2'&&events[4]==='success'").unwrap();
        assert!(
            test_eval::run(scope, source).is_true(),
            "events: {}",
            test_eval::eval(scope, "JSON.stringify(events)").to_rust_string_lossy(scope)
        );
    }

    #[test]
    fn indexeddb_close_waits_for_queued_transactions_and_native_settlement() {
        initialize_v8();
        let dom = Rc::new(RefCell::new(
            html::parse("<main></main>").into_runtime().unwrap(),
        ));
        let mut isolate = v8::Isolate::new(Default::default());
        isolate.set_microtasks_policy(v8::MicrotasksPolicy::Explicit);
        v8::scope!(let scope, &mut isolate);
        let context = v8::Context::new(scope, Default::default());
        let scope = &mut v8::ContextScope::new(scope, context);
        let state = install_generated_bindings(scope, context, dom, RealmId(0), 1).unwrap();
        let host = Rc::new(TestPlatformHost {
            idb_connection_managed: true,
            ..Default::default()
        });
        state.set_platform_host(host.clone());
        let source = v8::String::new(
            scope,
            r#"
            location.href='https://example.test/';globalThis.db=null;
            globalThis.events=[];
            const open=indexedDB.open('close-pending',1);
            open.onupgradeneeded=()=>open.result.createObjectStore('items');
            open.onsuccess=()=>db=open.result;
        "#,
        )
        .unwrap();
        v8::Script::compile(scope, source, None)
            .unwrap()
            .run(scope)
            .unwrap();
        for _ in 0..32 {
            state.drain_platform_completions(scope, 32).unwrap();
            scope.perform_microtask_checkpoint();
        }
        let source = v8::String::new(
            scope,
            r#"
            // Exceed the native in-flight limit: close must protect transactions
            // whose BeginTransaction command has not reached the host yet.
            for(let i=0;i<40;i++) {
                const tx=db.transaction('items','readwrite');
                tx.oncomplete=()=>events.push('complete');
                tx.onabort=()=>events.push('abort');
                if(i===39)tx.abort();
            }
            db.close();db.close();
            try {db.transaction('items');throw Error('new transaction accepted')}
            catch(error) {if(error.name!=='InvalidStateError')throw error}
        "#,
        )
        .unwrap();
        v8::Script::compile(scope, source, None)
            .unwrap()
            .run(scope)
            .unwrap();
        let database_id = state
            .platform_objects
            .borrow()
            .iter()
            .find_map(|(id, record)| match record {
                PlatformObjectRecord::IdbDatabase(db) if db.name == "close-pending" => Some(*id),
                _ => None,
            })
            .unwrap();
        assert!(state.idb_database_has_transactions(database_id));
        assert!(state.idb_database_blocks_change("close-pending"));
        assert!(!state.idb_database_blocks_change("unrelated"));
        assert!(state.has_pending_background_clients());
        assert_eq!(host.idb_closes.load(std::sync::atomic::Ordering::SeqCst), 0);
        for _ in 0..256 {
            state.drain_platform_completions(scope, 32).unwrap();
            scope.perform_microtask_checkpoint();
            if state.idb_database_has_transactions(database_id) {
                assert_eq!(host.idb_closes.load(std::sync::atomic::Ordering::SeqCst), 0);
                assert!(state.idb_database_blocks_change("close-pending"));
            }
        }
        assert!(!state.idb_database_has_transactions(database_id));
        assert!(!state.idb_database_blocks_change("close-pending"));
        assert_eq!(host.idb_closes.load(std::sync::atomic::Ordering::SeqCst), 1);
        let source = v8::String::new(
            scope,
            "events.filter(x=>x==='complete').length+'|'+events.filter(x=>x==='abort').length",
        )
        .unwrap();
        assert_eq!(
            v8::Script::compile(scope, source, None)
                .unwrap()
                .run(scope)
                .unwrap()
                .to_rust_string_lossy(scope),
            "39|1"
        );
    }

