    #[test]
    fn event_records_follow_javascript_lifetime_and_ids_never_alias() {
        initialize_v8();
        let dom = Rc::new(RefCell::new(
            html::parse("<p>events</p>").into_runtime().unwrap(),
        ));
        let mut isolate = v8::Isolate::new(Default::default());
        v8::scope!(let scope, &mut isolate);
        let context = v8::Context::new(scope, Default::default());
        let scope = &mut v8::ContextScope::new(scope, context);
        let state = install_generated_bindings(scope, context, dom, RealmId(0), 1).unwrap();
        let source = v8::String::new(
            scope,
            r#"
            globalThis.keptEvent=new PageTransitionEvent('pageshow',{persisted:true});
            for(let i=0;i<256;i++) {
              new Event('transient');new MessageEvent('message',{data:{i}});
              new UIEvent('ui');new ErrorEvent('error',{error:{i}});
            }
            true
        "#,
        )
        .unwrap();
        assert!(
            v8::Script::compile(scope, source, None)
                .unwrap()
                .run(scope)
                .unwrap()
                .is_true()
        );
        scope.low_memory_notification();
        state.reclaim_collected_events();
        assert_eq!(state.events.borrow().len(), 1);
        assert_eq!(state.event_objects.borrow().len(), 1);
        let source =
            v8::String::new(scope, "keptEvent.persisted && keptEvent.type==='pageshow'").unwrap();
        assert!(
            v8::Script::compile(scope, source, None)
                .unwrap()
                .run(scope)
                .unwrap()
                .is_true()
        );
        let max = (1_u64 << 53) - 1;
        state.next_event_id.set(max);
        assert_eq!(state.allocate_event_id().unwrap(), max);
        assert!(state.allocate_event_id().is_err());
        assert_eq!(state.next_event_id.get(), max + 1);
        let source = v8::String::new(scope, "keptEvent=null; true").unwrap();
        v8::Script::compile(scope, source, None)
            .unwrap()
            .run(scope)
            .unwrap();
        scope.low_memory_notification();
        state.reclaim_collected_events();
        assert!(state.events.borrow().is_empty());
        assert!(state.event_objects.borrow().is_empty());
    }

