    #[test]
    fn invalid_tree_insertions_preserve_documents_fragments_and_live_ranges() {
        initialize_v8();
        let parsed = html::parse("<!doctype html><main>text</main>");
        let dom = Rc::new(RefCell::new(parsed.into_runtime().unwrap()));
        let mut isolate = v8::Isolate::new(Default::default());
        v8::scope!(let scope, &mut isolate);
        let context = v8::Context::new(scope, Default::default());
        let scope = &mut v8::ContextScope::new(scope, context);
        install_generated_bindings(scope, context, dom, RealmId(0), 1).unwrap();
        let source = v8::String::new(scope, r#"
            const check = (value, message) => { if (!value) throw new Error(message); };
            const reject = (operation, name) => {
                try { operation(); } catch (e) { check(e.name === name, e.name); return; }
                throw new Error('insertion unexpectedly succeeded');
            };
            const host = document.querySelector('main'), type = document.doctype;
            const range = document.createRange(); range.selectNode(type);
            reject(() => host.appendChild(type), 'HierarchyRequestError');
            reject(() => host.insertBefore(type, host.firstChild), 'HierarchyRequestError');
            const attribute = document.createAttribute('probe');
            const beforeAttributeAttempt = host.innerHTML;
            reject(() => host.appendChild(attribute), 'HierarchyRequestError');
            reject(() => host.insertBefore(attribute, host.firstChild), 'HierarchyRequestError');
            reject(() => host.replaceChild(attribute, host.firstChild), 'HierarchyRequestError');
            check(host.innerHTML === beforeAttributeAttempt && attribute.parentNode === null, 'attribute rejection is atomic');
            check(document.doctype === type && type.parentNode === document, 'doctype preserved');
            check(range.startContainer === document && range.startOffset === 0 && range.endOffset === 1, 'range preserved');
            const fragment = document.createDocumentFragment();
            fragment.appendChild(document.createElement('one'));
            fragment.appendChild(document.createElement('two'));
            reject(() => document.appendChild(fragment), 'HierarchyRequestError');
            check(fragment.childNodes.length === 2, 'fragment not partially consumed');
            reject(() => document.insertBefore(document.createComment('x'), host), 'NotFoundError');
            reject(() => document.appendChild(document.createTextNode('x')), 'HierarchyRequestError');
            reject(() => host.firstChild.appendChild(document.createElement('x')), 'HierarchyRequestError');
            const detached = document.createTextNode('abcd');
            const detachedRange = document.createRange();
            detachedRange.setStart(detached, 1); detachedRange.setEnd(detached, 3);
            const detachedTail = detached.splitText(2);
            check(detachedRange.startContainer === detached && detachedRange.startOffset === 1 && detachedRange.endContainer === detached && detachedRange.endOffset === 2, 'detached split clamps original range');
            check(detachedTail.data === 'cd' && detachedTail.parentNode === null, 'detached tail');
            const text = host.firstChild;
            const textRange = document.createRange(); textRange.setStart(text, 1); textRange.setEnd(text, 3);
            const afterText = document.createRange(); afterText.setStart(host, 1); afterText.collapse(true);
            const tail = text.splitText(2);
            check(textRange.startContainer === text && textRange.startOffset === 1 && textRange.endContainer === tail && textRange.endOffset === 1, 'attached split moves trailing boundary');
            check(afterText.startContainer === host && afterText.startOffset === 2 && afterText.endOffset === 2, 'parent boundary follows both text nodes');
            const box = document.createElement('div');
            const oldChild = document.createElement('i'), following = document.createElement('b');
            box.appendChild(oldChild); box.appendChild(following);
            const replacementRange = document.createRange(); replacementRange.setStart(box, 1); replacementRange.collapse(true);
            const nodes = document.createDocumentFragment();
            const first = document.createTextNode('first'), second = document.createTextNode('second');
            nodes.appendChild(first); nodes.appendChild(second);
            check(box.replaceChild(nodes, oldChild) === oldChild, 'replacement return value');
            check(box.childNodes.length === 3 && box.firstChild === first && first.nextSibling === second && second.nextSibling === following, 'fragment insertion order');
            check(nodes.childNodes.length === 0 && oldChild.parentNode === null, 'fragment consumed and child detached');
            check(replacementRange.startContainer === box && replacementRange.startOffset === 0 && replacementRange.endOffset === 0, 'replacement removes before insertion');
            const original = document.documentElement, replacement = document.createElement('html');
            document.replaceChild(replacement, original);
            check(document.documentElement === replacement && document.doctype === type, 'valid root replacement');
            'ok'
        "#).unwrap();
        let result = v8::Script::compile(scope, source, None)
            .unwrap()
            .run(scope)
            .unwrap()
            .to_rust_string_lossy(scope);
        assert_eq!(result, "ok");
    }

    #[test]
    fn token_lists_are_live_indexed_branded_and_preserve_literal_values() {
        initialize_v8();
        let dom = Rc::new(RefCell::new(
            html::parse("<main class='  a a b  '></main>")
                .into_runtime()
                .unwrap(),
        ));
        let mut isolate = v8::Isolate::new(Default::default());
        v8::scope!(let scope, &mut isolate);
        let context = v8::Context::new(scope, Default::default());
        let scope = &mut v8::ContextScope::new(scope, context);
        install_generated_bindings(scope, context, dom, RealmId(0), 1).unwrap();
        let source = v8::String::new(scope, r#"
            const check=(ok,message)=>{if(!ok)throw new Error(message)};
            const element=document.querySelector('main'), list=element.classList;
            check(list===element.classList && list.length===2,'same live list');
            check(String(list)==='  a a b  ' && list.value==='  a a b  ','literal string');
            check(list.item(2)===null && list[2]===undefined && !(2 in list),'absent index');
            check(Object.keys(list).join(',')==='0,1','enumerable indices');
            check(list.values===Array.prototype.values && list[Symbol.iterator]===list.values,'intrinsic iterator');
            const iterator=list.values();check(iterator.next().value==='a','first item');
            element.className='x y z';
            check(iterator.next().value==='y' && list.length===3,'iteration is live');
            check(list.replace('y','z') && [...list].join(',')==='x,z','ordered set replace');
            element.classList='  q q r  ';
            check(list.value==='  q q r  ' && list.length===2,'put forwards value');
            const before=list.value;
            try {list.add('valid','bad token');throw Error('accepted invalid token')} catch(e) {check(e.name==='InvalidCharacterError','validation error')}
            check(list.value===before,'validation is atomic');
            check(Reflect.set(list,'0','wrong')===false && list[0]==='q','indices are read only');
            check(Reflect.deleteProperty(list,'0')===false,'indices cannot be deleted');
            for(const receiver of [element,{},Object.create(list),new Proxy(list,{})]) {
                try {DOMTokenList.prototype.toString.call(receiver);throw Error('accepted invalid receiver')} catch(e) {check(e.name==='TypeError','receiver brand')}
            }
            try {list.supports('q');throw Error('class supports tokens')} catch(e) {check(e.name==='TypeError','unsupported vocabulary')}
            list.value='a\u00a0b a\vb a\tb';
            check(list.length===4,'only ASCII space characters split tokens');
            'ok'
        "#).unwrap();
        assert_eq!(
            v8::Script::compile(scope, source, None)
                .unwrap()
                .run(scope)
                .unwrap()
                .to_rust_string_lossy(scope),
            "ok"
        );
    }

    #[test]
    fn explicit_editing_overrides_survive_paste_and_clear_on_selection_changes() {
        initialize_v8();
        let dom = Rc::new(RefCell::new(
            html::parse("<main contenteditable>hello</main><aside contenteditable>world</aside>")
                .into_runtime()
                .unwrap(),
        ));
        let mut isolate = v8::Isolate::new(Default::default());
        v8::scope!(let scope, &mut isolate);
        let context = v8::Context::new(scope, Default::default());
        let scope = &mut v8::ContextScope::new(scope, context);
        install_generated_bindings(scope, context, dom, RealmId(0), 1).unwrap();
        let source = v8::String::new(scope, r#"
            const check=(ok,message)=>{if(!ok)throw new Error(message)};
            const host=document.querySelector('main'),other=document.querySelector('aside'),selection=document.getSelection();
            selection.collapse(host.firstChild,2);
            document.execCommand('bold');
            check(document.queryCommandState('bold'),'explicit bold');
            document.execCommand('insertHTML',false,'x<i>y</i>z');
            check(document.queryCommandState('bold'),'paste preserves override');
            document.execCommand('insertText',false,'Q');
            check(document.queryCommandState('bold'),'typing preserves override');
            const caretElement=selection.anchorNode.nodeType===1?selection.anchorNode:selection.anchorNode.parentElement;
            check(caretElement.closest('b,strong')?.textContent==='Q','typed text has actual bold formatting');
            selection.collapse(other.firstChild,1);
            check(!document.queryCommandState('bold'),'moving selection clears override');
            document.execCommand('italic');
            document.execCommand('insertHTML',false,'plain');
            check(document.queryCommandState('italic'),'explicit italic survives paste');
            selection.removeAllRanges();
            check(!document.queryCommandState('italic'),'empty selection clears override');
            for (const command of ['delete','forwardDelete','insertLineBreak','insertParagraph','formatBlock','insertOrderedList','insertUnorderedList']) {
                host.innerHTML='foobar';
                selection.collapse(host.firstChild,3);
                document.execCommand('bold');
                check(document.queryCommandState('bold'),command+': initial typing state');
                document.execCommand(command,false,command==='formatBlock'?'div':'');
                check(document.queryCommandState('bold'),command+': internal caret movement preserves typing state');
                selection.collapse(other.firstChild,1);
                check(!document.queryCommandState('bold'),command+': external selection clears typing state');
            }
            for (const commands of [['italic','bold'],['bold','italic']]) {
                host.innerHTML='ac';selection.collapse(host.firstChild,1);
                document.execCommand('styleWithCSS',false,false);
                for (const command of commands) document.execCommand(command);
                document.execCommand('insertText',false,'b');
                const tags=commands.map(command=>command==='bold'?'b':'i');
                const expected='a<'+tags[0]+'><'+tags[1]+'>b</'+tags[1]+'></'+tags[0]+'>c';
                check(host.innerHTML===expected,'typing format command order: '+commands);
                document.execCommand('undo');document.execCommand('redo');
                check(host.innerHTML===expected,'redo preserves typing format order');
                selection.collapse(other.firstChild,1);
            }
            'ok'
        "#).unwrap();
        let actual = test_eval::run(scope, source).to_rust_string_lossy(scope);
        assert_eq!(actual, "ok");
    }

    #[test]
    fn editing_command_settings_and_query_categories_follow_document_semantics() {
        initialize_v8();
        let parsed = html::parse(
            "<main contenteditable><b id='bold'>abc</b><span id='color' style='color:red;background-color:blue;font-size:20px'>def</span></main>",
        );
        let dom = Rc::new(RefCell::new(parsed.into_runtime().unwrap()));
        let mut isolate = v8::Isolate::new(Default::default());
        v8::scope!(let scope, &mut isolate);
        let context = v8::Context::new(scope, Default::default());
        let scope = &mut v8::ContextScope::new(scope, context);
        install_generated_bindings(scope, context, dom, RealmId(0), 1).unwrap();
        let source = v8::String::new(scope, r#"
            const check = (condition, message) => { if (!condition) throw new Error(message); };
            const selection = document.getSelection();
            selection.removeAllRanges();
            for (const command of ['justifyLeft', 'justifyCenter', 'justifyRight', 'justifyFull']) {
                check(!document.queryCommandState(command), command + ' has no active state');
                check(document.queryCommandValue(command) === '', command + ' has no active value');
            }
            check(document.queryCommandEnabled('selectAll'), 'selectAll enabled without an editor');
            for (const command of ['defaultParagraphSeparator', 'styleWithCSS', 'useCSS']) {
                check(!document.queryCommandEnabled(command), command + ' disabled without an editor');
                check(!document.execCommand(command, false, 'true'), command + ' rejects execution without an editor');
            }
            check(!document.queryCommandState('styleWithCSS'), 'rejected command preserves initial CSS flag');
            check(document.queryCommandValue('defaultParagraphSeparator') === 'div', 'rejected command preserves initial paragraph');
            selection.selectAllChildren(document.getElementById('bold'));
            for (const command of ['defaultParagraphSeparator', 'styleWithCSS', 'useCSS']) {
                check(document.queryCommandEnabled(command), command + ' enabled in an editor');
            }
            check(document.execCommand('defaultParagraphSeparator', false, 'P'), 'set paragraph');
            check(document.queryCommandValue('defaultParagraphSeparator') === 'p', 'paragraph value');
            check(!document.execCommand('defaultParagraphSeparator', false, 'br'), 'reject br');
            check(document.queryCommandValue('defaultParagraphSeparator') === 'p', 'preserve paragraph');
            for (const value of ['', 'true', 'arbitrary', 'FALSE']) {
                check(document.execCommand('styleWithCSS', false, value), 'set styling');
                check(document.queryCommandState('styleWithCSS') === (value !== 'FALSE'), 'styling flag');
                check(document.queryCommandValue('styleWithCSS') === '', 'styling has no value');
                check(document.execCommand('useCSS', false, value), 'set legacy styling');
                check(document.queryCommandState('styleWithCSS') === (value === 'FALSE'), 'legacy flag');
                check(!document.queryCommandState('useCSS'), 'legacy has no state');
                check(document.queryCommandValue('useCSS') === '', 'legacy has no value');
            }
            selection.removeAllRanges();
            check(!document.execCommand('styleWithCSS', false, 'false'), 'disabled command cannot clear CSS flag');
            check(document.queryCommandState('styleWithCSS'), 'CSS flag survives disabled command');
            check(!document.execCommand('defaultParagraphSeparator', false, 'div'), 'disabled command cannot reset paragraph');
            check(document.queryCommandValue('defaultParagraphSeparator') === 'p', 'paragraph survives disabled command');
            selection.selectAllChildren(document.getElementById('bold'));
            check(document.queryCommandState('bold'), 'bold state');
            check(document.queryCommandValue('bold') === '', 'bold has no value');
            selection.selectAllChildren(document.getElementById('color'));
            for (const command of ['foreColor', 'backColor', 'hiliteColor', 'fontSize']) {
                check(!document.queryCommandState(command), command + ' has no state');
                check(document.queryCommandValue(command) !== '', command + ' has value');
            }
            'ok'
        "#).unwrap();
        let result = v8::Script::compile(scope, source, None)
            .unwrap()
            .run(scope)
            .unwrap()
            .to_rust_string_lossy(scope);
        assert_eq!(result, "ok");
    }

