    #[test]
    fn character_data_preserves_utf16_and_coerces_before_reading_live_length() {
        initialize_v8();
        let dom = Rc::new(RefCell::new(
            html::parse("<body></body>").into_runtime().unwrap(),
        ));
        let mut isolate = v8::Isolate::new(Default::default());
        v8::scope!(let scope,&mut isolate);
        let context = v8::Context::new(scope, Default::default());
        let scope = &mut v8::ContextScope::new(scope, context);
        install_generated_bindings(scope, context, dom, RealmId(0), 1).unwrap();
        let source=v8::String::new(scope,r#"
            const text=document.createTextNode('\ud800😀\udc00');document.body.append(text);
            const original=[text.length,text.substringData(0,1).charCodeAt(0),text.substringData(1,1).charCodeAt(0)];
            const tail=text.splitText(2);document.body.normalize();
            const restored=[text.length,text.data.charCodeAt(0),text.data.charCodeAt(1),text.data.charCodeAt(2),text.data.charCodeAt(3)];
            text.data='old';text.appendData({toString(){text.data='X';return 'Y'}});
            const appended=text.data;
            let threw=false;try{text.insertData({valueOf(){throw Error('index')}},'!')}catch(e){threw=true}
            text.replaceData(0,1,{toString(){text.data='abc';return 'Q'}});
            [original.join(','),restored.join(','),appended,threw,text.data].join('|')
        "#).unwrap();
        assert_eq!(
            v8::Script::compile(scope, source, None)
                .unwrap()
                .run(scope)
                .unwrap()
                .to_rust_string_lossy(scope),
            "4,55296,55357|4,55296,55357,56832,56320|XY|true|Qbc"
        );
    }

    #[test]
    fn design_mode_uses_native_document_state_and_ignores_unknown_keywords() {
        initialize_v8();
        let dom = Rc::new(RefCell::new(
            html::parse("<body>text</body>").into_runtime().unwrap(),
        ));
        let mut isolate = v8::Isolate::new(Default::default());
        v8::scope!(let scope, &mut isolate);
        let context = v8::Context::new(scope, Default::default());
        let scope = &mut v8::ContextScope::new(scope, context);
        let state = install_generated_bindings(scope, context, dom.clone(), RealmId(0), 1).unwrap();
        let source = v8::String::new(scope, r#"
            document.designMode='ON';
            document.designMode='invalid';
            const retained=document.designMode;
            const host=document.createElement('div');document.body.append(host);
            const inner=document.createElement('span');host.attachShadow({mode:'open'}).append(inner);
            if(inner.isContentEditable)throw Error('designMode crossed shadow boundary');
            let converted=0;
            document.designMode={toString(){converted++;return 'oFf'}};
            let threw=false;try{document.designMode={toString(){throw new Error('conversion')}}}catch(e){threw=true}
            [retained,document.designMode,converted,threw].join('|')
        "#).unwrap();
        assert_eq!(
            v8::Script::compile(scope, source, None)
                .unwrap()
                .run(scope)
                .unwrap()
                .to_rust_string_lossy(scope),
            "on|off|1|true"
        );
        let document = state.document_root();
        assert!(!dom.borrow().document_design_mode(document).unwrap());
        dom.borrow_mut()
            .set_document_design_mode(document, true)
            .unwrap();
        let source = v8::String::new(
            scope,
            "document.designMode+'|'+document.body.isContentEditable",
        )
        .unwrap();
        assert_eq!(
            v8::Script::compile(scope, source, None)
                .unwrap()
                .run(scope)
                .unwrap()
                .to_rust_string_lossy(scope),
            "on|true"
        );
    }

