    #[test]
    #[ignore = "diagnostic only; requires ORYN_WPT_SELECTION_DIRECTORY"]
    fn pinned_selection_extend_assertions_without_browser_reporting() {
        initialize_v8();
        let directory =
            std::path::PathBuf::from(std::env::var("ORYN_WPT_SELECTION_DIRECTORY").unwrap());
        let dom = Rc::new(RefCell::new(
            html::parse(
                "<!doctype html><html><head><title>Selection</title></head><body></body></html>",
            )
            .into_runtime()
            .unwrap(),
        ));
        let mut isolate = v8::Isolate::new(Default::default());
        v8::scope!(let scope, &mut isolate);
        let context = v8::Context::new(scope, Default::default());
        let scope = &mut v8::ContextScope::new(scope, context);
        install_generated_bindings(scope, context, dom, RealmId(0), 1).unwrap();
        // This intentionally isolates runtime assertions from WPT reporting.
        // It is a diagnostic regression, never official WPT pass evidence.
        let prelude = r#"
            globalThis.window = globalThis;
            globalThis.getSelection = () => document.getSelection();
            globalThis.tests = [];
            function test(fn, name) { try { fn(); tests.push('ok'); } catch(e) { tests.push(name + ': ' + String(e)); } }
            function assert_equals(a,b,m) { if (a !== b) throw Error(m || 'equality'); }
            function assert_not_equals(a,b,m) { if (a === b) throw Error(m || 'inequality'); }
            function assert_true(a,m) { if (a !== true) throw Error(m || 'true'); }
            function assert_unreached(m) { throw Error(m || 'unreached'); }
            function assert_throws_dom(name, fn) {
                const names = {INVALID_STATE_ERR:'InvalidStateError', INDEX_SIZE_ERR:'IndexSizeError', INVALID_NODE_TYPE_ERR:'InvalidNodeTypeError'};
                try { fn(); } catch(e) { assert_equals(e.name, names[name] || name); return; }
                throw Error('missing ' + name);
            }
        "#;
        let started = Instant::now();
        for source in [
            prelude.to_string(),
            std::fs::read_to_string(directory.join("common.js")).unwrap(),
            std::fs::read_to_string(directory.join("extend.js")).unwrap(),
            "testExtendSubSet(0,20);testExtendSubSet(20,40);".into(),
        ] {
            v8::tc_scope!(let tc, scope);
            let source = v8::String::new(tc, &source).unwrap();
            let result = v8::Script::compile(tc, source, None).unwrap().run(tc);
            assert!(
                result.is_some(),
                "{:?}",
                tc.exception().map(|e| e.to_rust_string_lossy(tc))
            );
        }
        let source = v8::String::new(scope, "tests.length").unwrap();
        let count = v8::Script::compile(scope, source, None)
            .unwrap()
            .run(scope)
            .unwrap()
            .uint32_value(scope)
            .unwrap();
        let mut failures = Vec::new();
        for index in 0..count {
            let source = v8::String::new(scope, &format!("tests[{index}]")).unwrap();
            let result = v8::Script::compile(scope, source, None)
                .unwrap()
                .run(scope)
                .unwrap()
                .to_rust_string_lossy(scope);
            if result != "ok" {
                failures.push(result);
            }
        }
        eprintln!(
            "{count} diagnostic assertions in {:?}; {} failures",
            started.elapsed(),
            failures.len()
        );
        assert!(
            failures.is_empty(),
            "{:?}",
            &failures[..failures.len().min(8)]
        );
    }

    #[test]
    fn classic_compilation_failure_preserves_unentered_retry_and_syntax_error_identity() {
        initialize_v8();
        let dom = Rc::new(RefCell::new(
            html::parse("<script id=source type=application/json></script>")
                .into_runtime()
                .unwrap(),
        ));
        let node = dom.borrow().find_by_id("source").unwrap();
        let mut isolate = v8::Isolate::new(Default::default());
        v8::scope!(let scope,&mut isolate);
        let context = v8::Context::new(scope, Default::default());
        let scope = &mut v8::ContextScope::new(scope, context);
        let state = install_generated_bindings(scope, context, dom, RealmId(0), 1).unwrap();
        state.commit_location("https://example.test/").unwrap();
        let entries = Cell::new(0);
        FAIL_CLASSIC_COMPILATION_EMPTY.with(|failure| failure.set(true));
        assert!(
            execute_classic_script_with_started(
                scope,
                &state,
                node,
                "globalThis.runs=(globalThis.runs||0)+1",
                StartedClassicScriptInputs {
                    resource_name: "https://example.test/source.js",
                    muted_errors: false,
                    include_credentials: false,
                    referrer_policy: "no-referrer",
                    base_url: "https://example.test/",
                    started: &mut || entries.set(entries.get() + 1)
                }
            )
            .is_err()
        );
        assert_eq!(entries.get(), 0);
        assert!(state.current_script.get().is_none());
        execute_classic_script_with_started(scope, &state, node, "globalThis.runs=(globalThis.runs||0)+1;globalThis.errors=[];onerror=(message,url,line,column,error)=>{errors.push(error.name);return true}", StartedClassicScriptInputs { resource_name: "https://example.test/source.js", muted_errors: false, include_credentials: false, referrer_policy: "no-referrer", base_url: "https://example.test/", started: &mut ||entries.set(entries.get()+1) }).unwrap();
        assert_eq!(entries.get(), 1);
        execute_classic_script_with_started(
            scope,
            &state,
            node,
            "let =",
            StartedClassicScriptInputs {
                resource_name: "https://example.test/broken.js",
                muted_errors: false,
                include_credentials: false,
                referrer_policy: "no-referrer",
                base_url: "https://example.test/",
                started: &mut || entries.set(entries.get() + 1),
            },
        )
        .unwrap();
        assert_eq!(entries.get(), 2);
        let source = v8::String::new(
            scope,
            "runs===1&&errors.join(',')==='SyntaxError'&&document.currentScript===null",
        )
        .unwrap();
        assert!(
            v8::Script::compile(scope, source, None)
                .unwrap()
                .run(scope)
                .unwrap()
                .is_true()
        );
    }

