    #[cfg(feature = "historical-test-input")]
    #[test]
    fn native_input_changes_focus_visibility_but_synthetic_keyboard_events_do_not() {
        initialize_v8();
        let dom = Rc::new(RefCell::new(html::parse(
            "<body><button id='button'></button><input id='text'><div id='editor' contenteditable></div></body>"
        ).into_runtime().unwrap()));
        let mut isolate = v8::Isolate::new(Default::default());
        v8::scope!(let scope, &mut isolate);
        let context = v8::Context::new(scope, Default::default());
        let scope = &mut v8::ContextScope::new(scope, context);
        install_generated_bindings(scope, context, dom.clone(), RealmId(0), 1).unwrap();
        let historical_state = scope
            .get_current_context()
            .get_slot::<V8BindingState>()
            .unwrap();
        set_historical_input_authority(scope, &historical_state, true).unwrap();
        for (source, visible) in [
            (
                "globalThis.button=document.getElementById('button');button.focus()",
                true,
            ),
            ("button.blur();__oryn_focus_from_pointer(button)", false),
            (
                "button.dispatchEvent(new Event('keydown',{bubbles:true}))",
                false,
            ),
            (
                "const shortcut=new Event('keydown',{bubbles:true});shortcut.ctrlKey=true;__oryn_dispatch_user_input(button,'keydown',false,shortcut)",
                false,
            ),
            ("__oryn_dispatch_user_input(button,'keydown',false)", true),
            ("__oryn_focus_from_pointer(button)", true),
            ("button.blur();button.focus()", true),
            (
                "button.blur();__oryn_focus_from_pointer(button);button.blur();button.focus()",
                false,
            ),
            ("document.getElementById('text').focus()", true),
            (
                "__oryn_focus_from_pointer(document.getElementById('editor'))",
                true,
            ),
        ] {
            let code = v8::String::new(scope, source).unwrap();
            v8::Script::compile(scope, code, None)
                .unwrap()
                .run(scope)
                .unwrap();
            assert_eq!(dom.borrow().focus_visible(), visible, "{source}");
        }
    }

    #[test]
    fn visual_viewport_handlers_keep_registration_order_and_stop_immediate() {
        initialize_v8();
        let dom = Rc::new(RefCell::new(
            html::parse("<!doctype html><body></body>")
                .into_runtime()
                .unwrap(),
        ));
        let mut isolate = v8::Isolate::new(Default::default());
        v8::scope!(let scope,&mut isolate);
        let context = v8::Context::new(scope, Default::default());
        let scope = &mut v8::ContextScope::new(scope, context);
        let state = install_generated_bindings(scope, context, dom, RealmId(0), 1).unwrap();
        state.set_layout(BindingLayout {
            generated_nodes: Vec::new(),
            pseudo_styles: Default::default(),
            viewport: Some((400., 300.)),
            ..Default::default()
        });
        let source = r#"const view=visualViewport;let log=[],stop=false;
            view.addEventListener('resize',e=>{log.push('a');if(e.eventPhase!==2||e.currentTarget!==view||e.target!==view)throw Error('phase');if(stop)e.stopImmediatePropagation()});
            view.onresize=()=>log.push('old');
            view.addEventListener('resize',()=>log.push('b'));
            view.addEventListener('resize',()=>log.push('capture'),true);
            view.onresize=()=>log.push('handler');
            view.dispatchEvent(new Event('resize'));
            if(log.join(',')!=='capture,a,handler,b')throw Error('handler replacement order');
            log=[];view.onresize=null;view.onresize=()=>log.push('new');view.dispatchEvent(new Event('resize'));
            if(log.join(',')!=='capture,a,b,new')throw Error('handler re-registration order');
            log=[];stop=true;view.dispatchEvent(new Event('resize'));
            if(log.join(',')!=='capture,a')throw Error('immediate propagation');true;"#;
        let code = v8::String::new(scope, source).unwrap();
        assert!(
            v8::Script::compile(scope, code, None)
                .unwrap()
                .run(scope)
                .unwrap()
                .is_true()
        );
    }

