    #[test]
    fn touch_targets_retarget_on_frozen_shadow_path_and_clear_private_lists() {
        initialize_v8();
        let dom = Rc::new(RefCell::new(
            html::parse("<!doctype html><body><div id=host></div></body>")
                .into_runtime()
                .unwrap(),
        ));
        let mut isolate = v8::Isolate::new(Default::default());
        v8::scope!(let scope,&mut isolate);
        let context = v8::Context::new(scope, Default::default());
        let scope = &mut v8::ContextScope::new(scope, context);
        install_generated_bindings(scope, context, dom, RealmId(0), 1).unwrap();
        let source = r#"const host=document.getElementById('host'),root=host.attachShadow({mode:'closed'}),inner=document.createElement('span');root.append(inner);
            const point=new Touch({identifier:1,target:inner,clientX:15});
            const event=new TouchEvent('touchstart',{bubbles:true,composed:true,touches:[point],targetTouches:[point],changedTouches:[point]});
            let outer=null,inside=null;const seen=[];
            document.addEventListener('touchstart',e=>{outer=e.touches;seen.push(e.touches[0].target===host);host.remove()},true);
            inner.addEventListener('touchstart',e=>{inside=e.touches;seen.push(e.touches[0].target===inner&&e.touches[0]===e.changedTouches[0])});
            document.addEventListener('touchstart',e=>{seen.push(e.touches[0].target===host&&e.touches[0]===e.changedTouches[0])});
            inner.dispatchEvent(event);
            if(seen.length!==3||seen.some(value=>!value)||outer[0].target!==host||inside[0].target!==inner||event.touches[0].target!==host)throw Error('touch path snapshot');
            const confined=new TouchEvent('touchmove',{bubbles:true,composed:false,touches:[point],targetTouches:[point],changedTouches:[point]});
            let during=false;inner.addEventListener('touchmove',e=>{during=e.touches[0].target===inner});inner.dispatchEvent(confined);
            if(!during||confined.target!==null||confined.touches.length||confined.targetTouches.length||confined.changedTouches.length)throw Error('touch target cleanup');
            true;"#;
        let code = v8::String::new(scope, source).unwrap();
        assert!(
            v8::Script::compile(scope, code, None)
                .unwrap()
                .run(scope)
                .unwrap()
                .is_true()
        );
    }

    #[test]
    fn touch_constructors_convert_sequences_and_preserve_native_identity() {
        initialize_v8();
        let dom = Rc::new(RefCell::new(
            html::parse("<!doctype html><body><div id=t></div></body>")
                .into_runtime()
                .unwrap(),
        ));
        let mut isolate = v8::Isolate::new(Default::default());
        v8::scope!(let scope,&mut isolate);
        let context = v8::Context::new(scope, Default::default());
        let scope = &mut v8::ContextScope::new(scope, context);
        install_generated_bindings(scope, context, dom, RealmId(0), 1).unwrap();
        let source = r#"const target=document.getElementById('t');
            const point=new Touch({identifier:4294967297,target,clientX:12.5,radiusX:2,force:0.5});
            if(point.identifier!==1||point.clientX!==12.5||point.target!==target)throw Error('Touch conversion');
            const values=[point];const event=new TouchEvent('touchstart',{touches:values,targetTouches:new Set(values),changedTouches:values,ctrlKey:true,view:window,detail:3});
            values.length=0;
            if(event.isTrusted||event.view!==window||event.detail!==3||!event.ctrlKey||event.touches.length!==1||event.touches[0]!==point||event.targetTouches.item(0)!==point)throw Error('TouchEvent snapshot');
            if(event.touches[1]!==undefined||event.touches.item(1)!==null)throw Error('indexed absence');
            if(Reflect.set(event.touches,'0',null)||Reflect.set(event.touches,'2',point)||Reflect.deleteProperty(event.touches,'0')||!Reflect.deleteProperty(event.touches,'2'))throw Error('indexed mutation');
            if(Object.keys(event.touches).join(',')!=='0')throw Error('indexed enumeration');
            let closed=0;const bad={[Symbol.iterator](){return {next(){return {done:false,value:{}}},return(){closed++;throw Error('secondary')}}}};
            let rejected=false;try{new TouchEvent('touchmove',{touches:bad})}catch(e){rejected=e instanceof TypeError}
            if(!rejected||closed!==1)throw Error('sequence brand and IteratorClose');
            for(const init of [{target},{identifier:1},{identifier:1,target:{}},{identifier:1,target,clientX:Infinity}]){
                let rejected=false;try{new Touch(init)}catch(e){rejected=e instanceof TypeError}if(!rejected)throw Error('invalid Touch');
            }
            true;"#;
        let code = v8::String::new(scope, source).unwrap();
        assert!(
            v8::Script::compile(scope, code, None)
                .unwrap()
                .run(scope)
                .unwrap()
                .is_true()
        );
    }

    #[test]
    fn native_touch_lists_are_snapshots_and_cancellation_prevents_pan_and_click() {
        initialize_v8();
        let dom = Rc::new(RefCell::new(
            html::parse("<!doctype html><body><button id=t>Touch</button></body>")
                .into_runtime()
                .unwrap(),
        ));
        let t = dom.borrow().find_by_id("t").unwrap();
        let mut isolate = v8::Isolate::new(Default::default());
        v8::scope!(let scope,&mut isolate);
        let context = v8::Context::new(scope, Default::default());
        let scope = &mut v8::ContextScope::new(scope, context);
        let state = install_generated_bindings(scope, context, dom, RealmId(0), 1).unwrap();
        state.set_layout(BindingLayout {
            generated_nodes: Vec::new(),
            pseudo_styles: Default::default(),
            viewport: Some((100., 100.)),
            geometry: BTreeMap::from([(
                node_key(t),
                BindingGeometry::Available(BindingRect {
                    x: 0.,
                    y: 0.,
                    width: 80.,
                    height: 80.,
                }),
            )]),
            ..Default::default()
        });
        let source = r#"globalThis.log=[];globalThis.saved=null;
            const target=document.getElementById('t'), TouchClass=Touch, ListClass=TouchList, EventClass=TouchEvent;
            globalThis.Touch=globalThis.TouchEvent=function(){throw new Error('author constructor')};
            for(const type of ['touchstart','touchmove','touchend','touchcancel'])target.addEventListener(type,e=>{
                if(!(e instanceof EventClass)||!e.isTrusted||!(e.touches instanceof ListClass))throw new Error('event brand');
                const point=e.changedTouches.item(0);
                if(!(point instanceof TouchClass)||point!==e.changedTouches[0]||point.target!==target||e.changedTouches.item(99)!==null)throw new Error('touch identity');
                log.push([type,e.touches.length,e.targetTouches.length,e.changedTouches.length,point.identifier,point.clientY]);
                if(type==='touchstart'&&!saved)saved=e.touches;
                e.preventDefault();
            },{passive:false});
            for(const type of ['pointercancel','mousedown','mouseup','click'])target.addEventListener(type,()=>log.push([type]));"#;
        let code = v8::String::new(scope, source).unwrap();
        v8::Script::compile(scope, code, None)
            .unwrap()
            .run(scope)
            .unwrap();
        let mut input = NativePointerInput {
            device: NativePointerDevice::Touch,
            x: 30.,
            y: 40.,
            button: 0,
            buttons: 1,
            pressure: 0.5,
            ..Default::default()
        };
        dispatch_native_pointer(scope, &state, &input, NativePointerAction::Down).unwrap();
        input.y = 20.;
        input.button = -1;
        dispatch_native_pointer(scope, &state, &input, NativePointerAction::Move).unwrap();
        input.button = 0;
        input.buttons = 0;
        input.pressure = 0.;
        dispatch_native_pointer(scope, &state, &input, NativePointerAction::Up).unwrap();
        let code=v8::String::new(scope,"JSON.stringify(log)===JSON.stringify([['touchstart',1,1,1,1,40],['touchmove',1,1,1,1,20],['touchend',0,0,1,1,20]])&&saved.length===1&&saved[0].clientY===40").unwrap();
        assert!(
            v8::Script::compile(scope, code, None)
                .unwrap()
                .run(scope)
                .unwrap()
                .is_true()
        );
    }

