    #[test]
    fn native_pointer_drag_delivers_payload_and_consumes_release_click() {
        initialize_v8();
        for escape in [false, true] {
            let dom = Rc::new(RefCell::new(
                html::parse(
                    "<!doctype html><body><div id=s draggable=true></div><div id=t></div></body>",
                )
                .into_runtime()
                .unwrap(),
            ));
            let s = dom.borrow().find_by_id("s").unwrap();
            let t = dom.borrow().find_by_id("t").unwrap();
            let mut isolate = v8::Isolate::new(Default::default());
            v8::scope!(let scope,&mut isolate);
            let context = v8::Context::new(scope, Default::default());
            let scope = &mut v8::ContextScope::new(scope, context);
            let state = install_generated_bindings(scope, context, dom, RealmId(0), 1).unwrap();
            state.set_layout(BindingLayout {
                generated_nodes: Vec::new(),
                pseudo_styles: Default::default(),
                viewport: Some((100., 100.)),
                geometry: BTreeMap::from([
                    (
                        node_key(s),
                        BindingGeometry::Available(BindingRect {
                            x: 0.,
                            y: 0.,
                            width: 40.,
                            height: 40.,
                        }),
                    ),
                    (
                        node_key(t),
                        BindingGeometry::Available(BindingRect {
                            x: 50.,
                            y: 0.,
                            width: 40.,
                            height: 40.,
                        }),
                    ),
                ]),
                ..Default::default()
            });
            let code=v8::String::new(scope,"globalThis.log=[];globalThis.payload=null;const s=document.getElementById('s'),t=document.getElementById('t');s.addEventListener('dragstart',e=>{log.push('start');e.dataTransfer.setData('text/plain','native');e.dataTransfer.effectAllowed='copy'});s.addEventListener('pointercancel',()=>log.push('cancel'));s.addEventListener('dragend',()=>log.push('end'));t.addEventListener('dragover',e=>e.preventDefault());t.addEventListener('drop',e=>{payload=e.dataTransfer.getData('text/plain');log.push('drop');e.preventDefault()});document.addEventListener('click',()=>log.push('click'))").unwrap();
            v8::Script::compile(scope, code, None)
                .unwrap()
                .run(scope)
                .unwrap();
            let mut input = NativePointerInput {
                x: 20.,
                y: 20.,
                button: 0,
                buttons: 1,
                pressure: 0.5,
                ..Default::default()
            };
            dispatch_native_pointer(scope, &state, &input, NativePointerAction::Down).unwrap();
            input.x = 70.;
            input.button = -1;
            dispatch_native_pointer(scope, &state, &input, NativePointerAction::Move).unwrap();
            if escape {
                let key = NativeKeyboardInput {
                    key: vec![0xe00c],
                    down: true,
                    ..Default::default()
                };
                assert!(dispatch_native_keyboard(scope, &state, &key).unwrap());
            }
            input.button = 0;
            input.buttons = 0;
            input.pressure = 0.;
            dispatch_native_pointer(scope, &state, &input, NativePointerAction::Up).unwrap();
            let code = v8::String::new(
                scope,
                if escape {
                    "payload===null&&log.join(',')==='start,cancel,end'"
                } else {
                    "payload==='native'&&log.join(',')==='start,cancel,drop,end'"
                },
            )
            .unwrap();
            assert!(
                v8::Script::compile(scope, code, None)
                    .unwrap()
                    .run(scope)
                    .unwrap()
                    .is_true()
            );
        }
    }

    #[test]
    fn cssom_scroll_setters_respect_shared_native_coordinate_domain() {
        initialize_v8();
        let dom = Rc::new(RefCell::new(
            html::parse("<!doctype html><body></body>")
                .into_runtime()
                .unwrap(),
        ));
        let document = dom.borrow().document();
        let root = dom.borrow().first_element_child(document).unwrap().unwrap();
        let mut isolate = v8::Isolate::new(Default::default());
        v8::scope!(let scope,&mut isolate);
        let context = v8::Context::new(scope, Default::default());
        let scope = &mut v8::ContextScope::new(scope, context);
        let state = install_generated_bindings(scope, context, dom, RealmId(0), 1).unwrap();
        let limit = oryn_common::layout_domain::MAX_SCROLL_COORDINATE;
        state.set_layout(BindingLayout {
            generated_nodes: Vec::new(),
            pseudo_styles: Default::default(),
            viewport: Some((100., 100.)),
            viewport_scroll: Some(oryn_common::v4::PaintViewportScroll {
                scroll: oryn_common::v4::PaintScrollGeometry {
                    offset_x: 0.,
                    offset_y: 0.,
                    scrollport: oryn_common::v4::CssRect {
                        x: 0.,
                        y: 0.,
                        width: 100.,
                        height: 100.,
                    },
                    scrollable: oryn_common::layout_domain::SCROLL_DOMAIN,
                },
                style: BTreeMap::from([
                    ("overflow-x".into(), "auto".into()),
                    ("overflow-y".into(), "auto".into()),
                ]),
            }),
            ..Default::default()
        });
        let code = v8::String::new(
            scope,
            "document.documentElement.scrollLeft=-1e100;document.documentElement.scrollTop=1e100",
        )
        .unwrap();
        v8::Script::compile(scope, code, None)
            .unwrap()
            .run(scope)
            .unwrap();
        let bounds = native_scroll_bounds_in_layout(
            &state.dom.borrow(),
            &state.layout.borrow(),
            document,
            root,
        );
        assert_eq!(bounds.min, (-limit, -limit));
        assert_eq!(bounds.max, (limit - 100., limit - 100.));
        assert_eq!(
            state.scroll_offsets.borrow()[&root],
            (bounds.min.0, bounds.max.1)
        );
        let code=v8::String::new(scope,&format!("document.documentElement.scrollWidth==={}&&document.documentElement.scrollHeight==={}&&Number.isFinite(document.documentElement.scrollLeft)&&Number.isFinite(document.documentElement.scrollTop)",2.*limit,2.*limit)).unwrap();
        assert!(
            v8::Script::compile(scope, code, None)
                .unwrap()
                .run(scope)
                .unwrap()
                .is_true()
        );
    }

