    #[test]
    fn viewport_scrollbar_input_uses_identity_geometry_above_page_content() {
        initialize_v8();
        let dom = Rc::new(RefCell::new(
            html::parse("<!doctype html><body><button id=p>covered</button></body>")
                .into_runtime()
                .unwrap(),
        ));
        let p = dom.borrow().find_by_id("p").unwrap();
        let root = dom
            .borrow()
            .first_element_child(dom.borrow().document())
            .unwrap()
            .unwrap();
        let mut isolate = v8::Isolate::new(Default::default());
        v8::scope!(let scope,&mut isolate);
        let context = v8::Context::new(scope, Default::default());
        let scope = &mut v8::ContextScope::new(scope, context);
        let state = install_generated_bindings(scope, context, dom, RealmId(0), 1).unwrap();
        state.set_layout(BindingLayout {
            generated_nodes: Vec::new(),
            pseudo_styles: Default::default(),
            viewport: Some((100., 100.)),
            viewport_scroll: Some(oryn_common::v4::PaintViewportScroll {
                scroll: oryn_common::v4::PaintScrollGeometry {
                    offset_x: 0.,
                    offset_y: 0.,
                    scrollport: oryn_common::v4::CssRect {
                        x: 0.,
                        y: 0.,
                        width: 90.,
                        height: 80.,
                    },
                    scrollable: oryn_common::v4::CssRect {
                        x: -100.,
                        y: 0.,
                        width: 190.,
                        height: 180.,
                    },
                },
                style: BTreeMap::from([
                    ("overflow-x".into(), "scroll".into()),
                    ("overflow-y".into(), "scroll".into()),
                ]),
            }),
            geometry: BTreeMap::from([(
                node_key(p),
                BindingGeometry::Available(BindingRect {
                    x: 0.,
                    y: 0.,
                    width: 100.,
                    height: 100.,
                }),
            )]),
            ..Default::default()
        });
        let code=v8::String::new(scope,"globalThis.contentPresses=0;document.getElementById('p').addEventListener('pointerdown',()=>contentPresses++)").unwrap();
        v8::Script::compile(scope, code, None)
            .unwrap()
            .run(scope)
            .unwrap();
        let mut input = NativePointerInput {
            x: 10.,
            y: 90.,
            button: 0,
            buttons: 1,
            pressure: 0.5,
            ..Default::default()
        };
        dispatch_native_pointer(scope, &state, &input, NativePointerAction::Down).unwrap();
        assert_eq!(state.scroll_offsets.borrow().get(&root).unwrap().0, -90.);
        input.buttons = 0;
        input.pressure = 0.;
        dispatch_native_pointer(scope, &state, &input, NativePointerAction::Up).unwrap();
        input.x = 95.;
        input.y = 10.;
        input.buttons = 1;
        input.pressure = 0.5;
        dispatch_native_pointer(scope, &state, &input, NativePointerAction::Down).unwrap();
        input.y = 75.;
        input.button = -1;
        dispatch_native_pointer(scope, &state, &input, NativePointerAction::Move).unwrap();
        assert_eq!(state.scroll_offsets.borrow().get(&root).unwrap().1, 100.);
        input.button = 0;
        input.buttons = 0;
        input.pressure = 0.;
        dispatch_native_pointer(scope, &state, &input, NativePointerAction::Up).unwrap();
        let mut layout = state.layout.borrow().clone();
        layout
            .viewport_scroll
            .as_mut()
            .unwrap()
            .style
            .insert("overflow-y".into(), "hidden".into());
        state.set_layout(layout);
        perform_scroll(&state, root, (None, Some(0.)), false).unwrap();
        apply_pixel_wheel(&state, p, 0., 50.).unwrap();
        assert_eq!(
            state.scroll_offsets.borrow().get(&root).unwrap().1,
            0.,
            "hidden viewport overflow must reject wheel scrolling"
        );
        perform_scroll(&state, root, (None, Some(50.)), false).unwrap();
        assert_eq!(
            state.scroll_offsets.borrow().get(&root).unwrap().1,
            50.,
            "hidden overflow still allows script scrolling"
        );
        perform_scroll(&state, root, (None, Some(0.)), false).unwrap();
        scroll_element_into_view(&state, p, "end", "nearest", false).unwrap();
        assert_eq!(
            state.scroll_offsets.borrow().get(&root).unwrap().1,
            20.,
            "scrollIntoView must exclude the 20px viewport gutter"
        );
        let code = v8::String::new(scope, "contentPresses===0").unwrap();
        assert!(
            v8::Script::compile(scope, code, None)
                .unwrap()
                .run(scope)
                .unwrap()
                .is_true()
        );
    }

