    #[test]
    fn native_control_notifications_ignore_author_methods_and_stop_after_detachment() {
        initialize_v8();
        let dom = Rc::new(RefCell::new(
            html::parse("<!doctype html><body><input id=p><input id=q></body>")
                .into_runtime()
                .unwrap(),
        ));
        let p = dom.borrow().find_by_id("p").unwrap();
        let q = dom.borrow().find_by_id("q").unwrap();
        let mut isolate = v8::Isolate::new(Default::default());
        v8::scope!(let scope,&mut isolate);
        let context = v8::Context::new(scope, Default::default());
        let scope = &mut v8::ContextScope::new(scope, context);
        let state = install_generated_bindings(scope, context, dom, RealmId(0), 1).unwrap();
        let code=v8::String::new(scope,"globalThis.log=[];const p=document.getElementById('p'),q=document.getElementById('q');for(const node of [p,q])for(const type of ['input','change'])node.addEventListener(type,e=>{log.push([node.id,e.type,e.isTrusted,e.composed]);if(node===q&&type==='input')q.remove()});p.focus=()=>{throw Error('author focus')};EventTarget.prototype.dispatchEvent=()=>{throw Error('author dispatch')};globalThis.Event=()=>{throw Error('author event')}").unwrap();
        v8::Script::compile(scope, code, None)
            .unwrap()
            .run(scope)
            .unwrap();
        notify_native_control(scope, &state, p, NativeControlNotification::Focus).unwrap();
        assert_eq!(state.dom.borrow().focused(), Some(p));
        state
            .dom
            .borrow_mut()
            .set_user_control_value(p, "first", false)
            .unwrap();
        notify_native_control(scope, &state, p, NativeControlNotification::InputAndChange).unwrap();
        assert!(!state.dom.borrow_mut().take_control_change(p).unwrap());
        state
            .dom
            .borrow_mut()
            .set_user_control_value(q, "second", false)
            .unwrap();
        notify_native_control(scope, &state, q, NativeControlNotification::InputAndChange).unwrap();
        assert!(
            notify_native_control(scope, &state, q, NativeControlNotification::Change).is_err()
        );
        let code=v8::String::new(scope,"JSON.stringify(log)==='[[\"p\",\"input\",true,true],[\"p\",\"change\",true,false],[\"q\",\"input\",true,true]]'").unwrap();
        assert!(
            v8::Script::compile(scope, code, None)
                .unwrap()
                .run(scope)
                .unwrap()
                .is_true()
        );
    }

