    #[test]
    fn window_handler_error_convention_requires_error_type_and_error_event_brand() {
        check_global_event_prototype_script(
            r#"(()=>{
          const cases=[
            ['load',()=>new ErrorEvent('load',{cancelable:true}),false],
            ['error',()=>new Event('error',{cancelable:true}),false],
            ['error',()=>new ErrorEvent('error',{cancelable:true}),true]
          ];
          for(const [type,make,special] of cases){
            for(const result of [true,false,0,1,null,undefined,new Boolean(false)]){
              let count=0,args=null;const event=make();
              window['on'+type]=function(){count++;args=Array.from(arguments);return result};
              const allowed=dispatchEvent(event);
              const canceled=special?result===true:result===false;
              if(count!==1||args.length!==(special?5:1))throw Error('argument convention '+type);
              if(!special&&args[0]!==event)throw Error('ordinary event argument');
              if(allowed===canceled||event.defaultPrevented!==canceled)throw Error('return convention '+type);
              window['on'+type]=null;
            }
          }
          let args;
          const disguised=new ErrorEvent('load',{cancelable:true});
          Object.defineProperty(disguised,'type',{value:'error'});
          onload=function(){args=Array.from(arguments);return true};
          if(!dispatchEvent(disguised)||args.length!==1||args[0]!==disguised)throw Error('public type changed native convention');
          return true;
        })()"#,
        );
    }

