    #[test]
    fn character_and_fragment_constructors_bind_native_identity() {
        initialize_v8();
        let dom = Rc::new(RefCell::new(
            html::parse("<main></main>").into_runtime().unwrap(),
        ));
        let mut isolate = v8::Isolate::new(Default::default());
        v8::scope!(let scope, &mut isolate);
        let context = v8::Context::new(scope, Default::default());
        let scope = &mut v8::ContextScope::new(scope, context);
        install_generated_bindings(scope, context, dom, RealmId(0), 1).unwrap();
        let source = v8::String::new(scope, r#"
            (() => {
                const check = (ok, label) => { if (!ok) throw Error(label); };
                for (const [Constructor, type] of [[Text, 3], [Comment, 8]]) {
                    const node = new Constructor('a😀');
                    check(node instanceof Constructor && node instanceof Node && node.nodeType === type, 'native interface');
                    check(node.data === 'a😀' && node.length === 3 && node.ownerDocument === document && node.parentNode === null, 'initial state');
                    check(new Constructor().data === '' && new Constructor(undefined).data === '' && new Constructor(null).data === 'null', 'default conversion');
                    document.body.appendChild(node);
                    check(document.body.lastChild === node, 'wrapper identity');
                    class Derived extends Constructor {}
                    check(new Derived('x') instanceof Derived, 'derived construction');
                    const sentinel = {}; let caught;
                    try { new Constructor({toString() {throw sentinel;}}); } catch (e) {caught = e;}
                    check(caught === sentinel, 'conversion exception');
                }
                const fragment = new DocumentFragment();
                const text = fragment.appendChild(new Text('fragment'));
                check(fragment.ownerDocument === document && fragment.nodeType === 11, 'fragment identity');
                document.body.appendChild(fragment);
                check(fragment.childNodes.length === 0 && document.body.lastChild === text, 'fragment insertion');
                return true;
            })()
        "#).unwrap();
        assert!(
            v8::Script::compile(scope, source, None)
                .unwrap()
                .run(scope)
                .unwrap()
                .is_true()
        );
    }

    #[test]
    fn dom_parser_preserves_xml_document_mode_and_native_nodes() {
        initialize_v8();
        let dom = Rc::new(RefCell::new(
            html::parse("<main></main>").into_runtime().unwrap(),
        ));
        let mut isolate = v8::Isolate::new(Default::default());
        v8::scope!(let scope, &mut isolate);
        let context = v8::Context::new(scope, Default::default());
        let scope = &mut v8::ContextScope::new(scope, context);
        install_generated_bindings(scope, context, dom, RealmId(0), 1).unwrap();
        let source = v8::String::new(scope, r#"
            (() => {
                const check = (ok, label) => { if (!ok) throw Error(label); };
                const ns = 'http://www.w3.org/1999/xhtml';
                const span = document.createElementNS(ns, 'p:span');
                check(span instanceof HTMLSpanElement && span.cloneNode() instanceof HTMLSpanElement, 'span interface');
                check(document.createElementNS(ns, 'SPAN') instanceof HTMLUnknownElement, 'case-sensitive interface');
                for (const name of ['madeup', 'applet', 'font-face', 'X-widget']) {
                    check(document.createElementNS(ns, name) instanceof HTMLUnknownElement, 'unknown ' + name);
                }
                for (const name of ['div', 'acronym', 'x-widget', 'x-😍']) {
                    const element = document.createElementNS(ns, name);
                    check(element instanceof HTMLElement && !(element instanceof HTMLUnknownElement), 'known or custom ' + name);
                }
                check(!(document.createElementNS('urn:test', 'span') instanceof HTMLSpanElement), 'namespace-sensitive interface');
                const parser = new DOMParser();
                const xml = parser.parseFromString('<?before data?><p:Root xmlns:p="urn:test" p:Attr="v">a<![CDATA[b]]>c</p:Root>', 'application/xml');
                check(xml.contentType === 'application/xml' && xml.compatMode === 'CSS1Compat', 'XML metadata');
                const root = xml.documentElement;
                check(root.nodeName === 'p:Root' && root.localName === 'Root' && root.namespaceURI === 'urn:test', 'XML element');
                check(xml.createElement('MiXeD').nodeName === 'MiXeD', 'XML createElement');
                check(root instanceof Element && !(root instanceof SVGElement) && !(root instanceof HTMLElement), 'XML element interface');
                check(root.ownerDocument === xml && root.getAttributeNodeNS('urn:test', 'Attr').ownerDocument === xml, 'native ownership');
                check(xml.firstChild.nodeType === 7 && root.childNodes[1].nodeType === 4 && root.textContent === 'abc', 'XML character nodes');
                const subset=parser.parseFromString('<!DOCTYPE foo [ <!ENTITY x "y"> ]><foo>&x;</foo>','text/xml');
                check(subset.doctype.name==='foo'&&subset.doctype.publicId===''&&subset.doctype.systemId==='','internal subset doctype IDs');
                const serializer=new XMLSerializer();
                check(serializer.serializeToString(subset.documentElement)==='<foo>y</foo>','internal entity expansion');
                check(serializer.serializeToString(subset.doctype)==='<!DOCTYPE foo>','internal subset is not serialized');
                check(subset.doctype.ownerDocument===subset&&subset.documentElement.ownerDocument===subset,'internal subset node ownership');
                const invalid = parser.parseFromString('<a><b></a>', 'text/xml');
                check(invalid.contentType === 'text/xml' && invalid.documentElement.localName === 'parsererror', 'parse error');
                const html = parser.parseFromString('<P>hello', 'text/html');
                check(html.contentType === 'text/html' && html.body.firstChild.nodeName === 'P', 'HTML dispatch');
                return true;
            })()
        "#).unwrap();
        assert!(
            v8::Script::compile(scope, source, None)
                .unwrap()
                .run(scope)
                .unwrap()
                .is_true()
        );
    }

    #[test]
    fn attribute_creation_validates_namespaces_case_and_values() {
        initialize_v8();
        let dom = Rc::new(RefCell::new(
            html::parse("<main></main>").into_runtime().unwrap(),
        ));
        let mut isolate = v8::Isolate::new(Default::default());
        v8::scope!(let scope, &mut isolate);
        let context = v8::Context::new(scope, Default::default());
        let scope = &mut v8::ContextScope::new(scope, context);
        install_generated_bindings(scope, context, dom, RealmId(0), 1).unwrap();
        let source = v8::String::new(scope, r#"
            (() => {
                const check = (ok, label) => { if (!ok) throw Error(label); };
                const throws = (name, action) => {
                    try { action(); } catch (error) { check(error.name === name, name); return; }
                    throw Error('missing ' + name);
                };
                const attr = document.createAttribute('P:FLAG');
                check(attr instanceof Attr && attr.nodeType === 2 && attr.name === 'p:flag' && attr.localName === 'p:flag', 'literal HTML attribute');
                check(attr.prefix === null && attr.namespaceURI === null && attr.ownerElement === null && attr.ownerDocument === document, 'attribute ownership');
                check(attr.value === '', 'initial value'); attr.value = 'changed';
                check(attr.nodeValue === 'changed' && attr.textContent === 'changed', 'native value');
                const xml = document.implementation.createDocument(null, 'root');
                check(xml.createAttribute('P:FLAG').name === 'P:FLAG', 'XML case');
                const namespaced = xml.createAttributeNS('urn:test', 'P:FLAG');
                check(namespaced.name === 'P:FLAG' && namespaced.localName === 'FLAG' && namespaced.prefix === 'P' && namespaced.namespaceURI === 'urn:test' && namespaced.ownerDocument === xml, 'expanded name');
                check(document.createAttributeNS('', 'A').namespaceURI === null, 'empty namespace');
                for (const invalid of ['', 'x y', 'x/y', 'x=y', 'x>', '\0']) {
                    throws('InvalidCharacterError', () => document.createAttribute(invalid));
                    throws('InvalidCharacterError', () => document.body.setAttribute(invalid, 'v'));
                    throws('InvalidCharacterError', () => document.body.toggleAttribute(invalid, false));
                }
                throws('NamespaceError', () => document.createAttributeNS(null, 'p:x'));
                throws('NamespaceError', () => document.createAttributeNS('urn:x', 'xml:x'));
                throws('InvalidCharacterError', () => document.createAttributeNS(null, ':'));
                throws('InvalidCharacterError', () => document.implementation.createDocumentType('\0', '', ''));
                const element = document.createElement('i'); element.setAttribute('DATA-X', 'v');
                check(element.getAttribute('data-x') === 'v' && element.getAttribute('DATA-X') === 'v' && element.hasAttribute('DATA-X'), 'HTML lookup');
                element.removeAttribute('DATA-X'); check(!element.hasAttribute('data-x'), 'HTML removal');
                element.toggleAttribute('DATA-X'); check(element.getAttributeNames()[0] === 'data-x', 'HTML toggle');
                const xmlElement = xml.createElement('i'); xmlElement.setAttribute('DATA-X', 'v');
                check(xmlElement.getAttribute('data-x') === null && xmlElement.getAttribute('DATA-X') === 'v' && xmlElement.getAttributeNode('DATA-X').name === 'DATA-X', 'XML lookup');
                xmlElement.setAttributeNS('urn:test', 'P:FLAG', 'first');
                const existing = xmlElement.getAttributeNode('P:FLAG'); xmlElement.setAttribute('P:FLAG', 'second');
                check(existing === xmlElement.getAttributeNode('P:FLAG') && existing.namespaceURI === 'urn:test' && existing.localName === 'FLAG' && existing.value === 'second', 'namespace-preserving update');
                const sentinel = {}; let caught;
                try { element.setAttribute('bad name', {toString() {throw sentinel;}}); } catch (error) {caught = error;}
                check(caught === sentinel, 'conversion before validation');
                return true;
            })()
        "#).unwrap();
        assert!(
            v8::Script::compile(scope, source, None)
                .unwrap()
                .run(scope)
                .unwrap()
                .is_true()
        );
    }

    #[test]
    fn fresh_detached_leaves_preserve_owners_and_later_tree_edges() {
        initialize_v8();
        let dom = Rc::new(RefCell::new(
            html::parse("<main></main>").into_runtime().unwrap(),
        ));
        let mut isolate = v8::Isolate::new(Default::default());
        v8::scope!(let scope, &mut isolate);
        let context = v8::Context::new(scope, Default::default());
        let scope = &mut v8::ContextScope::new(scope, context);
        let state = install_generated_bindings(scope, context, dom.clone(), RealmId(0), 1).unwrap();
        let source = v8::String::new(
            scope,
            r#"
            (() => {
                const foreign = document.implementation.createHTMLDocument('owner');
                foreign.marker = 91;
                globalThis.leaves = Array.from({length: 4000}, (_, i) => {
                    const leaf = foreign.createElement('i'); leaf.marker = i; return leaf;
                });
                const parent = foreign.createElement('section'); parent.marker = 92;
                const sibling = foreign.createTextNode('sibling'); sibling.marker = 93;
                parent.append(leaves[0], sibling);
            })(); true
        "#,
        )
        .unwrap();
        assert!(
            v8::Script::compile(scope, source, None)
                .unwrap()
                .run(scope)
                .unwrap()
                .is_true()
        );
        // No observers are installed; finish the host mutation checkpoint so
        // removal-journal custody does not outlive the operation under test.
        {
            let mut dom = dom.borrow_mut();
            let mutations = dom.drain_mutations();
            dom.release_mutation_roots(&mutations).unwrap();
        }
        scope.low_memory_notification();
        state.process_weak_releases().unwrap();
        let source = v8::String::new(
            scope,
            r#"
            leaves.length === 4000 && leaves.every((leaf, i) =>
                leaf.marker === i && leaf.ownerDocument.marker === 91) &&
            leaves[0].parentNode.marker === 92 && leaves[0].nextSibling.marker === 93
        "#,
        )
        .unwrap();
        assert!(
            v8::Script::compile(scope, source, None)
                .unwrap()
                .run(scope)
                .unwrap()
                .is_true()
        );
        let source = v8::String::new(
            scope,
            "for(let i=1;i<leaves.length;i+=2)leaves[i]=null;true",
        )
        .unwrap();
        assert!(
            v8::Script::compile(scope, source, None)
                .unwrap()
                .run(scope)
                .unwrap()
                .is_true()
        );
        scope.low_memory_notification();
        state.process_weak_releases().unwrap();
        assert_eq!(dom.borrow().arena().iter().filter(|(_, record)|
            matches!(&record.kind, NodeKind::Element { name } if name.local.as_ref() == "i")).count(), 2000);
        let source = v8::String::new(scope, "delete globalThis.leaves; true").unwrap();
        assert!(
            v8::Script::compile(scope, source, None)
                .unwrap()
                .run(scope)
                .unwrap()
                .is_true()
        );
        scope.low_memory_notification();
        state.process_weak_releases().unwrap();
        assert!(!dom.borrow().arena().iter().any(|(_, record)|
            matches!(&record.kind, NodeKind::Element { name } if name.local.as_ref() == "i")));
    }

