    #[test]
    fn native_node_identity_uses_brand_owner_and_generation_without_author_getters() {
        initialize_v8();
        let dom = Rc::new(RefCell::new(
            html::parse("<div id=target><span></span></div>")
                .into_runtime()
                .unwrap(),
        ));
        let target = dom.borrow().find_by_id("target").unwrap();
        let mut isolate = v8::Isolate::new(Default::default());
        v8::scope!(let scope,&mut isolate);
        let a = v8::Context::new(scope, Default::default());
        let b = v8::Context::new(scope, Default::default());
        let state_a;
        let object;
        {
            let scope = &mut v8::ContextScope::new(scope, a);
            state_a = install_generated_bindings(scope, a, dom.clone(), RealmId(0), 1).unwrap();
            let source=v8::String::new(scope,r#"
                const node=document.getElementById('target');
                for(const key of ['nodeType','ownerDocument','isConnected','toJSON'])Object.defineProperty(node,key,{get(){throw Error('author getter')}});
                node
            "#).unwrap();
            let value = v8::Script::compile(scope, source, None)
                .unwrap()
                .run(scope)
                .unwrap();
            object = v8::Global::new(scope, value);
        }
        let scope = &mut v8::ContextScope::new(scope, b);
        let _state_b = install_generated_bindings(scope, b, dom, RealmId(1), 1).unwrap();
        let value = v8::Local::new(scope, &object);
        let (owner, node) = native_node_identity(scope, value).unwrap().unwrap();
        assert!(Rc::ptr_eq(&owner, &state_a));
        assert_eq!(node, target);
        let key = v8::String::new(scope, "foreign").unwrap();
        let global = b.global(scope);
        global.set(scope, key.into(), value);
        for code in [
            "Object.create(foreign)",
            "new Proxy(foreign,{get(){throw Error('trap')}})",
            "({get nodeType(){throw Error('getter')}})",
        ] {
            let source = v8::String::new(scope, code).unwrap();
            let ordinary = v8::Script::compile(scope, source, None)
                .unwrap()
                .run(scope)
                .unwrap();
            assert!(native_node_identity(scope, ordinary).unwrap().is_none());
        }
        state_a.retire_execution();
        assert!(native_node_identity(scope, value).is_err());
    }

