    #[test]
    fn node_arguments_respect_foreign_registry_identity_on_id_collision() {
        initialize_v8();
        let mut runtime = html::parse("<main></main>").into_runtime().unwrap();
        let local_node = runtime.create_text("local");
        let foreign_node = runtime.create_text("foreign");
        let dom = Rc::new(RefCell::new(runtime));
        let mut isolate = v8::Isolate::new(Default::default());
        v8::scope!(let scope, &mut isolate);
        let a = v8::Context::new(scope, Default::default());
        let b = v8::Context::new(scope, Default::default());
        let state_a;
        let local_id;
        {
            let scope = &mut v8::ContextScope::new(scope, a);
            state_a = install_generated_bindings(scope, a, dom.clone(), RealmId(0), 1).unwrap();
            let object = wrap_node(scope, &state_a, local_node).unwrap();
            local_id = receiver_wrapper_id(scope, object).unwrap();
        }
        let scope = &mut v8::ContextScope::new(scope, b);
        let state_b = install_generated_bindings(scope, b, dom, RealmId(1), 1).unwrap();
        let foreign = wrap_node(scope, &state_b, foreign_node).unwrap();
        assert_eq!(receiver_wrapper_id(scope, foreign).unwrap(), local_id);
        assert_eq!(
            argument_node(scope, &state_a, foreign.into()).unwrap(),
            foreign_node
        );
        let local = wrap_node(scope, &state_a, local_node).unwrap();
        assert_eq!(
            argument_node(scope, &state_b, local.into()).unwrap(),
            local_node
        );
    }

    #[test]
    fn foreign_selection_roots_shared_range_until_the_last_selection_releases_it() {
        initialize_v8();
        let dom = Rc::new(RefCell::new(
            html::parse("<main>text</main>").into_runtime().unwrap(),
        ));
        let mut isolate = v8::Isolate::new(Default::default());
        v8::scope!(let scope, &mut isolate);
        let a = v8::Context::new(scope, Default::default());
        let b = v8::Context::new(scope, Default::default());
        let state_a;
        {
            let scope = &mut v8::ContextScope::new(scope, a);
            state_a = install_generated_bindings(scope, a, dom.clone(), RealmId(0), 1).unwrap();
        }
        let scope = &mut v8::ContextScope::new(scope, b);
        let state_b = install_generated_bindings(scope, b, dom, RealmId(1), 1).unwrap();
        assert!(Rc::ptr_eq(&state_a.ranges, &state_b.ranges));
        assert!(Rc::ptr_eq(&state_a.range_objects, &state_b.range_objects));
        {
            v8::scope!(let inner, scope);
            let range = register_live_range(
                &state_a,
                RangeRecord {
                    start_container: state_a.document_root(),
                    start_offset: 0,
                    end_container: state_a.document_root(),
                    end_offset: 0,
                },
            )
            .unwrap();
            let object = new_stateful_object(inner, &state_a, "Range", range).unwrap();
            let marker = v8::Boolean::new(inner, true);
            set_object_property(inner, object, "marker", marker.into()).unwrap();
            state_a.selection_range.set(Some(range));
            state_b.selection_range.set(Some(range));
            refresh_range_wrapper_roots(inner, &state_b);
            assert!(Rc::ptr_eq(
                &state_a.rooted_range_selection_ids,
                &state_b.rooted_range_selection_ids
            ));
            // Collection may observe a temporary deselection before refresh.
            // Restoring the same selected IDs must still restore the roots.
            clear_selection(&state_a);
            clear_selection(&state_b);
            collect_dead_ranges(&state_a, false).unwrap();
            assert!(
                state_a.range_objects.borrow()[&range]
                    .selection_root
                    .is_none()
            );
            state_a.selection_range.set(Some(range));
            state_b.selection_range.set(Some(range));
            refresh_range_wrapper_roots(inner, &state_b);
            assert!(
                state_a.range_objects.borrow()[&range]
                    .selection_root
                    .is_some()
            );
        }
        scope.low_memory_notification();
        state_a.process_weak_releases().unwrap();
        assert_eq!(state_a.ranges.borrow().len(), 1);
        {
            v8::scope!(let inner, scope);
            let id = state_b.selection_range.get().unwrap();
            let object = new_stateful_object(inner, &state_b, "Range", id).unwrap();
            let key = v8::String::new(inner, "marker").unwrap();
            assert!(object.get(inner, key.into()).unwrap().is_true());
            assert!(Rc::ptr_eq(
                &binding_state_for_receiver(inner, object).unwrap(),
                &state_a
            ));
        }
        clear_selection(&state_a);
        refresh_range_wrapper_roots(scope, &state_a);
        scope.low_memory_notification();
        state_a.process_weak_releases().unwrap();
        assert_eq!(state_a.ranges.borrow().len(), 1);
        clear_selection(&state_b);
        refresh_range_wrapper_roots(scope, &state_a);
        scope.low_memory_notification();
        state_b.process_weak_releases().unwrap();
        apply_range_memory_accounting(scope, &state_b);
        assert!(state_a.ranges.borrow().is_empty());
        assert!(state_a.range_objects.borrow().is_empty());
        assert_eq!(state_a.range_memory_delta.get(), 0);
    }

    #[test]
    fn selection_extend_replaces_ranges_and_preserves_state_on_rejected_targets() {
        initialize_v8();
        let dom = Rc::new(RefCell::new(
            html::parse("<!doctype html><main>abcdef</main>")
                .into_runtime()
                .unwrap(),
        ));
        let mut isolate = v8::Isolate::new(Default::default());
        v8::scope!(let scope, &mut isolate);
        let context = v8::Context::new(scope, Default::default());
        let scope = &mut v8::ContextScope::new(scope, context);
        let state = install_generated_bindings(scope, context, dom, RealmId(0), 1).unwrap();
        let source = v8::String::new(scope, r#"
            (() => {
                const s = document.getSelection(), text = document.querySelector('main').firstChild;
                const detached = document.createTextNode('x');
                s.extend(detached, 999);
                if (s.rangeCount) throw Error('detached empty selection');
                function throws(name, fn) {
                    try { fn(); } catch (e) { if (e.name === name) return; throw e; }
                    throw Error('missing ' + name);
                }
                throws('InvalidStateError', () => s.extend(text, 0));
                s.collapse(text, 3);
                const old = s.getRangeAt(0);
                s.extend(text, 1);
                if (s.getRangeAt(0) === old || old.startOffset !== 3 || old.endOffset !== 3)
                    throw Error('old range mutated');
                if (s.anchorOffset !== 3 || s.focusOffset !== 1 || s.toString() !== 'bc')
                    throw Error('backward selection');
                const backward = s.getRangeAt(0);
                s.extend(text, 5);
                if (s.getRangeAt(0) === backward || backward.startOffset !== 1 || backward.endOffset !== 3)
                    throw Error('backward range mutated');
                const current = s.getRangeAt(0);
                s.extend(detached, 999);
                throws('IndexSizeError', () => s.extend(text, 999));
                throws('InvalidNodeTypeError', () => s.extend(document.doctype, 0));
                if (s.getRangeAt(0) !== current || s.anchorOffset !== 3 || s.focusOffset !== 5)
                    throw Error('rejected target changed selection');
                s.extend(text, 5);
                if (s.getRangeAt(0) === current) throw Error('same-point identity');
                const host = document.createElement('div');
                document.body.appendChild(host);
                const shadow = host.attachShadow({mode: 'open'});
                const shadowText = document.createTextNode('shadow');
                shadow.appendChild(shadowText);
                s.extend(shadowText, 2);
                if (s.anchorNode !== shadowText || s.focusNode !== shadowText ||
                    s.anchorOffset !== 2 || s.focusOffset !== 2 || !s.isCollapsed)
                    throw Error('different root must collapse at focus');
                s.extend(text, 3);
                for (let i = 0; i < 256; ++i) s.extend(text, i % 6);
            })(); true
        "#).unwrap();
        assert!(test_eval::run(scope, source).is_true());
        scope.low_memory_notification();
        state.process_weak_releases().unwrap();
        assert_eq!(state.ranges.borrow().len(), 1);
    }

    #[test]
    fn range_wrappers_preserve_selection_identity_and_release_collected_native_records() {
        initialize_v8();
        let dom = Rc::new(RefCell::new(
            html::parse("<main>text</main>").into_runtime().unwrap(),
        ));
        let mut isolate = v8::Isolate::new(Default::default());
        v8::scope!(let scope, &mut isolate);
        let context = v8::Context::new(scope, Default::default());
        let scope = &mut v8::ContextScope::new(scope, context);
        let state = install_generated_bindings(scope, context, dom, RealmId(0), 1).unwrap();
        let source = v8::String::new(scope, r#"
            (() => {
                const selected = new Range();
                selected.marker = 'kept';
                document.getSelection().addRange(selected);
                if (document.getSelection().getRangeAt(0) !== selected) throw Error('range identity');
                const text = document.createTextNode('detached');
                globalThis.frozen = new StaticRange({startContainer:text,startOffset:1,endContainer:text,endOffset:3});
                for (let i=0;i<4096;i++) { new Range(); document.createRange(); }
            })();
            true
        "#).unwrap();
        assert!(
            v8::Script::compile(scope, source, None)
                .unwrap()
                .run(scope)
                .unwrap()
                .is_true()
        );
        scope.low_memory_notification();
        state.process_weak_releases().unwrap();
        assert_eq!(state.ranges.borrow().len(), 2);
        assert_eq!(state.range_objects.borrow().len(), 2);
        let source = v8::String::new(scope, r#"
            document.getSelection().getRangeAt(0).marker === 'kept' &&
            document.getSelection().getRangeAt(0) === document.getSelection().getRangeAt(0) &&
            frozen.startContainer.data === 'detached' && frozen.startOffset === 1 && frozen.endOffset === 3
        "#).unwrap();
        assert!(
            v8::Script::compile(scope, source, None)
                .unwrap()
                .run(scope)
                .unwrap()
                .is_true()
        );
        let selected = state.selection_range.get().unwrap();
        let source = v8::String::new(
            scope,
            "document.getSelection().removeAllRanges();delete globalThis.frozen;true",
        )
        .unwrap();
        assert!(
            v8::Script::compile(scope, source, None)
                .unwrap()
                .run(scope)
                .unwrap()
                .is_true()
        );
        scope.low_memory_notification();
        state.process_weak_releases().unwrap();
        apply_range_memory_accounting(scope, &state);
        assert!(state.ranges.borrow().is_empty());
        assert!(state.static_ranges.borrow().is_empty());
        assert!(state.range_objects.borrow().is_empty());
        assert!(
            state
                .dom
                .borrow()
                .live_range(LiveRangeId(selected))
                .is_err()
        );
        assert_eq!(state.range_memory_delta.get(), 0);
    }

