    #[test]
    fn document_write_preserves_variadic_utf16_and_trusted_newline() {
        initialize_v8();
        let dom = Rc::new(RefCell::new(
            html::parse("<body></body>").into_runtime().unwrap(),
        ));
        let mut isolate = v8::Isolate::new(Default::default());
        v8::scope!(let scope,&mut isolate);
        let context = v8::Context::new(scope, Default::default());
        let scope = &mut v8::ContextScope::new(scope, context);
        let state = install_generated_bindings(scope, context, dom, RealmId(0), 1).unwrap();
        state.configure_trusted_types(TrustedTypesConfig {
            require_script: true,
            allowed_policy_names: ["default".into(), "trusted".into()].into(),
            ..TrustedTypesConfig::default()
        });
        let code=v8::String::new(scope,r#"(()=>{
          const seen=[];trustedTypes.createPolicy('default',{createHTML(value){seen.push(value);return value}});
          const policy=trustedTypes.createPolicy('trusted',{createHTML:value=>value});
          const copy=document.implementation.createHTMLDocument('');copy.open();
          const prefix='\u{f0000}oryn-wtf16:[55296]';
          copy.write(policy.createHTML('<p id=a>\ud800'),policy.createHTML('X\udc00</p>'));
          copy.writeln(policy.createHTML('<p id=b>'),policy.createHTML(prefix+'</p>'));
          if(seen.length)throw Error('trusted concatenation invoked default');
          copy.write(policy.createHTML('<p id=c>\ud801'),{toString(){return 'Y\udc01'}},'</p>');
          copy.close();
          return seen.length===1&&seen[0]==='<p id=c>\ud801Y\udc01</p>'
            &&copy.getElementById('a').textContent==='\ud800X\udc00'
            &&copy.getElementById('b').textContent===prefix
            &&copy.getElementById('c').textContent==='\ud801Y\udc01'
            &&copy.getElementById('b').nextSibling.data==='\n';
        })()"#).unwrap();
        assert!(
            v8::Script::compile(scope, code, None)
                .unwrap()
                .run(scope)
                .unwrap()
                .is_true()
        );
    }

    #[test]
    fn document_write_small_dispatch_preserves_reentrant_conversion_and_receiver_checks() {
        check_global_event_prototype_script(
            r#"(()=>{
          const copy=document.implementation.createHTMLDocument('');copy.open();
          const order=[];
          function write(depth){copy.write({toString(){order.push('enter'+depth);
            if(depth)write(depth-1);order.push('leave'+depth);return '<i>'+depth+'</i>'}})}
          write(8);copy.writeln('<b>last</b>');copy.close();
          const expected=[];for(let i=8;i>=0;i--)expected.push('enter'+i);
          for(let i=0;i<=8;i++)expected.push('leave'+i);
          if(order.join(',')!==expected.join(','))throw Error('conversion order');
          if(Array.from(copy.querySelectorAll('i'),node=>node.textContent).join(',')!=='0,1,2,3,4,5,6,7,8')throw Error('nested publication');
          let converted=false,invalid=false;
          try{Document.prototype.write.call({}, {toString(){converted=true;return 'bad'}})}catch(error){invalid=error instanceof TypeError}
          return invalid&&!converted&&copy.querySelector('b').nextSibling.data==='\n';
        })()"#,
        );
    }

