    #[test]
    fn document_write_implicitly_opens_and_replaces_the_previous_tree() {
        check_global_event_prototype_script(
            r#"(()=>{
          const target=document.implementation.createHTMLDocument('old');
          const oldRoot=target.documentElement;target.body.textContent='old contents';
          const failure={};let caught;
          try{target.write({toString(){throw failure}})}catch(error){caught=error}
          if(caught!==failure||target.documentElement!==oldRoot)throw Error('conversion failure opened stream');
          target.write('<p id=new>');target.write('replacement','</p>');target.close();
          if(target.documentElement===oldRoot||oldRoot.parentNode!==null)throw Error('previous tree retained');
          if(target.body.textContent!=='replacement')throw Error('write appended to previous document');
          const returned=target.open();
          if(returned!==target||target.documentElement!==null)throw Error('open did not remove all children');
          target.write('discarded');target.open();target.write('<p>final</p>');target.close();
          return target.body.textContent==='final';
        })()"#,
        );
    }

    #[test]
    fn document_open_capacity_rejection_preserves_incumbent_listeners_and_tree() {
        check_global_event_prototype_script(
            r#"(()=>{
          const streams=[];
          for(let i=0;i<1024;i++){
            const target=document.implementation.createHTMLDocument('');
            target.open();streams.push(target);
          }
          const root=document.documentElement,body=document.body,calls=[];
          document.addEventListener('probe',()=>calls.push('document'));
          window.addEventListener('probe',()=>calls.push('window'));
          body.addEventListener('probe',()=>calls.push('body'));
          let rejected=false;
          try{document.open()}catch(error){rejected=true}
          if(!rejected)throw Error('stream capacity was not enforced');
          if(document.documentElement!==root||document.body!==body)throw Error('rejected open replaced tree');
          document.dispatchEvent(new Event('probe'));
          window.dispatchEvent(new Event('probe'));
          body.dispatchEvent(new Event('probe'));
          if(calls.join(',')!=='document,window,body')throw Error('rejected open removed listeners');
          // Reopening an admitted stream remains legal at capacity.
          streams[0].open();streams[0].write('<p>retained slot</p>');streams[0].close();
          if(streams[0].body.textContent!=='retained slot')throw Error('existing stream lost its slot');
          for(const target of streams.slice(1))target.close();
          return true;
        })()"#,
        );
    }

    #[test]
    fn document_open_clears_replaced_tree_and_window_listeners_only() {
        check_global_event_prototype_script(
            r#"(()=>{
          const calls=[],oldBody=document.body;
          oldBody.innerHTML='<button onclick="throw Error(\'old content handler reactivated\')">old</button><div id=host></div>';
          const host=document.getElementById('host');
          const shadow=host.attachShadow({mode:'closed'});shadow.innerHTML='<button>shadow</button>';
          const shadowButton=shadow.firstChild;
          const detached=document.createElement('button');
          const inert=document.implementation.createHTMLDocument('');const other=inert.body;
          for(const [target,label] of [[document,'document'],[window,'window'],[oldBody,'body'],
              [shadowButton,'shadow'],[detached,'detached'],[other,'other']]){
            target.addEventListener('probe',()=>calls.push(label));
          }
          oldBody.onclick=()=>calls.push('old click');window.onload=()=>calls.push('old load');
          document.open();
          for(const target of [document,window,oldBody,shadowButton,detached,other])target.dispatchEvent(new Event('probe'));
          oldBody.click();oldBody.querySelector('button').click();window.dispatchEvent(new Event('load'));
          if(calls.join(',')!=='detached,other')throw Error('listener cleanup boundary: '+calls);
          if(oldBody.querySelector('button').getAttribute('onclick')===null)throw Error('content attribute removed');
          if(onload!==null||oldBody.onclick!==null)throw Error('handler slot not cleared');
          document.write('<p>replacement</p>');document.close();
          return document.body.textContent==='replacement';
        })()"#,
        );
    }

    #[test]
    fn xml_documents_reject_html_stream_operations_without_mutation() {
        check_global_event_prototype_script(
            r#"(()=>{
          for(const namespace of [null,'http://www.w3.org/1999/xhtml']){
            const xml=document.implementation.createDocument(namespace,'root');
            const root=xml.documentElement;root.textContent='original';
            for(const method of ['open','write','writeln','close']){
              let caught;try{xml[method]()}catch(error){caught=error}
              if(!(caught instanceof DOMException)||caught.name!=='InvalidStateError')throw Error(method+' allowed XML stream');
              if(xml.documentElement!==root||root.textContent!=='original')throw Error(method+' mutated XML');
            }
            let converted=0,caught;
            try{xml.write({toString(){converted++;return '<changed/>'}})}catch(error){caught=error}
            if(converted!==1||caught.name!=='InvalidStateError')throw Error('union conversion order');
            const failure={};try{xml.writeln({toString(){throw failure}})}catch(error){caught=error}
            if(caught!==failure)throw Error('conversion exception replaced');
          }
          return true;
        })()"#,
        );
    }

