/// Host-only read of native records and traced template links. No author
/// methods or getters participate in extraction.
pub fn serialize_native_extraction(
    scope: &mut v8::PinScope,
    state: &Rc<V8BindingState>,
    roots: &[NodeId],
) -> Result<String, V8BindingError> {
    if state.execution_retired() || state.execution_suspended() {
        return Err(V8BindingError::Allocation(
            "extraction document retired or suspended",
        ));
    }
    let html = {
        let dom = state.dom.borrow();
        let document = state.document_root();
        let live = dom
            .arena()
            .descendants_inclusive(document)?
            .into_iter()
            .collect::<BTreeSet<_>>();
        for root in roots {
            if !live.contains(root) || dom.arena().node_document(*root)? != Some(document) {
                return Err(V8BindingError::Allocation(
                    "extraction root outside active document",
                ));
            }
        }
        dom.arena()
            .get(document)?
            .document_metadata
            .as_ref()
            .is_none_or(|metadata| metadata.is_html)
    };
    let mut units = Vec::new();
    for root in roots {
        let text = if html {
            template_links::serialize_html(scope, state, *root)
        } else {
            template_links::serialize_xml(scope, state, *root)
        }?;
        units.extend(oryn_dom::dom_string::units(&text));
    }
    Ok(oryn_dom::dom_string::from_units(&units))
}

