/// Native focus authority for host cross-realm keyboard routing.
pub fn native_keyboard_focus_document(
    state: &V8BindingState,
) -> Result<Option<NodeId>, V8BindingError> {
    if state.execution_retired() {
        return Err(V8BindingError::Allocation("retired keyboard document"));
    }
    let dom = state.dom.borrow();
    let Some(focused) = dom.focused() else {
        return Ok(None);
    };
    let Some(document) = dom.arena().node_document(focused)? else {
        return Ok(None);
    };
    let mut owner = document;
    let mut seen = BTreeSet::new();
    while owner != state.document_root() {
        if !seen.insert(owner) {
            return Err(V8BindingError::Allocation("cyclic keyboard embedding"));
        }
        let host = dom
            .arena()
            .document_host(owner)
            .ok_or(V8BindingError::Allocation(
                "keyboard focus outside selected document",
            ))?;
        owner = dom
            .arena()
            .node_document(host)?
            .ok_or(V8BindingError::Allocation("retired keyboard embedding"))?;
    }
    Ok(Some(document))
}

