    #[test]
    fn range_stringification_joins_code_units_across_node_boundaries() {
        let mut dom = DomRuntime::new();
        let host = dom.create_element("div");
        let high = dom.create_text(oryn_dom::dom_string::from_units(&[0xd83d]));
        let low = dom.create_cdata_section(oryn_dom::dom_string::from_units(&[0xde00]));
        let literal = format!("{}[65]", oryn_dom::dom_string::PREFIX);
        let literal_units = literal.encode_utf16().collect::<Vec<_>>();
        let tail = dom.create_text(oryn_dom::dom_string::from_units(&literal_units));
        for node in [high, low, tail] {
            dom.append_child(host, node).unwrap();
        }
        let pair = RangeRecord {
            start_container: high,
            start_offset: 0,
            end_container: low,
            end_offset: 1,
        };
        assert_eq!(
            oryn_dom::dom_string::units(&range_text(&dom, &pair).unwrap()),
            vec![0xd83d, 0xde00]
        );
        let partial = RangeRecord {
            start_container: high,
            start_offset: 1,
            ..pair
        };
        assert_eq!(
            oryn_dom::dom_string::units(&range_text(&dom, &partial).unwrap()),
            vec![0xde00]
        );
        let whole = RangeRecord {
            start_container: host,
            start_offset: 0,
            end_container: host,
            end_offset: 3,
        };
        let mut expected = vec![0xd83d, 0xde00];
        expected.extend(literal_units);
        assert_eq!(
            oryn_dom::dom_string::units(&range_text(&dom, &whole).unwrap()),
            expected
        );
        assert_eq!(
            oryn_dom::dom_string::units(&dom.arena().text_content(high).unwrap()),
            vec![0xd83d]
        );
    }
