#[cfg(test)]
mod native_extraction_ownership_tests {
    use super::*;
    #[test]
    fn extraction_follows_external_templates_and_rejects_detached_or_suspended_roots() {
        tests::initialize_v8();
        let mut isolate = v8::Isolate::new(Default::default());
        v8::scope!(let scope,&mut isolate);
        let source_context = v8::Context::new(scope, Default::default());
        let (source_state, source_document) = {
            let scope = &mut v8::ContextScope::new(scope, source_context);
            let dom=Rc::new(RefCell::new(html::parse("<body><template id=t><template><span>A &amp; B</span></template><br></template></body>").into_runtime().unwrap()));
            let state =
                install_generated_bindings(scope, source_context, dom, RealmId(148), 1).unwrap();
            let document = wrap_node(scope, &state, state.document_root()).unwrap();
            (state, v8::Global::new(scope, document))
        };
        let context = v8::Context::new(scope, Default::default());
        let scope = &mut v8::ContextScope::new(scope, context);
        let dom = Rc::new(RefCell::new(
            html::parse("<body></body>").into_runtime().unwrap(),
        ));
        let state = install_generated_bindings(scope, context, dom, RealmId(149), 1).unwrap();
        assert_ne!(
            source_state.dom.borrow().arena().id(),
            state.dom.borrow().arena().id()
        );
        let document = v8::Local::new(scope, &source_document);
        let key = v8::String::new(scope, "sourceDocument").unwrap();
        context
            .global(scope)
            .set(scope, key.into(), document.into());
        let source=v8::String::new(scope,r#"(()=>{
            const template=sourceDocument.querySelector('#t');
            const content=template.content;
            document.body.append(document.adoptNode(template));
            if(template.content!==content)throw Error('lost content identity');
            Object.defineProperty(template,'outerHTML',{get(){throw Error('author getter invoked');}});
        })()"#).unwrap();
        v8::Script::compile(scope, source, None)
            .unwrap()
            .run(scope)
            .unwrap();
        let result = serialize_native_extraction(scope, &state, &[state.document_root()]).unwrap();
        assert!(
            result.contains(
                "<template id=\"t\"><template><span>A &amp; B</span></template><br></template>"
            ),
            "{result}"
        );
        let detached = state.dom.borrow_mut().create_element("div");
        assert!(serialize_native_extraction(scope, &state, &[detached]).is_err());
        state.execution_suspended.set(true);
        assert!(serialize_native_extraction(scope, &state, &[state.document_root()]).is_err());
        state.execution_suspended.set(false);
        assert_eq!(
            serialize_native_extraction(scope, &state, &[state.document_root()]).unwrap(),
            result
        );
    }
}

/// Broadcast native resize observations during the rendering update loop.
pub fn broadcast_resize_observers(
    scope: &mut v8::PinScope,
    state: &Rc<V8BindingState>,
) -> Result<bool, V8BindingError> {
    resize_observers::broadcast(scope, state)
}

pub struct UnloadGuard(std::rc::Weak<V8BindingState>);
impl Drop for UnloadGuard {
    fn drop(&mut self) {
        if let Some(state) = self.0.upgrade() {
            state
                .unload_counter
                .set(state.unload_counter.get().saturating_sub(1));
        }
    }
}

pub fn sample_intersection_observers(
    scope: &mut v8::PinScope,
    state: &Rc<V8BindingState>,
) -> Result<(), V8BindingError> {
    intersection_observers::sample(scope, state)
}
pub fn deliver_intersection_observer(
    scope: &mut v8::PinScope,
    state: &Rc<V8BindingState>,
) -> Result<bool, V8BindingError> {
    intersection_observers::poll(scope, state)
}

