#[cfg(test)]
mod request_clone_borrow_tests {
    use super::*;
    #[test]
    fn request_and_response_clones_preserve_metadata_with_independent_headers() {
        tests::initialize_v8();
        let mut isolate = v8::Isolate::new(Default::default());
        v8::scope!(let scope,&mut isolate);
        let context = v8::Context::new(scope, Default::default());
        let scope = &mut v8::ContextScope::new(scope, context);
        let dom = Rc::new(RefCell::new(
            oryn_dom::html::parse("<body></body>")
                .into_runtime()
                .unwrap(),
        ));
        let state = install_generated_bindings(scope, context, dom, RealmId(0), 1).unwrap();
        assert!(test_eval::eval(scope,r#"(()=>{
            const check=(x,m)=>{if(!x)throw Error(m)};
            const controller=new AbortController();
            const source=new Request('https://example.test/path',{method:'POST',body:'payload',keepalive:true,headers:{'x-source':'original'},signal:controller.signal});
            const clone=source.clone();
            check(clone.keepalive&&clone.method==='POST'&&clone.url===source.url,'metadata');
            clone.headers.set('x-source','clone');check(source.headers.get('x-source')==='original','request headers independent');
            check(clone.body!==source.body&&!source.bodyUsed&&!clone.bodyUsed,'request tee');
            controller.abort('reason');check(source.signal.aborted&&clone.signal.aborted&&clone.signal.reason==='reason','following signal');
            const response=new Response('body',{status:201,headers:{'x-source':'original'}}),copy=response.clone();
            copy.headers.set('x-source','copy');check(response.headers.get('x-source')==='original'&&copy.status===201,'response metadata');
            check(copy.body!==response.body&&!response.bodyUsed&&!copy.bodyUsed,'response tee');
            globalThis.cloneFixture=clone;return true;
        })()"#).is_true());
        // Internal source classification must survive clone independently of
        // exposed metadata; later Fetch/Range policy depends on these flags.
        let records = state.platform_objects.borrow();
        let requests = records
            .values()
            .filter_map(|record| {
                if let PlatformObjectRecord::Request(request) = record {
                    Some(request)
                } else {
                    None
                }
            })
            .collect::<Vec<_>>();
        assert_eq!(requests.len(), 2);
        assert!(requests.iter().all(|request| request.keepalive
            && request.body_source_known
            && !request.privileged_range));
    }
}

#[cfg(test)]
mod node_base_uri_regressions {
    use super::*;

    fn fixture(scope: &mut v8::PinScope) -> Rc<V8BindingState> {
        let dom = Rc::new(RefCell::new(
            oryn_dom::html::parse(
                "<head><base href='assets/'></head><body><section id=shadow></section></body>",
            )
            .into_runtime()
            .unwrap(),
        ));
        let context = scope.get_current_context();
        let state = install_generated_bindings(scope, context, dom, RealmId(0), 1).unwrap();
        state
            .commit_location("https://example.test/old/document")
            .unwrap();
        state
    }

    #[test]
    fn node_base_uri_is_inherited_readonly_and_receiver_branded() {
        super::tests::initialize_v8();
        let mut isolate = v8::Isolate::new(Default::default());
        v8::scope!(let scope, &mut isolate);
        let context = v8::Context::new(scope, Default::default());
        let scope = &mut v8::ContextScope::new(scope, context);
        let _state = fixture(scope);
        assert!(super::test_eval::eval(scope, r#"(() => {
            const d=Object.getOwnPropertyDescriptor(Node.prototype,'baseURI');
            if(!d||typeof d.get!=='function'||d.set!==undefined||!d.enumerable||!d.configurable)return false;
            if(Object.hasOwn(Document.prototype,'baseURI'))return false;
            const nodes=[document,document.body,document.createTextNode('text'),document.createComment('comment'),document.createDocumentFragment(),shadow.attachShadow({mode:'open'}),document.createAttribute('data-test')];
            for(const node of nodes){
                if(node.baseURI!=='https://example.test/old/assets/'||d.get.call(node)!==node.baseURI)return false;
                if(Reflect.set(node,'baseURI','https://wrong.test/'))return false;
            }
            for(const receiver of [{},null,undefined,new Proxy(document.body,{})]){
                try{d.get.call(receiver);return false}catch(error){if(!(error instanceof TypeError))return false;}
            }
            document.querySelector('base').href='/changed/';
            return nodes.every(node=>node.baseURI==='https://example.test/changed/');
        })()"#).is_true());
    }

    #[test]
    fn borrowed_base_uri_follows_owner_document_and_adoption_without_new_wrapper() {
        super::tests::initialize_v8();
        let mut isolate = v8::Isolate::new(Default::default());
        v8::scope!(let scope, &mut isolate);
        let context = v8::Context::new(scope, Default::default());
        let scope = &mut v8::ContextScope::new(scope, context);
        let _state = fixture(scope);
        assert!(super::test_eval::eval(scope, r#"(() => {
            const get=Object.getOwnPropertyDescriptor(Node.prototype,'baseURI').get;
            const other=document.implementation.createHTMLDocument('other');
            other.head.innerHTML='<base href="https://foreign.test/resources/">';
            const node=other.createElement('span'),text=other.createTextNode('text');
            node.append(text);other.body.append(node);
            if(get.call(node)!=='https://foreign.test/resources/'||get.call(text)!==node.baseURI)return false;
            node.remove();
            if(get.call(node)!=='https://foreign.test/resources/')return false;
            const saved=node,adopted=document.adoptNode(node);
            if(adopted!==saved||node.ownerDocument!==document||text.ownerDocument!==document)return false;
            if(get.call(node)!=='https://example.test/old/assets/'||get.call(text)!==node.baseURI)return false;
            document.querySelector('base').remove();
            return get.call(node)==='https://example.test/old/document'&&get.call(other)==='https://foreign.test/resources/';
        })()"#).is_true());
    }
}

#[cfg(test)]
mod executable_checkpoint_pending_tests {
    use super::*;

    #[test]
    fn local_queue_witness_is_nonconsuming_and_borrows_are_conservative() {
        tests::initialize_v8();
        let mut isolate = v8::Isolate::new(Default::default());
        v8::scope!(let scope, &mut isolate);
        let context = v8::Context::new(scope, Default::default());
        let scope = &mut v8::ContextScope::new(scope, context);
        let dom = Rc::new(RefCell::new(
            html::parse("<body></body>").into_runtime().unwrap(),
        ));
        let state = install_generated_bindings(scope, context, dom.clone(), RealmId(0), 1).unwrap();
        let before = state.executable_checkpoint_identity().unwrap();
        state
            .pending_referrer_policies
            .borrow_mut()
            .push_back("no-referrer".into());
        assert_eq!(state.executable_checkpoint_identity(), Some(before));
        assert!(state.has_pending_executable_checkpoint_work(true));
        assert!(state.has_pending_executable_checkpoint_work(true));
        assert_eq!(state.take_pending_referrer_policies(), vec!["no-referrer"]);
        let held = state.pending_dynamic_scripts.borrow_mut();
        assert!(state.has_pending_executable_checkpoint_work(true));
        drop(held);
        let held = dom.borrow_mut();
        assert!(state.executable_checkpoint_identity().is_none());
        assert!(state.has_pending_executable_checkpoint_work(true));
        drop(held);
        assert_eq!(state.executable_checkpoint_identity(), Some(before));
        state.closed_document_stream.set(Some((3, 4)));
        assert!(state.has_pending_executable_checkpoint_work(true));
        assert_eq!(state.take_closed_document_stream(), Some((3, 4)));
    }
}
